COPY public."Articles" (id, slug, title, author_id, cover_path, cover_blur, excerpt, content_blocks, published_at, created_at, cover_width, cover_height, title_id) FROM stdin;
1	mrd6-zhelaniya-rebenka-ostalis-na-potom	Желания ребёнка остались на потом	40	mrd6/mrd6-zhelaniya-rebenka-ostalis-na-potom.jpg	data:image/jpeg;base64,	Ещё перед тем, как начали бить куранты, вдруг забилось сердечко маленького Славы. Окна в их тёплой трёшке на девятом этаже слегка затрещали: во дворе начался салют. Люди на улице не стали дожидаться окончания телевизионн	[{"kind": "image", "path": "mrd6/mrd6-zhelaniya-rebenka-ostalis-na-potom.jpg", "caption": "Иллюстрация Лены Солнцевой"}, {"kind": "paragraph", "text": "Ещё перед тем, как начали бить куранты, вдруг забилось сердечко маленького Славы. Окна в их тёплой трёшке на девятом этаже слегка затрещали: во дворе начался салют. Люди на улице не стали дожидаться окончания телевизионного поздравления, а приняли решение отметить праздник прямо сейчас — почему бы и нет? Что такое «принять решение», Слава пока не знал — ему всего четыре."}, {"kind": "paragraph", "text": "Огни сверкали. То было не похоже ни на что другое в жизни ребёнка — и он загорелся желанием всё это как следует разглядеть."}, {"kind": "paragraph", "text": "— Интересно, ой как интересно, — пищал Славка, сидя за общим столом, но никто не слышал."}, {"kind": "paragraph", "text": "Его окружали родственники, но мальчик, кроме мамы и папы, никого не помнил, хотя всем его детская мордашка знакома. Рядом друзья, не его, а опять же родительские. Все эти люди сейчас заняты тем, что передают друг другу шариковую ручку. Нужно написать на бумажке идеально сформулированное желание, а потом запить пепел доброй порцией игристого ровно в двенадцать."}, {"kind": "paragraph", "text": "Все эти тёти и дяди выше Славы, он в доме сегодня единственный ребёнок. Празднично накрытый стол по центру кухни, шумный телевизор на стене под потолком. Слава сидел там же, но все смотрели на телевизор."}, {"kind": "paragraph", "text": "А ему неймётся — ёрзает. И чем больше взрывов звучит на улице, тем сильнее сжимаются в нетерпении его кулачки, тем чаще его жопка выдаёт вензеля на стуле в детском нетерпении."}, {"kind": "paragraph", "text": "Он ещё раз бросил жалобный взгляд на маму, и та наконец обратила на ребёнка внимание. Пьяная она, но легко связала шум за окном и горящие глаза сына. Наклонившись к его светлой головушке, тихо произнесла:"}, {"kind": "paragraph", "text": "— Давай. Беги, только тихо."}, {"kind": "paragraph", "text": "Слава в ту же секунду рванул что есть мочи, и в общей человеческой трескотне не услышал, как позади рухнул табурет, и отец что-то прокричал."}, {"kind": "paragraph", "text": "По скользкому линолеуму, по пушистому тёплому ковру он добежал до родительской спальни, где раздвинул шторы и запрыгнул на подоконник. Его зрачки, расширенные из-за недостатка света в комнате, впитывали в себя каждую искорку божественного праздника за стеклом."}, {"kind": "paragraph", "text": "Что значит «божественный», он тоже ещё не понимал."}, {"kind": "paragraph", "text": "Огни отражались в чёрных глазках, детская улыбка, умиляющая любого родителя, уже секунд десять не спадала. На синем снегу во дворе чёрные точки запускали огненные ракеты. Точек множество, они разбрелись по углам детской площадки: вот летит один снаряд, второй через мгновение у турника, а после третий догоняет их в воздухе — и начинается яркая, ни на что не похожая разноцветная феерия."}, {"kind": "paragraph", "text": "Мальчик не знал, почему фейерверк и яркие ледовые городки для него куда важнее на Новый год, чем подарки или конфеты. А о Дедушке Морозе он и совсем не думал. Не потому, что в него не верил, просто ещё пару праздников назад седой бородач заставил одетого в дурацкие чулки Славу рассказывать на табуретке какой-то стишок, да ещё перед кучей детей. Стих он сейчас не вспомнит, но смех отца и этих засерь из группы «Динозаврик» блокировал в его сознании тождество Нового года и Деда Мороза."}, {"kind": "paragraph", "text": "Сидя на подоконнике, Слава опёрся ладошками на стекло пластикового окна, которое никогда не замерзало настолько, чтобы можно было увидеть древовидные узоры — один из атрибутов праздника в памяти его родителей. Смотрел он вниз, на парковку, потом услышал чей-то крик:"}, {"kind": "paragraph", "text": "— Сейчас вы все охереете, что я купил!"}, {"kind": "paragraph", "text": "Что такое «охереть», Слава только догадывался."}, {"kind": "paragraph", "text": "И ждал он великого суперпраздника, такого, что в деревне у бабушки все петухи услышат. Так про петухов всегда изъясняется его мама, когда папа начинает говорить на повышенных тонах. Однако исступление Славки было прервано: всё вмиг пропало, а в окне вместо двора показалась детская испуганная гримаса. Отец включил в комнате свет."}, {"kind": "paragraph", "text": "— Ты куда, блядь, залез, пацан? Я кому кричу там, кричу?"}, {"kind": "paragraph", "text": "Он сдёрнул сына с подоконника и потряс в воздухе."}, {"kind": "paragraph", "text": "— Зову тебя, а он пошёл, побежал, деловой. Чё, от меня прячешься, хм?"}, {"kind": "paragraph", "text": "От отца пахло рыбой и водкой — оно всегда так, но в тот раз как-то по-особенному: слишком пьяно, невыносимо жирно."}, {"kind": "paragraph", "text": "— Чё молчишь? Дать те по башке, чтоб слушал?"}, {"kind": "paragraph", "text": "Слава молчал: просто не знал, как говорить с тем, кто его как куклу трясёт. Мальчик висел, дёргаясь в отцовских руках, — тут уж о фейерверках и думать забудешь."}, {"kind": "paragraph", "text": "— Я спрашиваю, ты чё молчишь — язык проглотил или боишься, а? Боишься меня?"}, {"kind": "paragraph", "text": "Ребёнок моргал, не понимая, что ответить. У него болели плечи, и только когда к глазам стали подходить горячие слёзы, отец его отпустил."}, {"kind": "paragraph", "text": "— В кого ты такой дебил растёшь? Смотреть противно. Дуй отсюда, говорю, и имей уважение к гостям — позоришь меня!"}, {"kind": "paragraph", "text": "Всё бы ничего, но мужчина вдогонку дал ребёнку оплеуху. Когда тот побежал прочь на своих маленьких ножках, отец задёрнул шторы, выключил свет и поплёлся, пошатываясь. По пути на кухню зашёл в туалетную комнату и, опёршись на стену плечом, стал громко ссать."}, {"kind": "paragraph", "text": "Слава прибежал к столу молча — не плакал ни секунды, — сел на стул, взял мандаринку и принялся очищать плод от кожуры. По телевизору что-то пели, Славка не слушал: он сейчас совсем отрешился. Его мама, накручивая указательным пальцем прядь покрытых лаком волос, шушукалась с мужчиной. Она слышала, что муж в туалете, и заискивающая женская улыбка не сходила с её лица."}, {"kind": "paragraph", "text": "А на Славку, еле фокусируя взгляд, смотрела незнакомая тётя с изрядно красными щеками. Она с удивлением произнесла:"}, {"kind": "paragraph", "text": "— Тань, глянь-ка на ребёнка."}, {"kind": "paragraph", "text": "— Чего?"}, {"kind": "paragraph", "text": "Мать обернулась и ахнула:"}, {"kind": "paragraph", "text": "— Ты где так весь растормошился? А, засранец наш? Иди ко мне, причешу. Щас президент будет поздравлять, давай-ка, усаживайся ко мне, я поухаживаю за сыном, правда ведь — сын ты или не сын?"}, {"kind": "paragraph", "text": "— Сын он тебе, — вторила тётя с улыбкой."}, {"kind": "paragraph", "text": "Программа поздравления началась."}, {"kind": "paragraph", "text": "— О, вовремя! — сказал отец, входящий в кухню. — Наливайте."}, {"kind": "paragraph", "text": "— Артём, всё уже налито. Никто желание своё не потерял?"}, {"kind": "paragraph", "text": "— Блин. Я потерял."}, {"kind": "paragraph", "text": "— Да вот оно, перед носом! Всё! Тихо. Готовьтесь."}, {"kind": "paragraph", "text": "Когда начали показывать Кремль, все в кухне затихли. Слава хотел было схватить со стола дольку мандаринки, но мама, расчёсывая его светлые волосы, одёрнула:"}, {"kind": "paragraph", "text": "— Имей уважение."}, {"kind": "paragraph", "text": "Слава смиренно сидел на коленях матери, стараясь показать то самое уважение к окружающим и к мужчине в телевизоре. Ему не было понятно, о чём тот говорит и почему на него накричал в спальне папа. Слава смотрел на свои шерстяные носочки и ждал, когда взрослые снова начнут громко разговаривать."}, {"kind": "paragraph", "text": "Когда пепел желаний все, кроме Славы, запили алкоголем, громкие разговоры продолжились. Новый год наконец постучался в двери — правда, не Славкиного дома, каких-то других домов. Слава его не чувствовал."}, {"kind": "paragraph", "text": "Вот пропал Новый год. Всё пропало."}, {"kind": "paragraph", "text": "Ребёнка отправили мыть руки и одеваться."}, {"kind": "paragraph", "text": "— Сына, иди носки переодень, пжлст, и штаны те возьми, которые мы с тобой, это самое… в садик одеваем, хорошо? На улицу пойдём, — дожёвывая что-то, сказала мама."}, {"kind": "paragraph", "text": "— Ладно, — ответил Слава и сполз с материнских колен."}, {"kind": "paragraph", "text": "Все решили выпить ещё раз, «на посошок», а батьке, видимо, уже хватило, когда ещё пепел желания запивал: как только рюмки взлетели в воздух, он потерял равновесие и неуклюже рухнул на ребёнка."}, {"kind": "paragraph", "text": "— АРТЁМ! АЛКАШИНА! ТЫ РЕБЁНКА УГРОБИШЬ!!"}, {"kind": "paragraph", "text": "— ХОРОШО, ВСЁ, ХОРОШО, Я РЯДОМ С НИМ УПАЛ, НЕ МОРОСИ, — он перевернулся с задницы и посадил на попу испуганного ребёнка. — СЛАВ, — пару пощёчин, не нужных вовсе. — СЛАВ! НЕ УШИБСЯ?"}, {"kind": "paragraph", "text": "Вокруг тельца собрались абсолютно все в этом доме — загремели маты, закричали женщины. Песен из телевизора было не слышно: кто-то, видимо, убавил звук. Слава открыл глаза и увидел над собой море красных лиц. Среди них он узнал только маму: та держала его головку и смотрела прямо в глаза."}, {"kind": "paragraph", "text": "— Спасибо тебе, Господи! Он дышит, — сказала она. — Артём, я с тобой разведусь, нахрен! Доведёшь ты меня, свинья неуклюжая!"}, {"kind": "paragraph", "text": "— А чё я, чё он под ногами, чего это я?"}, {"kind": "paragraph", "text": "Задав все эти вопросы с выпученными глазами и получив только один ответ: «Ничё!», отец поднялся, обошёл людей. Надув обиженно губки, он налил себе в рюмку водки, молча выпил и ушёл на балкон курить, даже не оборачиваясь. Хрустя коленями, встали остальные мужчины. Они присоединились к отцу."}, {"kind": "paragraph", "text": "И вот на кухне остались только тётки да Славка, который чувствовал себя вполне хорошо: ничего не сломал, только задница отца больно надавила на пузико — оно как-то странно ощущалось теперь."}, {"kind": "paragraph", "text": "Мальчик на стуле, со всех сторон на корточках сидели женщины, гладили его головушку и шептались."}, {"kind": "paragraph", "text": "— Таня, шли его к чёрту, подруга, подумай, он тебе ребёнка угробит."}, {"kind": "paragraph", "text": "— А она права, я те серьёзно. Это разве норма? Да не норма это них… ни фига! Он что сейчас сделал, посмотри."}, {"kind": "paragraph", "text": "— Ушёл курить."}, {"kind": "paragraph", "text": "— Сбежал."}, {"kind": "paragraph", "text": "— Сбежал!"}, {"kind": "paragraph", "text": "— Такие всегда сбегут — никакой надёжности…"}, {"kind": "paragraph", "text": "— Девки, хватит! — прервала их мать Славы, потом выдохнула. — А куда я пойду, вот куда?"}, {"kind": "paragraph", "text": "— Мужик найдётся, тебе проще ребёнка самой поднять, у меня такое было, представляешь…"}, {"kind": "paragraph", "text": "Ну и всё в таком духе. Славка это слушал, но не понимал особо, все ему задавали вопросы, где болит. А болит ли, он не мог сказать наверняка."}, {"kind": "paragraph", "text": "Вроде всё хорошо. Вроде обошлось."}, {"kind": "paragraph", "text": "— Славка, а, пацан! Ну-ка, пустите меня к сыну, — в женский круг вклинился пьяный отец. — Чё, у тебя всё нормально?"}, {"kind": "paragraph", "text": "Слава кивнул."}, {"kind": "paragraph", "text": "— Ты меня извини, не рассчитал — кто ж знал, что ты там внизу шаришься, тебя ж не видно, не слышно весь день, а тут вот как вышло, я не со зла. Да? Вот держи конфету."}, {"kind": "paragraph", "text": "Мальчик робко взял подарок."}, {"kind": "paragraph", "text": "— Ну вот, решили. Ну чё, пацан, хочешь с мужиками в город? — Он обратился к остальным: — Айда на горки… Ну чё за мины — всякое бывает. Погнали, ё-моё. Развеемся. Праздник ж."}, {"kind": "paragraph", "text": "— Ты ребёнка мне сейчас чуть не убил, какие горки, иди спать!"}, {"kind": "paragraph", "text": "— Не твоего, а нашего. Это и мой ребёнок тоже, и я решу: горки ему или не горки. Чё, согласен? Пойдём веселиться?"}, {"kind": "paragraph", "text": "Слава снова кивнул, а конфета, подаренная отцом, так и осталась нераскрытой лежать в тёплых детских ручонках."}, {"kind": "paragraph", "text": "Следующие десять минут для Славы были очень долгими. Его самым первым одели: увязали всеми мыслимыми и немыслимыми шарфами, напялили в миллион тысяч миллиардов слоёв одежды, пропихнули под курткой варежки на резинке, а на голову водрузили невозможных размеров шапку. Славка стоял в коридоре у двери один, пока все остальные искали кошельки, закуску, сигареты. Стоял, со стороны куда больше в ширину, нежели в длину. Славка — не Славка, а Смешарик."}, {"kind": "paragraph", "text": "Вскоре он уже был под ночным снежным небом, держа за руку маму, которая шагала так быстро, что Славка почти летел над холодным асфальтом. Ему не больно ручке: она натягивается, это да, но на нём столько надето, что совершенно не чувствуется."}, {"kind": "paragraph", "text": "Его папка, полураскрытый, осоловевший, топал во главе толпы, что растянулась на половину квартала. И издалека Славе его не видно. Они сейчас не вместе. Просто в одно и то же время вышли из точки А в точку Б. И если бы не большущая плотная шапка, Слава бы слышал, как недовольная мама материлась на мужа:"}, {"kind": "paragraph", "text": "— Торопится как, гляньте. Идиотина…"}, {"kind": "paragraph", "text": "Подружки её обогнали — все идут впереди, позади только она и маленький Слава. Её это бесит. Она слышит смех, видит спонтанную игру в снежки, реверансы случайным прохожим, громкие поздравления с праздником тех, кто сейчас на балконах — всё проходит мимо неё, всё веселье. Что за несправедливость! Одиночество ударило очень больно, и она сильнее сжала ручку Славки, быстрее поскакала по тротуару, догоняя уже, кажется, бывших подружек."}, {"kind": "paragraph", "text": "Повсюду гремели салюты, но Слава не мог оценить всю эту прелесть: он просто нёсся над землёй неведомо куда, ведомый матерью. Ребёнок как сумочка, ребёнок как багаж."}, {"kind": "paragraph", "text": "Спустя несколько дворов и парковок они вышли к городскому парку. В центре стояла двадцатипятиметровая ёлка — из железа и бездушия, муниципальная. Рядом залили четыре ледовые горки, самая высокая из которых почти пять метров, а её спуск достигал рекордных для города семидесяти. Такого изобилия ещё никогда не было в жизни Славки, он видел этот спуск и слепящие огни гирлянд, рассеивающие ночную тьму городка, тысячи людей вокруг и… просто не мог поверить своим глазам. Это сон, прекрасный сон, детская сказка! И всё, что было до этой секунды, вмиг забывается, и только одна мысль Славу волнует: изучать эту волшебную страну, каждый её закуток, изучать до изнеможения. Добравшись до горки, мама опустилась на колено, поправила ему шарф и показала рукой на одну из горок:"}, {"kind": "paragraph", "text": "— Смотри, там наверху папа. Хочешь к нему?"}, {"kind": "paragraph", "text": "Среди десятка людей на вершине деревянной конструкции Слава увидел человека, поднявшего руки. Тот что-то прокричал и с разбега рванул вниз по спуску. Он катился на ногах, неуклюже балансируя. Пролетая мимо Славы, отец потерял равновесие, рухнул на задницу и вылетел с ледового покрытия в снежный сугроб."}, {"kind": "paragraph", "text": "— Не волнуйся, ему не больно, — сказала мама, равнодушно отворачиваясь от мужчины, которого когда-то выбрала себе в мужья. — Пойдём лучше ледянку спросим."}, {"kind": "paragraph", "text": "Она отметила, что из колонок бьёт «что-то-из-детства-новогоднее-где-я-это-слышал» музыка. Неподалёку в тени стояли машины полицейских и медиков. Стражи правопорядка и врачеватели, сменяя друг друга, выходили из авто и курили компашками, оглядываясь и выпивая что-то из бумажных пакетиков."}, {"kind": "paragraph", "text": "Среди них был примечателен один человек, которого она, к сожалению, не рассмотрела и, следовательно, не запомнила. С седой головой, чисто выбритыми щеками и подбородком, чёрными, как графит, глазами. На нём был синий шарф, причудливо завязанный на шее."}, {"kind": "paragraph", "text": "Сей мужчина знал, что Слава придёт, но ожидал его куда раньше. Когда отец ребёнка, громко матерясь, скатился с горки в первый раз, незнакомец вышел из палатки, отапливаемой печкой-буржуйкой. С тех пор он стоял, попивая горячий чай, и не спускал глаз с новоприбывших в его ледяное царство."}, {"kind": "paragraph", "text": "Он — проектировщик, местный художник, что выиграл грант на создание главной праздничной локации столицы региона в этом году. Придумал дизайн ледового городка, нарисовал схему расположения горок и населил парк волшебными созданиями изо льда. О нём мало кто слышал, ещё меньше людей видели его лицо. А вот творчество было знакомо каждому здесь, хоть мало кто отдавал себе в этом отчёт. От рекламных баннеров до галерейных картин, от театральных постановок до — на удивление — звучных стихов, на которые накладывали музыку местные уличные артисты, срывая дневной куш."}, {"kind": "paragraph", "text": "Каждый его проект приносит небольшое состояние — всегда успех, — однако эти блага достаются тем, кто от имени художника выступает. Сам автор наблюдает со стороны — не гордясь, не улыбаясь. Отправленная им заявка на создание ледового городка была одобрена лично мэром, все действия на объекте выполняли субподрядчики, однако ночами мужчина приходил в парк и обтёсывал неровности фигур, заливал всё новые и новые слои на горки. Его работу так просто не заметить, настолько она кажется незначительной на первый взгляд. На самом же деле его труд куда глубже, куда полезней — он волшебный."}, {"kind": "paragraph", "text": "Глаза Славы — золотые тарелочки, его ножки — бамбуковые палочки в руках голодного."}, {"kind": "paragraph", "text": "Шик-шик-шик."}, {"kind": "paragraph", "text": "А сердечко — его горячий моторчик — барабанит напропалую."}, {"kind": "paragraph", "text": "Тум-тум-тум."}, {"kind": "paragraph", "text": "Ребёнок в одиночестве любовался высокими статуями двенадцати месяцев, гладил макушку сидящего на ледяной ветке морозного кота. Иногда поднимал голову, поправляя сползающую шапку, на праздничную ёлку, чья звезда на макушке чуть выше звёзд космических, рассматривал других детей. Слава не искал маму, что потерялась минуты назад, не ждал общения, экскурсий, а просто был сам по себе. Вот он изучает наклон горки поменьше той, с которой катался его отец, стоит рядышком с ледянкой в руках, не решаясь подняться к толпе ребят."}, {"kind": "paragraph", "text": "В это время его родители-бедокуры выясняли отношения у сугроба, в котором до сих пор сидел отец мальчика, а остальные — родственники и друзья — вообще потерялись из виду. Они отошли в сторону покурить и выпить по глотку горячительного из небольших бутылочек, взятых с собой."}, {"kind": "paragraph", "text": "— Ты стесняешься, — прозвучал мягкий голос за спиной, который Слава расслышал отчётливо, несмотря на укрытость ушей. — Попробуй, никто тебе против не скажет."}, {"kind": "paragraph", "text": "Слава обернулся и увидел гладкое лицо седовласого мужчины. Тот был без шапки, но, несмотря на мороз, лицо незнакомца источало сильное тепло. Мужчина улыбнулся, и Слава улыбнулся тоже."}, {"kind": "paragraph", "text": "— Там нету мне места, — сказал мальчик."}, {"kind": "paragraph", "text": "— А почему ты так уверен? Смотри! — Мужчина кивнул за спину ребёнка, тот обернулся, и, действительно, выбранная им горка пустовала."}, {"kind": "paragraph", "text": "— Беги, пока никто не занял, — незнакомец подтолкнул Славу, тот со смехом рванул. Рванул с такой же пульсирующей детской энергией, с какой побежал дома к окну спальни, когда на улице заиграли фейерверки. Но, вспомнив оплеуху отца, тут же замедлился и обернулся к мужчине."}, {"kind": "paragraph", "text": "— Я тебя понимаю, — тихо сказал тот, улыбаясь. Он сделал шаг навстречу. — Знаешь, я эту горку сам придумал, одна из моих любимых, — он поправил шарф и прикосновением направил ребёнка ближе к горке. — Смотри, какие красивые у неё перила, видишь узоры?"}, {"kind": "paragraph", "text": "Слава вгляделся в орнамент, который появился буквально только что. До этого узор казался невнятной, покрытой снегом белибердой. Действительно, перила покрывали причудливые очертания девочек с крыльями."}, {"kind": "paragraph", "text": "— Их называют феями. Волшебные создания, согласись? — незнакомец опустился на колено и провёл пальцем по одной из фигур, смахнув с неё иней. Та встрепенулась и весело затанцевала, словно узнала в мужчине своего создателя. Слава от восторга чуть не упал: он не мог поверить в увиденное. Что-то пропищал, в два прыжка приблизился к чуду и очистил от морозного серебра ещё один рисунок феи. Та точно так же ожила, удивлённо посмотрела на укутанного Славку и улыбнулась."}, {"kind": "paragraph", "text": "— Давно ты не разговариваешь? — вдруг спросил мужчина."}, {"kind": "paragraph", "text": "Слава, всё ещё любуясь волшебством, которое сотворил варежкой, кивнул, мол, давно."}, {"kind": "paragraph", "text": "— Тебя это устраивает?"}, {"kind": "paragraph", "text": "Кивнул, принялся очищать третью фигурку."}, {"kind": "paragraph", "text": "— А исправить хочешь?"}, {"kind": "paragraph", "text": "Мальчик помотал головой."}, {"kind": "paragraph", "text": "— Слава, скажи мне: что такое плохо и что такое хорошо? Как думаешь?"}, {"kind": "paragraph", "text": "— Горка. Это хорошо."}, {"kind": "paragraph", "text": "— О, смотри, заговорил, — улыбнулся седовласый. — Любишь горки?"}, {"kind": "paragraph", "text": "— Угу, — ответил Слава."}, {"kind": "paragraph", "text": "— Так почему всё ещё не на ней?"}, {"kind": "paragraph", "text": "Ребёнок вытер сопливый нос и обернулся назад."}, {"kind": "paragraph", "text": "— Родители не разрешают, хочешь сказать?"}, {"kind": "paragraph", "text": "Слава снова замотал головой."}, {"kind": "paragraph", "text": "— Ты же видишь, их нет здесь. Они сейчас другим заняты."}, {"kind": "paragraph", "text": "— Ругаются, — произнёс Слава."}, {"kind": "paragraph", "text": "— Да, и ты это знаешь, — засмеялся мужчина. — Давай так! У тебя, вижу, красивая ледянка есть, но у меня тут… волшебная, — из-под куртки он вытащил что-то совершенно причудливой формы и цвета. — Я её тебе хочу дать. Но при одном условии."}, {"kind": "paragraph", "text": "Слава почесал нос."}, {"kind": "paragraph", "text": "— Я обещаю тебе, если ты скатишься вот с этой горки хоть раз, один всего разочек... и повеселишься… Я обещаю, ледянка будет твоей! Не бойся. Сам поймёшь, что ничего веселее ты раньше не пробовал. Но. Сначала на своей скатись."}, {"kind": "paragraph", "text": "Горка была совсем небольшая: детская, для дошкольников. Чуть ниже отцов, которые обычно торчат рядом и отправляют по ледяному спуску своих трусливых ребятишек, а после, словно гвоздями прибитые, ждут на этом месте, пока те не наиграются. Слава забрался по лесенке, и каждая ожившая фея на перилах ему рукоплескала и подбадривала, а мальчик громко смеялся в ответ. Он присел на вершине, расчистил ледянку, протянул её под попой, сел и несколько раз подпрыгнул, занимая позицию поудобней. После ещё раз посмотрел на седого незнакомца и двинулся к краю. И вот — он покатился."}, {"kind": "paragraph", "text": "В ту же секунду земля, что была в каком-то метре, оказалась далеко, а в какой-то момент спуск казался бесконечным. Это было совсем не страшно. Мальчик катился и катился, смеялся и смеялся, набирая скорость, пока та не стала постоянной и сверх, но всё это не удивительно, а понятно и знакомо. Такую скорость Слава мог развивать во снах. И там она была для него само собой разумеющимся явлением."}, {"kind": "paragraph", "text": "Не сосчитать, сколько прошло времени, сколько эмоций пережито, но Славка оказался внизу. Он проехал пару метров по спуску и развалился на льду, хохоча и по-детски захлёбываясь соплями."}, {"kind": "paragraph", "text": "— Весело, правда? — улыбаясь, спросил мужчина."}, {"kind": "paragraph", "text": "— Очень! Очень весело, так круто! Хочу ещё, можно ещё?"}, {"kind": "paragraph", "text": "— А почему нет? Возьми вот эту ледянку, я, как и обещал, дарю её тебе. Только зачем тебе маленькая горка, пойди вон к той, — мужчина указал рукой на самую высокую. И Славкины глаза засияли. — Я тебе обещаю показать мир, который ты так часто видел во снах. И встречу с друзьями, которых ты видишь только тогда, когда закрываешь глаза. Слава, я хочу подарить тебе то, что никто в твоей жизни тебе не даёт: исполнение желаний, сказку, в которой так отчаянно нуждается твоя душа."}, {"kind": "paragraph", "text": "— Это как? — спросил ребёнок."}, {"kind": "paragraph", "text": "— Как захочешь — всё, что ты захочешь, всё это будет."}, {"kind": "paragraph", "text": "— А мама с папой?"}, {"kind": "paragraph", "text": "Мужчина подошёл к ребёнку и опустился на колено."}, {"kind": "paragraph", "text": "— Знаешь, а я заметил, что ты так и не ответил на мой вопрос. Что для тебя хорошо, мы услышали, верно?"}, {"kind": "paragraph", "text": "— Угу."}, {"kind": "paragraph", "text": "— А что такое плохо — нет."}, {"kind": "paragraph", "text": "— Я не знаю."}, {"kind": "paragraph", "text": "— Ты, Слава, многого не понимаешь, верно? Но сердцем своим ты многое знаешь."}, {"kind": "paragraph", "text": "— Родители? — сдался ребёнок."}, {"kind": "paragraph", "text": "— Родители, — повторил он. — Ты хочешь, чтобы они не ругались?"}, {"kind": "paragraph", "text": "— Хочу."}, {"kind": "paragraph", "text": "— Чтобы любили тебя?"}, {"kind": "paragraph", "text": "— Да, — улыбнулся Слава."}, {"kind": "paragraph", "text": "— И чтобы ты их не боялся, хочешь?"}, {"kind": "paragraph", "text": "Ребёнок смущённо кивнул."}, {"kind": "paragraph", "text": "— Я тебе всё это обещаю исполнить уже к утру, к утру вернётся любовь к тебе и даже сильнее, но мне от тебя всё ещё кое-что нужно. Чтобы ты скатился вон с той ледяной горки — она моя особая гордость, высочайшая и такая красивая! Посмотри на неё, я долго её строил, она тебе понравится, правда. Ты согласен?"}, {"kind": "paragraph", "text": "— Угу."}, {"kind": "paragraph", "text": "— Я хочу показать тебе другой мир. Мой мир, где я уже много лет живу."}, {"kind": "paragraph", "text": "— А он далеко?"}, {"kind": "paragraph", "text": "— Всего лишь в конце той горки. И смотри — на ней никого нет. Она полностью в твоём распоряжении."}, {"kind": "paragraph", "text": "Вступил Слава на лестницу, и перила заходили ходуном. Заиграли на флейтах феи и причудливые создания заплясали, вытесанные во льду и ожившие с приходом мальчика. Звучали знакомые напевы, такие родные и весёлые. Но Слава не мог выделить что-то одно: песнопения смешались. Всё вокруг стремилось угодить ребёнку. И ребёнку это нравилось, то и дело Славка подплясывал, а ступеньки под ним расширялись, оберегая от падения. Где-то сверху включился свет, и мальчик словно оказался на сцене, а взявшиеся из ниоткуда рукоплескания не умолкали."}, {"kind": "paragraph", "text": "Весь мир сузился до этой горки — за ней всё покрыто мраком, — здесь же праздник и бесконечная радость. Как счастлив он сейчас, как ему хочется танцевать и петь, обнять каждую зверюшку, живущую на перилах, и забыть обо всём."}, {"kind": "paragraph", "text": "На вершине он огляделся. Вокруг высились древние горы — снежные исполины, — а под ними журчали ручьи, раскинулись равнины с озёрами, зацвели сиреневым поля на горизонте. Солнце показалось совсем близким, а облака можно было разогнать ладонью."}, {"kind": "paragraph", "text": "— Ты сейчас очень высоко забрался, Слава. Перед тобой весь мой мир, посмотри вниз, — сказал седой мужчина в шарфе. Однако его стиль изменился. Теперь на нём длинный белый балахон. Да и сам мальчик выглядел иначе: ни варежек, ни куртки, ни того бесчисленного множества кофт, которые напялила на него мама. Только ледянка, подаренная незнакомцем. Слава одет так, как ему нравится: белая рубашка и джинсы."}, {"kind": "paragraph", "text": "Слава посмотрел вниз и увидел аттракционы, огни на колесе обозрения и скачущих туда-сюда акробатов. Всё это он видел и раньше, но где именно, вспомнить не мог, да и не нужно ему. Оно всё здесь, и вместе, и сейчас."}, {"kind": "paragraph", "text": "— Ты готов? — спросил мужчина."}, {"kind": "paragraph", "text": "Слава кивнул и сел на ледянку, подполз к краю такой высокой горки, какую он и вообразить не мог, и принялся ждать."}, {"kind": "paragraph", "text": "— Я тебя сейчас оставлю, но мы с тобой увидимся внизу, хорошо? Тебя ждёт праздник, Слава. Только не бойся. Поверь, теперь всё будет иначе."}, {"kind": "paragraph", "text": "И когда мужчина исчез, словно дым на ветру, Слава спокойно посмотрел на свои руки, прошёлся пятернёй по волосам несколько раз. Он любил так делать, но ему запрещали — портилась укладка, — улыбнулся и решился."}, {"kind": "paragraph", "text": "Воздух сотряс тупой удар, будто в океан одновременно упала сотня спелых арбузов. Ледовый городок накрыло инфернальным ором, а родители Славы всё выясняли отношения. Они стояли у полицейского автомобиля: сотрудники патрульной службы явились на ругань супругов и изолировали пьяных от празднующих."}, {"kind": "paragraph", "text": "В городке отключили музыку, и гости вопросительно двинулись в одном направлении, словно рой. Рации у полицейских неистово затрещали. Уже через секунду вместе с медиками уполномоченные бежали к новогодней ёлке. Мама и папа Славы, воспользовавшись моментом, юркнули в темноту. Кто в какую сторону и зачем — потом и сами не смогут объяснить."}, {"kind": "paragraph", "text": "— Семьдесят метров, ей-богу, никто не доезжал так далеко!"}, {"kind": "paragraph", "text": "— А это как случилось, по-вашему? Доехал ведь!"}, {"kind": "paragraph", "text": "— Семьдесят! Мы после пятидесяти даже лёд не полировали — туда просто невозможно добраться с горки!"}, {"kind": "paragraph", "text": "— Это ты его семье объяснять будешь! А вон и полиция! Здравствуйте, вовремя вы!"}, {"kind": "paragraph", "text": "— Что здесь произошло?"}, {"kind": "paragraph", "text": "— На ребёнка кусок ворот рухнул."}, {"kind": "paragraph", "text": "— Боже мой…"}, {"kind": "paragraph", "text": "— Да, мы свидетели, видели — мальчик летел как метеор и врезался, вон они и повалились, стены эти. Страшный удар!"}, {"kind": "paragraph", "text": "— Такой хруст был, мой брат до сих пор блюёт."}, {"kind": "paragraph", "text": "— Они ледовые блоки толком не скрепили, нарушение!"}, {"kind": "paragraph", "text": "— Пошла ты — учить меня будешь, как со льдом работать?!"}, {"kind": "paragraph", "text": "— Откуда он скатился? С неё, что ли?"}, {"kind": "paragraph", "text": "— Да, с той горки."}, {"kind": "paragraph", "text": "— Это невозможно. До неё метров сто, не меньше."}, {"kind": "paragraph", "text": "— Семьдесят пять, максимум восемьдесят."}, {"kind": "paragraph", "text": "— Издеваетесь? Его кто-то толкал?"}, {"kind": "paragraph", "text": "— Да он один летел на ледянке. Да вот она лежит."}, {"kind": "paragraph", "text": "— Что это за цвет такой?"}, {"kind": "paragraph", "text": "— Оранжевый?"}, {"kind": "paragraph", "text": "— Какой оранжевый! Я такой вообще не видел… в дырках вся."}, {"kind": "paragraph", "text": "— Кто? Кто проектировщик?"}, {"kind": "paragraph", "text": "— Это я её строил, ей-богу, не вините, мы тысячу раз на выездных её проверяли — тут просто немыслимая ситуация! Так далеко не уехать даже на волшебной ледянке!"}, {"kind": "paragraph", "text": "— На волшебной, видно, можно."}, {"kind": "paragraph", "text": "— Дело не в том — доехать или нет, у вас стены не по ГОСТу построены, только заденешь — упадёт!"}, {"kind": "paragraph", "text": "— Какой ГОСТ, женщина?! Что вы несёте?"}, {"kind": "paragraph", "text": "— Ребёнка убили — он на вашей совести."}, {"kind": "paragraph", "text": "— Я и сам в этом убеждён!"}, {"kind": "paragraph", "text": "— Так, вы родитель?"}, {"kind": "paragraph", "text": "— Боже упаси, нет…"}, {"kind": "paragraph", "text": "— А хули тут делаете? Уберите бабу, нахрен! Достала орать."}, {"kind": "paragraph", "text": "— А родителей правда жалко."}, {"kind": "paragraph", "text": "— Его пожалей. Где они?"}, {"kind": "paragraph", "text": "— Ищем ещё."}, {"kind": "paragraph", "text": "— Ищите! И изолируйте участок — никого сюда не пускать, особенно этих голосистых. Как родственники найдутся, сообщи мне. Я сам с ними буду говорить."}, {"kind": "paragraph", "text": "Мужчина в полицейской форме достал из внутреннего кармана куртки пачку сигарет, выудил одну и зажёг крикетом огонь. Его руки не дрожали, мысли не толкались одна о другую: он был профессионалом. Но когда подобное случается, даже профессионал приходит к выводу, что он ничего не понимает."}, {"kind": "paragraph", "text": "Когда спасатели подняли массивную плиту — килограммов двести, не меньше, — под ней, придавленное и припорошённое инеем, лежало совсем крохотное тельце, всё синее, а череп был похож на разодранный гранат."}, {"kind": "paragraph", "text": "И никого уже не волновало, взъерошенные у мальчика волосы или нет."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1222	895	10
2	mrd6-idealnaya	Идеальная	41	mrd6/mrd6-idealnaya.jpg	data:image/jpeg;base64,	Как-то я подошла к ней, и у меня в руках громко, на всю квартиру, зазвонил телефон. Я вздрогнула от неожиданности, а она и не обернулась, продолжила вытирать пыль. Как же она ходит по городу, не слыша моторы и сигналы ма	[{"kind": "image", "path": "mrd6/mrd6-idealnaya.jpg", "caption": "Иллюстрация Лены Солнцевой"}, {"kind": "paragraph", "text": "Как-то я подошла к ней, и у меня в руках громко, на всю квартиру, зазвонил телефон. Я вздрогнула от неожиданности, а она и не обернулась, продолжила вытирать пыль. Как же она ходит по городу, не слыша моторы и сигналы машин, как отвечает на вопросы незнакомцев, телефонные звонки?"}, {"kind": "paragraph", "text": "Может, она живёт в божественной тишине или слышит белый шум? Я мало знала о ней: откуда она приходила, где просыпалась по утрам? Куда уходила, знала: к следующему клиенту. Их становилось всё больше и больше, полный город изнеженных белоручек. Зачем убирать, если есть она — идеальная домработница? Не слышит, не говорит, можно записывать голосовые на любые темы, можно включать музыку на всю громкость, можно обсуждать, что угодно."}, {"kind": "paragraph", "text": "Такая свобода при постороннем — роскошь. Но всё же около неё я всегда ощущала неловкость, что я слышу, а она нет, могу говорить, а она... Как оказалось, она могла говорить, плохо, непонятно, но могла."}, {"kind": "paragraph", "text": "Она тоже удивилась, что я собираю её звуки в слова. А я и не собирала, если честно, чутьём улавливала смысл. Со мной она могла не только писать, но и говорить, эмоционально, взахлёб, размахивая руками, всем телом передавая суть."}, {"kind": "paragraph", "text": "Гибкая как лань, высокая, стройная, изящная. Бледная той интеллигентной бледностью, какая бывает у девушек, которые за книгами проводят больше времени, чем на солнце. Не знаю, что у неё было с чтением, просто в голову пришёл образ. Она была белокожей северной казашкой с тонкими костями и нежными чертами лица. Красивая, молодая, модно одетая. Если бы не её особенность, она бы ни за что не зарабатывала на жизнь уборкой."}, {"kind": "paragraph", "text": "Я легко могу представить её в кафе, изводящую ухажёра бесконечными хотелками. Или в офисе на высоких каблуках, взлетающую в тугой юбке по карьерной лестнице, уверенную и сильную. Она такой и была."}, {"kind": "paragraph", "text": "Только вместо иностранных языков и музыки она в школьные годы осваивала язык жестов, чтобы из интерната для глухонемых перейти в пугающий мир. Не существовать на грошовое пособие инвалида, а жить как обычный человек."}, {"kind": "paragraph", "text": "Она приходила в худи, джинсах и кроссовках, переодевалась в рабочие лосины и футболку, доставала свои чудо-тряпочки и, как одержимая, начинала мыть. Знакомая, которая дала контакт Даны, сказала, что та — маньяк уборки, чувствует грязь кончиками пальцев. Я со скепсисом пригласила её и обалдела: она убиралась, как музыканты играют симфонию — слаженно и красиво, квартира после сияла."}, {"kind": "paragraph", "text": "Той ночью мне приснилось, что на вечеринке муж обнимал девушку, нежно поглаживая её ягодицу. Меня как кипятком ошпарили, никаких сомнений — у них связь, гнев мгновенно ударил в голову, и я метнула бутылку вина, которую несла к столу, в голову мужа. Он охнул, обернулся и... Оказался незнакомым парнем. Схватился за голову, осел, кровь поползла из-под его пальцев по лицу ниже, на рубашку, заливая её. Музыка смолкла. Все, кто был на вечеринке, в ступоре молча переводили взгляды с парня на меня и обратно."}, {"kind": "paragraph", "text": "Я проснулась, тяжело дыша и лихорадочно соображая, что же делать. Вызывать скорую, на какой адрес? Напряжение отпустило, когда я поняла, что это сон. На часах половина седьмого утра. Попыталась заснуть, но не смогла. Нащупала тапочки и пошла на кухню ставить чайник. Довольный моим ранним подъёмом кот, мешаясь под ногами, добился пакетика корма."}, {"kind": "paragraph", "text": "Солнце едва поднялось над крышами, но город уже ожил, по дорогам ехали машины, на спортплощадке кто-то делал зарядку, одиночные прохожие спешили по делам. На горизонте дымили две огромные трубы теплосетей. Столько петиций написали, чтобы перестали жечь уголь, перешли на газ, а смог от труб всё так же расползается, скрывая город от неба, превращая алматинцев в безмолвных очевидцев экологической драмы. И, наверное, я провела у окна много времени, потому что позже обычного разбудила своих, и они собирались в спешке, перекусывали на ходу, выливая на меня раздражение. «Не хочу сырники», «где моя рубашка», «опаздываем из-за тебя»."}, {"kind": "paragraph", "text": "Когда все разошлись в школу и офис, я села работать. Сняв трубку домофона, по привычке спросила: «Кто?» Ответом была тишина. Я вспомнила, что день уборки, и нажала на кнопку с ключом."}, {"kind": "paragraph", "text": "Дана вошла стремительно, улыбаясь, как будто безумно рада меня видеть. Это для обычных людей добраться до нужного адреса — не задача, а для таких как она — сложности на каждом шагу. Поэтому она светилась как ребёнок, её хотелось сгрести в охапку и зарядиться энергией."}, {"kind": "paragraph", "text": "Тем более странно было, позже проходя через зал, увидеть её сидящей на подоконнике с опущенной головой. Окно открыто настежь. Она его мыла, а сейчас застыла в позе птицы, которая хочет взлететь. А у нас двадцатый этаж, и Дана — не птица."}, {"kind": "paragraph", "text": "Меня объял ужас, похожий на тот, что был во сне. Странное явление — сновидения: то ли идут по следам, то ли предсказывают. Я стояла как каменная. Позвать Дану — она не услышит. А если подойти и схватить за руку — можно испугать. Кто знает, в каком вакууме она живёт и как отреагирует?"}, {"kind": "paragraph", "text": "Она всё сидела и сидела, а меня бросало то в жар, то в холод. Если упадёт, как жить после этого? И как это возможно — мыла окно и решила покончить с собой? Я ведь не знаю о ней ничего, полиция может предположить, что я её выкинула… Хотя за что? Меня с ней ничего не связывает, кроме уборки. Мои руки похолодели, я стояла, боясь пошевельнуться, как будто неловкими движениями могла поколебать пространство и невольно подтолкнуть Дану к опасному шагу."}, {"kind": "paragraph", "text": "Наконец она задвигалась, поднялась с корточек, развернулась и спрыгнула с подоконника в комнату. Увидела меня и смутилась."}, {"kind": "paragraph", "text": "— Давно стоишь? — уловила я в протяжном звуке."}, {"kind": "paragraph", "text": "Я смогла только кивнуть. Она сунула мне свой телефон. На экране — четыре пропущенных."}, {"kind": "paragraph", "text": "— Послушай, — попросила она мычанием и взглядом."}, {"kind": "paragraph", "text": "Её телефон зазвонил снова. Дана приложила руку к уху, подталкивая меня ответить."}, {"kind": "paragraph", "text": "Я нехотя провела зелёный значок вверх."}, {"kind": "paragraph", "text": "— Привет, киска, ты сегодня свободна? Подъедешь? — мужской голос звучал так, что лёгкая тошнота подступила к моему горлу."}, {"kind": "paragraph", "text": "Дана рядом буравила вопросительным взглядом:"}, {"kind": "paragraph", "text": "— Кто это?"}, {"kind": "paragraph", "text": "Я пожала плечами и отключила вызов. Дана повторила вопрос на бумаге: «Кто звонил?»"}, {"kind": "paragraph", "text": "«Мужчина, просил подъехать», — написала я."}, {"kind": "paragraph", "text": "Она нахмурилась, взяла у меня ручку и быстро задвигала ей по бумаге: «Бывший муж на сайте проституток мой номер выложил. Спрашивает, где я, где дети»."}, {"kind": "paragraph", "text": "«У тебя есть дети?»"}, {"kind": "paragraph", "text": "«Да, трое»."}, {"kind": "paragraph", "text": "Ей ведь лет двадцать пять… Когда успела?"}, {"kind": "paragraph", "text": "«А где они?» — спросила я."}, {"kind": "paragraph", "text": "«У родственников в другом городе. Муж хочет забрать их»."}, {"kind": "paragraph", "text": "Чужая беда молчаливо встала передо мной. Я знала, что Дана приехала из Павлодара в Алматы. Думала, потому что здесь больше работы, больше платят, а, получается, она убегает и прячет детей. Я поймала её взгляд — тревожный, но полный доверия, как будто мне ничего не стоит решить её проблемы."}, {"kind": "paragraph", "text": "«Почему с мужем развелись?» — написала я и передала ей ручку."}, {"kind": "paragraph", "text": "«Пил много, дети ему мешали, бил их»."}, {"kind": "paragraph", "text": "«А тебя?»"}, {"kind": "paragraph", "text": "Дана отрицательно покачала головой, потом сказала едва внятно: «Иногда, один-два раза». И вытянула вверх три пальца."}, {"kind": "paragraph", "text": "В следующий раз она не пришла вовремя. Написала, что поехала в РОВД с заявлением, что муж её преследует. Появилась в двенадцатом часу. При встрече я не почувствовала обычной её детской радости, движения у неё были резкие, порывистые. И убиралась она суетливо, и писала, писала мне длинные сообщения, бросая пылесос и тряпки посреди комнат, чтобы красивым почерком довольно грамотно выводить на бумаге: нет ли у меня знакомых, которые продают дом, и он стоит пустой. Она готова купить в рассрочку, жить и платить. Ей нужно быть вместе с детьми, муж грозится отнять. Он жестокий человек, она не хочет его видеть, детям нельзя к нему, они должны жить с матерью, и не так, как сейчас. Она будет работать."}, {"kind": "paragraph", "text": "Я спросила, что сказали в РОВД."}, {"kind": "paragraph", "text": "«Нет состава, не приняли заявление», — написала она, и крупные слезинки беззвучно потекли по её щекам. От неё так легко отмахнуться: идеальная жертва, доверчивая и безмолвная. Стоит рядом, а её как будто нет, только глаза взывают о помощи."}, {"kind": "paragraph", "text": "Я кожей ощущала её растерянность. Испытывая стыд за моё благополучие, принесла ей стакан воды. Перебрала в голове знакомых с пустующими дачами: у друга, с которым когда-то у нас не сложилось, недавно умер отец, остался дом, надо ему позвонить, он всегда так рад меня видеть…"}, {"kind": "paragraph", "text": "Когда она ушла, я вернулась к работе. А ночью стала птицей. Птицей, отгрызающей себе ногу, чтобы освободиться от приковавшего к столбику кольца. Когда всё было кончено, лапка неподвижно распласталась на земле. Я, не чувствуя боли, прыгая на одной лапе, подняла голову к небу и расправила крылья. Но приближающийся топот заставил оглянуться. Через поле бежали мои дети: «Мама, мама!» Как же я могла о них забыть? Прижались, уткнули носики, три счастливых личика, куда я от них? Сомкнула крылья в безмерном объятии. Кандалы, удерживающие меня на земле крепче железных оков, тихо сопели у меня на груди. Теперь всё ещё сложнее, я уже не та красивая птичка, какой была, моё тело стало другим, мне трудно держаться на одной ноге. Я устремила взгляд к звёздам. Тоска о свободном полёте с широко расправленными крыльями вырвалась наружу громким стоном. Я проснулась с головной болью."}, {"kind": "paragraph", "text": "Никому я не позвонила, потому что это не телефонный разговор, а поводов для встречи не было. Я тогда с головой ушла в творчество, с трудом удерживаясь в семейной жизни. А вскоре Дана исчезла совсем. Не пришла на очередную уборку, мобильный равнодушно сообщил, что номер отключён. Я спросила о Дане у знакомой: «Уехала, сама напишет, когда приедет»."}, {"kind": "paragraph", "text": "Прошли месяцы, я нашла другую домработницу. В блокноте остались исписанные листы, не вырываю, иногда натыкаюсь. И ещё у меня появилась привычка — замирать, увидев новости о погибших женщинах, судорожно вчитываться в скупые строчки, не Дана ли это, как будто я оставила её в опасности."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1379	1041	10
3	mrd6-vo-vsem-vinovat-eyzenshteyn	Во всём виноват Эйзенштейн	42	mrd6/mrd6-vo-vsem-vinovat-eyzenshteyn.png	data:image/jpeg;base64,	1	[{"kind": "image", "path": "mrd6/mrd6-vo-vsem-vinovat-eyzenshteyn.png", "caption": "Иллюстрация Маргариты Царевой при помощи Midjourney"}, {"kind": "paragraph", "text": "1"}, {"kind": "paragraph", "text": "Ершаков вот что запомнил: светлая комната с высоким потолком и большим окном. Возле окна — покрытый светло-коричневой олифой стол. С левой стороны — заправленная бордовой накидкой двуспальная кровать. С правой — комод с чёрно-белым телевизором и сервант с книгами у стенки. Телевизор включён. На экране творится невообразимое: огромный табун лошадей в белых попонах несётся по заснеженному пространству. На каждой лошади всадник в белом одеянии с чёрным крестом, каждый держит в руке длинный заострённый шест, у каждого на голове перевёрнутое металлическое ведро с крестообразной прорезью."}, {"kind": "paragraph", "text": "Кто они? Что происходит? Двухлетний Ершаков тревожно вглядывается в экран, не в силах оторваться. Между тем лавина всадников врезается в толпу пеших людей в каплевидных железных головных уборах, тоже с заострёнными шестами в руках. Начинается побоище. Люди кричат, падают в снег. Откуда-то набегают новые. Всё превращается в свалку. Идут динамичные крупные планы. Ершаков заворожённо смотрит, не понимая сути действия, увлечённый водоворотом необычного, блестящего, звенящего. В груди у него зарождается ощущение какого-то непривычного восторга. И всё это вместе: калейдоскоп средневековой схватки, затапливающее чувство восхищения — останется с ним на многие-многие годы, до самого конца."}, {"kind": "paragraph", "text": "В комнату зашли мама и отец. Поглощённый зрелищем Ершаков их не видит. Только слышит. Память сохранила обрывки фраз: «кино», «Александр Невский»… Пояснения к сюжету, словесные коды. Формулы, позволяющие пройти дальше, проскользнуть в мир, давно исчезнувший, но продолжающий отчаянно пульсировать в параллельной реальности, которую Ершакову ещё только предстоит постичь, на собственной шкуре испытать на прочность связку прошлого и настоящего."}, {"kind": "paragraph", "text": "2"}, {"kind": "paragraph", "text": "Остовы двух разорванных легковушек дымились около сквера республиканского МВД в центре осенней Махачкалы. Кругом сновали полицейские, медики и пожарные. Тротуар был заляпан кровью и клочьями белой пены. С моря приближалась туча, обещавшая дождь. Большинство раненых уже увезли."}, {"kind": "paragraph", "text": "Ершаков успел записать со слов очевидцев следующее: «…когда взорвалась первая машина, обошлось без пострадавших. У раскуроченного остова собрались правоохранители. В этот момент бабахнула вторая заминированная тачка, припаркованная неподалёку. Силовиков и оказавшихся рядом горожан покосило осколками и поражающими элементами — гайками, болтами, обрезками арматуры. Погибли двое — страж порядка и случайный прохожий. Человек шестьдесят получили различные ранения. Некоторых посекло оконными стёклами, выбитыми ударной волной, метнувшейся по проспекту»."}, {"kind": "paragraph", "text": "Когда Ершаков примчался, улицу у сквера занимали кареты скорой помощи, сбоку примостилась пожарная. Орали сирены. Перепачканные кровью обалдевшие медики таскали на носилках травмированных, распихивая по салонам. Им помогали гражданские. Заполненные скорые уезжали прочь. Их место тотчас занимали другие."}, {"kind": "paragraph", "text": "Ершаков принялся фотографировать. Набегавшись, мельком пообщался с кем-то из окровавленных врачей, на пару минут прислонившихся к бортам скорых, с кем-то из легкораненых, сидевших на газоне, с парой-тройкой державшихся тут же зевак. Он старался не наступать на тёмно-красные сгустки, запёкшиеся на асфальте. Между тем пожарные проливали то, что осталось от взорвавшихся автомобилей, и вода, слизывая с тротуара подсыхающую кровь и сукровицу, мутными струями вытекала на проезжую часть."}, {"kind": "paragraph", "text": "Вечером в прибрежной кафешке Сиражудин спросил его:"}, {"kind": "paragraph", "text": "— Зачем тебе это? Со мной-то понятно: я правозащитой занимаюсь, живу здесь. Люди вокруг не чужие для меня. А тебе-то зачем? Остался бы у себя в Екатеринбурге. Ходил бы в офис, писал новости уральские. По крайней мере, в безопасности."}, {"kind": "paragraph", "text": "Ершаков задумался, а затем выдал:"}, {"kind": "paragraph", "text": "— Во всём виноват Эйзенштейн."}, {"kind": "paragraph", "text": "— Поясни."}, {"kind": "paragraph", "text": "— Есть семейное предание. В раннем детстве, когда мы ещё жили в коммуналке, родители телик забыли выключить, и я фильм «Александр Невский» Эйзенштейна глянул случайно. Данный факт серьёзно повлиял на моё сознательное и бессознательное."}, {"kind": "paragraph", "text": "— А Кавказ тут при чём?"}, {"kind": "paragraph", "text": "— А при том, что позже абсолютно закономерно я начал интересоваться российской военной историей. И когда в 1999-м Басаев и Хаттаб к вам вторглись, меня окончательно переклинило. А много ли надо пятнадцатилетнему мальчишке? История? Пожалуйста! Война? Пожалуйста!"}, {"kind": "paragraph", "text": "— И ты пропал…"}, {"kind": "paragraph", "text": "— Да. Следил за событиями. Делал заметки в толстой тетради. Потом на журфак поступил. Ну а дальше ты в курсе."}, {"kind": "paragraph", "text": "— Тебе не говорили, что ты просто авантюрист или адреналиновый наркоман? — уточнил Сиражудин."}, {"kind": "paragraph", "text": "— Говорили, — усмехнулся Ершаков. — Но сие утверждение весьма спорное. Вернее, кусочек правды здесь есть. Но он — лишь небольшая часть диагноза. А сам диагноз, наверное, сложнее."}, {"kind": "paragraph", "text": "— Для себя-то хоть сформулировал?"}, {"kind": "paragraph", "text": "— Нет. Пока нет."}, {"kind": "paragraph", "text": "3"}, {"kind": "paragraph", "text": "Подобные ситуации постоянно сопровождали Ершакова. Люди, с которыми он знакомился, рано или поздно интересовались причинами его — странного, на их взгляд, — способа жить. Ершаков, отвечая, отшучивался. Мол, существует фамильная легенда: во всём виноваты режиссёр Сергей Эйзенштейн и актёр Николай Черкасов, сыгравший князя Александра Невского. Собеседники, разумеется, не верили."}, {"kind": "paragraph", "text": "Вопросы чаще возникали у женщин. Однажды летом ему в мессенджере написала молодая журналистка — среднего роста шатенка накануне развода, мать двоих детей. Она хотела делать документальный фильм про уральских военкоров, и кто-то посоветовал ей обратиться к Ершакову. Встретились в центре города, в парке у станции метро «Динамо». Он рассказал о своих поездках, а дойдя до главного, произнёс:"}, {"kind": "paragraph", "text": "— В чём причина? Знаете, полную ответственность несёт Эйзенштейн."}, {"kind": "paragraph", "text": "— Шутите? — удивилась Мария, так её звали."}, {"kind": "paragraph", "text": "— Ни в коем случае."}, {"kind": "paragraph", "text": "Впрочем, мир этой истории не узнал. Мария рассчитывала на грант, а зря. Грант не дали. Запись интервью легла на полку."}, {"kind": "paragraph", "text": "В другой раз Ершаков разговорился с коллегой-азербайджанкой. Миниатюрная, смазливая, похожая на кошку, с хорошими фото в соцсетях, она очень ему нравилась."}, {"kind": "paragraph", "text": "— Дима, как тебя девушка-то отпускает?"}, {"kind": "paragraph", "text": "— А у меня нет девушки."}, {"kind": "paragraph", "text": "— Ну родственники. Им же явно не всё равно."}, {"kind": "paragraph", "text": "— Знаешь, всё очень сложно. — И далее последовала былина про пагубное влияние кинематографического творчества Эйзенштейна на неокрепшую психику юного Ершакова."}, {"kind": "paragraph", "text": "Со временем подобные диалоги стали привычны. И когда на корпоративе к нему подсела юная выпускница журфака, недавно перешедшая в их информагентство из филиала федеральной газеты, он, оценивая её большие карие глаза, длинные русые волосы и выразительные, чуть пухлые губы, уже ничему не удивлялся."}, {"kind": "paragraph", "text": "4"}, {"kind": "paragraph", "text": "На ночь бабушка читала Ершакову вместо сказок «Юность полководца» Василия Яна. Вытянувшись худеньким тельцем под одеялом, он внимательно слушал, но понемногу образы князя Александра, дружинников, шведов и немцев смешивались у него в голове, и он засыпал."}, {"kind": "paragraph", "text": "Книжка была старой, с иллюстрациями художника Ивана Кускова. Вечером, после садика, Ершаков изучал серые невзрачные картинки: вот битва на Неве и упавший с конём на землю ярл Биргер, вот битва на Чудском озере и тонущие в полыньях ливонские кнехты и рыцари — непременно в рогатых шлемах."}, {"kind": "paragraph", "text": "Книга стала продолжением фильма. Она дополнила изначальные впечатления, расширила их. Ведь где «Юность полководца», там и «Чингисхан», «Батый» и «К \\"Последнему морю\\"» — серия романов Яна про создание монгольской империи в XIII веке. Ершаков не заметил, как проглотил их от корки до корки, заодно обучившись грамоте. В груди у него уже теплился огонёк страсти."}, {"kind": "paragraph", "text": "Текст Яна явился второй бациллой, поразившей маленького Ершакова. «Постепенно пёстрое вражеское войско, сперва очень медленно, а затем всё быстрее, двинулось вперёд. Тяжёлым равномерным скоком, казалось, в непреодолимом натиске, приближались немецкие всадники. Уже отчётливо стали видны первые пять рыцарей, мчавшихся, пригнувшись и выставив длинные копья…» Можно было даже не напрягаться. Эйзенштейн услужливо подбрасывал картинку, изменяемую сюжетом книги в нужную сторону."}, {"kind": "paragraph", "text": "Мало того, изображение Ледовой сечи в изложении режиссёра и писателя как бы застыло во взоре Ершакова, отпечаталось на сетчатке. Он словно наблюдал окружающий мир сквозь прозрачные фигуры бьющихся окольчуженных конников в обрамлении теней копий и щитов. Разумеется, никто не знал этого секрета, ведь даже повествуя о семейном предании, он не раскрывал всех карт, умалчивая о фата-моргане, существующей в его мозгу."}, {"kind": "paragraph", "text": "Позже Ершаков прочитал биографию автора и нашёл схожие черты. Ян тоже работал военкором — на Русско-японской, в Персии, на Балканах, на румынском фронте Первой мировой, на Урале и в Сибири на стороне белых во время Гражданской. Тоже любил Восток, путешествовал по Центральной Азии. Правда, Ершакову там побывать не довелось, но Северный Кавказ ничем не хуже."}, {"kind": "paragraph", "text": "Иными словами, мозаика складывалась медленно, формируя характер, взгляды, поступки. Формируя судьбу. Ведь, рассуждая по совести, отговорка про фамильное предание была именно отговоркой. Но при более глубоком рассмотрении оказывалась клубком из разноцветных нитей. Возьмёшься распутывать — сразу провалишься в подёрнутый тонким ледком разлом исторических и культурных ассоциаций и воспоминаний."}, {"kind": "paragraph", "text": "5"}, {"kind": "paragraph", "text": "«Забавная новость», — подумал Ершаков, читая сообщение о том, что в соседней Курганской области установили памятник Александру Невскому. И ладно бы в столице региона, так ведь нет — в какой-то деревне. Инициаторами явились два брата: депутат Госдумы и директор мясокомбината, расположенного в том самом населённом пункте."}, {"kind": "paragraph", "text": "К пресс-релизу прилагалась фотография: князь Александр в доспехах возвышается на огромном каменном постаменте, придерживая шлем и опираясь на меч. «Какого рожна? Где Невский — и где Зауралье? Они там Эйзенштейна пересмотрели?» — недоумевал Ершаков. Но у мясокомбината с информационным агентством контракт, значит, придётся писать. Никуда не денешься. «Всё ради бизнеса шефа», — говорили обычно в таких случаях в редакции."}, {"kind": "paragraph", "text": "Ершаков устроился в агентство ещё до поездок на Кавказ. Собственно, оно оказалось на тот момент последним уральским местом работы. Последней каплей, переполнившей чашу. Он пришёл сюда тупо ради денег, дабы немного подзаработать и свалить куда подальше — от малой родины, от скучной повестки, от изнуряющей офисной обязаловки."}, {"kind": "paragraph", "text": "Само агентство являлось историческим для Екатеринбурга учреждением. Одним из первых в мегаполисе. Оно было слеплено на исходе девяностых на базе муниципального политического движения. Оно отстаивало интересы городской администрации в информационных баталиях с областными СМИ, поддерживающими губернатора. Битвы компроматов кипели такие, что не дай бог. Миниатюрное агентство лавировало в эпицентре схватки, уклоняясь от пудовых кулаков региональных воротил, пытаясь не попасть в объятия легализующихся бандитов, не забывая о своём истинном сюзерене в лице мэрии. Впрочем, к моменту прибытия Ершакова легендарные медиасражения миновали. Агентство влачило жалкое существование, деля помещение на первом этаже сталинки в тенистом квартале в центре Екатеринбурга с упомянутым выше движением, некогда ставшим для него опорной точкой, а нынче полностью захиревшим."}, {"kind": "paragraph", "text": "Главным редактором агентства был Василий Сергеевич Рыбников. Высокий плотный брюнет под пятьдесят, с пузиком, родом откуда-то с Волги, он ходил на работу в потёртых синих джинсах и старом сером, видавшем виды свитере. Идеальный начальник — весь день играл на компьютере в тетрис или раскладывал пасьянсы, ничего не навязывал, ни о чём не спрашивал, не придумывал идиотских заданий. Иногда складывалось впечатление, будто редакция — сама по себе, а Василий Сергеевич — сам по себе. Порой устраивали небольшие перерывы, и Рыбников рассказывал про жену, состоявшую в пресс-службе транспортной компании, про сына, учившегося на режиссёра в Питере, про будни девяностых, когда агентство занимало комнату в другом здании, а ниже функционировал офис ОПС «Уралмаш» — пожалуй, самой знаменитой преступной группировки Свердловской области того периода."}, {"kind": "paragraph", "text": "— И вот представьте, — басил Рыбников, — звонят мне знакомые журки из Москвы. Интересуются, как связаться с уралмашскими. А я отвечаю: «Запросто! Записывайте телефон пресс-секретаря». А те охренели: «У них ещё и пресс-секретарь есть?!»"}, {"kind": "paragraph", "text": "Но верховным руководителем агентства, директором, числился иной человек — Алексеев. Маленький пухленький мужчинка с щёчками, быстро передвигавшийся и без умолку тараторивший, любивший одеваться в костюмы мышиных тонов. Возил его пожилой татарин, ничем иным не занимавшийся, но уверявший окружающих, что трудится в МЧС, и как-то раз даже притащивший ведомственную медаль."}, {"kind": "paragraph", "text": "На самом деле Алексеевых было двое. Они отвечали за разные направления: старший держал агентство, а второй, такой же кругленький, упитанный брат-близнец, командовал фирмой, управлявшей коммерческой недвижимостью, в основном офисными центрами. Третьей опорой семейного подряда — рекламным агентством — рулила младшая сестра Алексеевых, абсолютно не похожая на них стройная симпатичная брюнетка Таисия."}, {"kind": "paragraph", "text": "Старший Алексеев боялся всего: конкурентов, чиновников, силовиков. Правда, время от времени, чувствуя поддержку во властных кабинетах, пытался «покусать» кого-нибудь в целях налаживания дальнейших отношений: мол, вы нам — деньги, мы вам — блок на негатив. Например, однажды он велел опубликовать на сайте агентства информацию о проблемах в какой-то новостройке."}, {"kind": "paragraph", "text": "— Сейчас мы их прижучим, — потирая влажные ладошки, ухмылялся Алексеев."}, {"kind": "paragraph", "text": "Вечером ему позвонили, и новость молниеносно исчезла. Выяснилось, что к новостройке имели отношение авторитетные люди."}, {"kind": "paragraph", "text": "Зато в следующий раз Алексееву удалось порезвиться вволю. Поступил заказ — мочить корпорацию, отвечавшую за развитие северной части федерального округа. Требовалось ежедневно звонить депутатам региональных дум, собирая компромат, а затем просить комментарии у пресс-службы корпорации."}, {"kind": "paragraph", "text": "— Прямо по спискам идите, в алфавитном порядке! — брызгал слюной Алексеев, размахивая руками. — И хуячьте, хуячьте!"}, {"kind": "paragraph", "text": "Депутаты сперва прониклись и радостно отвечали на вопросы, но уже через несколько дней заподозрили неладное и начали сливаться. Пресс-секретарь корпорации старался соблюдать политес, но в конце концов даже он психанул и проорал в трубку:"}, {"kind": "paragraph", "text": "— Пусть вам Алексеев комментирует всё это!"}, {"kind": "paragraph", "text": "Но самая вопиющая история приключилась чуть позже. В городе разгорелся нешуточный скандал: обострилось противостояние между МВД и общественником, боровшимся с наркоторговлей. Правда, ходили слухи, будто активист ведёт свою войну с распространителями дури в интересах определённой криминальной группы, но доказательств никто не предоставил. А поставлено всё было на широкую ногу: команда, офис, база, куда родственники привозили наркоманов на «лечение». Там пациентов приковывали наручниками к кроватям, а после ломки отправляли на трудотерапию."}, {"kind": "paragraph", "text": "И вот внезапно у одной пациентки обострился хронический менингит. Девушку доставили в больницу города Берёзовского, где она скончалась. Провели экспертизу. Главный врач публично объявил причину смерти гражданки. Видимо, в то мгновение в голове Алексеева щёлкнуло, и он решил вмешаться в конфликт. Ну или просто кто-то опять позвонил."}, {"kind": "paragraph", "text": "Миссию поручили Ершакову. Когда ему передали детали, он охренел. По словам Алексеева, нужно было сгонять в Берёзовский, найти названного главврача и сделать так, чтобы доктор заявил: девушка умерла от пыток, а пытали её, судя по всему, на той самой базе борцов с наркотиками."}, {"kind": "paragraph", "text": "— Арматуру брать? — съязвил Ершаков и добавил: — А почему мне поручили? Потому что я с Уралмаша?"}, {"kind": "paragraph", "text": "Ответа не последовало. Он поехал, отыскал врача. Тот сослался на экспертизу. Мол, никаких сомнений — менингит. Ну и славно. Вернувшись, Ершаков отчитался. Алексеев скривился — выслужиться перед вышестоящими не получалось."}, {"kind": "paragraph", "text": "«Ну кривись, кривись, — мрачно рассудил журналист. — Я все твои приколы запоминаю, ублюдок»."}, {"kind": "paragraph", "text": "6"}, {"kind": "paragraph", "text": "Толкучка парилась на летнем тяжёлом солнце. Высокий чернявый отец Ершакова нырял в толпу, словно знал тайные пути, вьющиеся в массиве пенсионерских тел, одетых в растянутые треники и футболки, затасканные пиджаки и пожухлые платья. Ершаков, недавно окончивший первый класс, бежал за ним, даже не пробуя припомнить дорогу назад, к спасительной трамвайной остановке. Людские волны бросали его в разные стороны, а он, уцепившись за отцовскую пятерню, зажмурившись, скользил по маршруту, пропитанному запахом пота и перегара."}, {"kind": "paragraph", "text": "Их выбросило к отмели, представляющей собой ряд лотков с книгами. Чего здесь только не было: детективы, сборники фольклора и рассказов про НЛО, пожелтевшие залежи классики и никому не известных советских писателей, подшивки детских и литературных журналов за разные годы, отрывные календари и труды о вкусной и здоровой пище с тысячами рецептов. Взгляд Ершакова безучастно блуждал по царству макулатуры, пока не споткнулся о скромную книжонку. На белой обложке оранжевая луна висела над чёрным полем, по которому навстречу друг другу неслись монгольский и славянский воины."}, {"kind": "paragraph", "text": "— Алексей Югов, «Ратоборцы», — прочитал Ершаков и обернулся к отцу."}, {"kind": "paragraph", "text": "— Давай посмотрим, — сказал тот, открывая аннотацию. — Так, «…повествует о жизни двух величайших защитников русской земли — Данииле Галицком и Александре Невском». Ну что? Берём?"}, {"kind": "paragraph", "text": "— Ага, — кивнул Ершаков, услыхав заветное имя."}, {"kind": "paragraph", "text": "Первая часть книги была посвящена Даниилу. В центре сюжета — Ярославская битва августа 1245-го, когда польско-венгерская армия потерпела поражение от русско-половецкого войска, и дальнейшие события отношений Галицко-Волынской Руси и Золотой Орды. Ершаков быстро преодолел её и обратился ко второй."}, {"kind": "paragraph", "text": "Во второй речь шла о пятидесятых годах XIII века. Прежде всего, о битве на Клязьме в мае 1252-го, то есть о разгроме монголами русской рати, которой руководил князь Андрей Ярославич, младший брат Александра Невского. Само сражение Югов расписал очень красочно. А вот остального юный читатель не оценил. Совсем не оценил."}, {"kind": "paragraph", "text": "Разочарование накатило на Ершакова. Он сидел, растерянный, на кровати и не мог понять, как можно, написав роман про Невского, обойти стороной Ледовое побоище. Как так можно? Это ведь самое главное! Не книжка, а недоразумение, кощунство! Вот у Эйзенштейна в фильме всё правильно: крестоносцы, таранящий пехоту рыцарский клин, трескающийся лёд. А тут? Кровавое месиво рубки с венграми и татарами. А где эстетика? Где романтика Средневековья? Где иллюстрации, в конце концов?"}, {"kind": "paragraph", "text": "Однако интересное всё же нашлось."}, {"kind": "paragraph", "text": "«Рассказывая, Александр вдруг расхохотался…"}, {"kind": "paragraph", "text": "— Да помнишь, как фон Грюнингена волокли ребята по льду ремнями за ноги?"}, {"kind": "paragraph", "text": "Хохочет и Андрей. И это не скатерть уже, а чуть припорошённый снежком лёд Чудского озера в тот достопамятный день. А вспомнилось братьям, как ватага неистовых новгородцев во главе с Мишей, пробившись до самого прецептора, свалила фон Грюнингена с коня, и так как закованного в панцирь гиганта трудно было унести на руках, то кто-то догадался захлестнуть за обе панцирные ноги прецептора два длинных ремня, и, ухватясь за них, ребята дружно помчали рыцаря плашмя по льду, в сторону своих: панцирь по льду скользил, как добрые санки с подрезами. И когда уже близ своих были, то кто-то вскочил на стальную грудь, как на дровни, и так проехался на фон Грюнингене, среди рёва и хохота»."}, {"kind": "paragraph", "text": "Маленькая деталь, но любопытная. Мерцающая вдали, сквозь заросли ордынских интриг. Свежий элемент орнамента, изнутри украшавшего ершаковскую черепную коробку."}, {"kind": "paragraph", "text": "7"}, {"kind": "paragraph", "text": "Ершакову было скучно. Новости про убийства, суды, ДТП, уголовные дела ему давным-давно надоели. Алексеевские идеи раздражали. В перерывах между заметками он читал электронные книги, травил байки с коллегами, выходил на крыльцо подышать свежим воздухом. Возвращаясь за компьютер, просматривал почту и лениво переписывал более или менее пристойные релизы от МВД, СКР или прокуратуры."}, {"kind": "paragraph", "text": "Зимой, накануне выходных, ему попалось любопытное письмо. Областной департамент охраны природы сообщал о сложной ситуации на севере региона. Там из-за сильных снегопадов и морозов к людям стали выбегать волки. Они пожирали сторожевых собак на деревенских окраинах и даже появлялись на дороге, ведущей в старинный городок Верхотурье. Местные власти посоветовали гражданам без нужды не покидать пределы населённого пункта, особенно по ночам."}, {"kind": "paragraph", "text": "Ершаков сразу представил вечернюю метель, поглощающую облупленный верхотурский кремль. Куцые огоньки, дрожащие в окнах избушек. На улице пусто, только белая стена из холодного, хрустящего, колюще-режущего волокна. Деревянный мост над промёрзшей рекой Турой превратился в гигантскую продолговатую ледышку. А на выезде в полях и перелесках мелькают быстрые зловещие приземистые тени."}, {"kind": "paragraph", "text": "Он изложил замысел Рыбникову: сделать репортаж о волчьей блокаде городка."}, {"kind": "paragraph", "text": "— А от меня-то что требуется?"}, {"kind": "paragraph", "text": "— Василий Сергеевич, поговорите с Алексеевым. Пожалуйста. Нужны только деньги на бензин, а с департаментом я сам порешаю."}, {"kind": "paragraph", "text": "— Ну хорошо. Давай попробуем."}, {"kind": "paragraph", "text": "К счастью, Алексеев согласился, отслюнявив пару тысяч на топливо в обе стороны."}, {"kind": "paragraph", "text": "Вместе с Ершаковым в командировку отпустили редакционного фотографа Севу. Двухметровый вихрастый брюнет-здоровяк Сева работал в агентстве уже несколько лет. Раньше он жил в Красноярске, но его супругу, занимавшую должность в РЖД, перевели в Екатеринбург, и Сева поехал за ней. Здесь они сняли квартиру. Жена продолжила трудиться в системе, а её избранника приняли в агентство."}, {"kind": "paragraph", "text": "Выдвинулись на Севиной легковушке по темноте. С проспекта Космонавтов выкатили к Верхней Пышме, а затем свернули на Серовский тракт, прозванный «трассой смерти» из-за частых смертельных аварий. За Нижним Тагилом дорога из четырёхполосной превратилась в двухполосную, разметка из-за снега не просматривалась в принципе, а когда проезжали мимо деревень, Сева матерился, опасаясь, как бы из переулка под колёса не выскочил пьяный сельчанин."}, {"kind": "paragraph", "text": "— А чего тебе туда приспичило? — спросил Сева про Верхотурье, когда остановились на заправке."}, {"kind": "paragraph", "text": "— Да ты знаешь, достало в офисе сидеть. Ну сколько можно?"}, {"kind": "paragraph", "text": "— Я бы в Италию или Испанию сгонял, — принялся мечтать Сева, — пофоткал бы там с удовольствием."}, {"kind": "paragraph", "text": "— А я бы на войну."}, {"kind": "paragraph", "text": "— Зачем? — удивился он."}, {"kind": "paragraph", "text": "— Военкором поработать. Интересно же."}, {"kind": "paragraph", "text": "— Серьёзно? Мне — нет. Грохнут, не дай бог, и всё. Ни Италии, ни Испании."}, {"kind": "paragraph", "text": "— Грохнуть-то и здесь могут."}, {"kind": "paragraph", "text": "— Согласен. Но там вероятность больше."}, {"kind": "paragraph", "text": "— Всю жизнь дома, что ли, теперь провести?"}, {"kind": "paragraph", "text": "— Не дома, но рисковать ни к чему, я считаю. Жизнь одна."}, {"kind": "paragraph", "text": "Верхотурье встретило позёмкой. Лет десять назад, во время учёбы в школе, Ершаков бывал здесь. Правда, летом. Но с тех пор городишко мало изменился. Тот же покоцанный кремль. Те же заброшенные церквушки тут и там. Те же почерневшие от старости деревянные бараки."}, {"kind": "paragraph", "text": "— Ну как тебе? — съехидничал Сева."}, {"kind": "paragraph", "text": "— Зашибись! — деланно воскликнул Ершаков."}, {"kind": "paragraph", "text": "— То-то и оно."}, {"kind": "paragraph", "text": "Егеря базировались на участке, примыкающем к лесу. Показали своё хозяйство, снегоходы, оружие, снаряжение, найденные капканы. Рассказали о ситуации, о борьбе с волками и браконьерами, накормили варёной картошкой с мясом."}, {"kind": "paragraph", "text": "— А что за мясо? Кажется, раньше не пробовал такого, — заметил Ершаков."}, {"kind": "paragraph", "text": "— Мясо хорошее. Кушайте, кушайте, — лукаво улыбнулся главный егерь, краснолицый крепенький мужик в камуфляже."}, {"kind": "paragraph", "text": "Обратно стартанули после обеда."}, {"kind": "paragraph", "text": "— Ты заметил, как он улыбался? — не унимался Ершаков."}, {"kind": "paragraph", "text": "— Да ладно тебе. Нашли, наверное, лося, попавшего в браконьерский капкан, пристрелили, разделали, заморозили. Или уже убитого изъяли, — предположил Сева и засмеялся. — Мясо-то хорошее!"}, {"kind": "paragraph", "text": "Ближе к Тагилу их нагнал буран. Сева снизил скорость, и они потащились в длинной веренице грузовиков и легковушек, пронизывающей снежное пространство. Ершаков пытался разглядеть окрестности, но видел только включённые фары ползущего впереди джипа, которые светились красно-оранжевым, а затем внезапно обратились в огромные огненные колёса и понеслись куда-то вверх."}, {"kind": "paragraph", "text": "8"}, {"kind": "paragraph", "text": "Откуда взялся тот зелёный том? Да и название пафосное — «За землю русскую». Тем не менее Ершаков одолел «кирпич». Вообще, так получилось, что в детстве и юности он читал в основном исторические романы. Ян, Пикуль, Конан Дойл, Сенкевич, Валентин Иванов, Станислав Пономарёв, Сергей Бородин… И зелёный том. А кто автор? Анатолий Субботин."}, {"kind": "paragraph", "text": "Субботин, конечно, превзошёл и Яна, и Югова и по объёму, и по глубине изложения. Но, опять же, прямо по Эйзенштейну: «В голубоватой дымке тумана можно различить с русского берега острый клин железного рыцарского полка. Закованные в броню, в рогатых шеломах и шеломах-бочках, с крестовиной спереди, с закрытыми бронёй мордами коней, словно невиданные страшные чудовища, поднявшиеся из ледяных глубин озера, приближаются железные всадники. <…> Но, разорвав чело русичей, меченосцы не повернули коней. Случилось то, чего не предвидели и не могли предвидеть обрадованные лёгкой победой на Лутсне рыцари духовного братства креста и меча. Кони их замешкались в возах, намеренно или случайно оказавшихся позади чела. За возами преграждала путь засека сваленных древесниц. Меж возами, в сучьях древесищ, словно в тенётах, бились рыцари. <…> Следом за железным полком меченосцев вытянулись на русский берег пешие кнехты и холопьи полки. Позади их, на льду Узмени, точно город, несокрушимая стена заднего рыцарского полка. Во главе заднего полка крестоносцев — магистр Ордена, благородный рыцарь фон дер Борг. Рядом с магистром маршал фон Балк, командоры Конрад фон Кейзерлинг и Людвиг фон Гире». И так далее. Словно фильм ещё раз посмотрел."}, {"kind": "paragraph", "text": "Однако Субботин дал конкретную предысторию конфликта: бросил две приманки — Медвежью Голову и Омовжу. Заинтригованный Ершаков не устоял. Ещё две битвы — пара новых ориентиров. Всё цепляется друг за друга, всё связано. И от этой связи никуда не деться. Если достаточно внимателен, ты не пройдёшь мимо нитей, тянущихся веером, пересекающихся, переплетающихся, точно узор высушенного листа, точно пульсирующая сеть кровеносных сосудов, грибница, космос."}, {"kind": "paragraph", "text": "По сути, с каждым шагом он дополнял разраставшуюся внутри матрицу. Добавлял текстуры, оттенки. А они не кончались и не кончались. Затейливый орнамент из картинок средневековых летописей, буковок и эмблем сперва полностью покрыл его череп, а затем пополз вниз, охватывая шейный отдел, позвоночник, рёбра."}, {"kind": "paragraph", "text": "Субботин, кстати, тоже оказался журналистом. Участвовал в Первой мировой и Гражданской. Чередовал административные должности и работу в различных изданиях. В итоге отдал предпочтение писательству. Закономерный мучительный этап, до начала которого большинство не доходит."}, {"kind": "paragraph", "text": "9"}, {"kind": "paragraph", "text": "Летом 2005-го Ершаков, учившийся на журфаке, отправился в Санкт-Петербург на практику четвёртого курса. Поселился у знакомой супружеской пары на юго-восточной окраине, около станции метро «Улица Дыбенко». Муж устанавливал домофоны, а жена трудилась в библиотеке. Ершаков снял у них на три месяца гостиную. Сразу за многоэтажкой тянулся проспект Большевиков, за ним простирался пустырь и текла речка Оккервиль. Иногда по утрам, по пути на работу, ему попадались пьяные негры или латиносы — неподалёку торчали общаги двух университетов: петербургского государственного и метеорологического."}, {"kind": "paragraph", "text": "Стажироваться Ершакова взяли в газету «Невское время». Редакция располагалась в центре города, на улице Большой Морской, около Исаакиевского собора, в четырёхэтажном доме. В соседнем корпусе — Музей Набокова. У дверей редакции посетителей встречала моложавая блондинка за сорок, выдававшая ключи сотрудникам отделов и записывающая в тетрадь приходящих и уходящих. Ершакова определили в отдел «Общество», поручив переписывать милицейские сводки, бегать на пресс-конференции и прозванивать оперативные инфоповоды. На стене комнаты висело чёрно-белое фото женщины в коротком платье, сидевшей на диване с тлеющей сигаретой в руке."}, {"kind": "paragraph", "text": "— А это кто? — уточнил однажды Ершаков."}, {"kind": "paragraph", "text": "— Проститутка, которую мы сюда вызывали, — бесстрастно ответил похожий на писателя и поэта Дмитрия Быкова[1] корреспондент."}, {"kind": "paragraph", "text": "В целом в редакции царила непринуждённая обстановка, щедро сдабриваемая анекдотами типа: «Идёт мужик по берегу озера. Видит — по пояс в воде рыбак стоит. — \\"Ну что, клюёт?\\" — \\"Нет, не клюёт. Сосёт!\\"»."}, {"kind": "paragraph", "text": "В свободное время Ершаков любил гулять по городу. Однажды его занесло в Александро-Невскую лавру. Арочный вход у названной в честь князя площади оккупировали попрошайки — псевдоветераны, горбатые старухи, «беременные» с подушками вместо живота, обезноженные пропойцы. Все они требовали денег, пива и грозились показать паспорт, видимо, желая доказать, что не являются мошенниками."}, {"kind": "paragraph", "text": "За аркой лежали прохладные Тихвинское и Лазаревское кладбища, тонкой лентой вилась речка Монастыриха и, наконец, возвышались оранжевые стены лавры. Сама лавра, возведённая в стиле классицизма, бросалась в глаза своими колоннами, башнями, широкими окнами. Внутри, в обитом позолоченным металлом ковчеге, хранились останки Александра Невского. Гробница не произвела на Ершакова никакого впечатления. Больше заинтересовал Казачий некрополь у подножия храма, усеянный захоронениями времён ленинизма-сталинизма."}, {"kind": "paragraph", "text": "— Надо же, сплошной «совок» в имперской обёртке, — пробормотал он, огибая надгробия бунтовщиков, учёных и партийных функционеров."}, {"kind": "paragraph", "text": "10"}, {"kind": "paragraph", "text": "А вот кто его удивил в своё время, так это советский писатель Борис Васильев. Автор знаменитой повести «А зори здесь тихие». Он же работал над сценарием не менее известного одноимённого фильма 1972 года режиссёра Станислава Ростоцкого. Ершаков со школьной скамьи воспринимал Васильева только в качестве создателя прозаических произведений о Великой Отечественной. Ну о чём ещё мог рассказать ветеран-фронтовик?"}, {"kind": "paragraph", "text": "Но как выяснилось, не войной единой. В девяностых и нулевых Васильев взялся за исторические романы, посвящённые средневековой Руси. Успел создать несколько — про Олега Вещего, про княгиню Ольгу, про её сына Святослава, про Владимира Крестителя и Владимира Мономаха. И ещё про Александра Невского."}, {"kind": "paragraph", "text": "Мама Ершакова, работавшая бухгалтером в галантерейном магазине, приносила домой газету, которую присылали в дирекцию по подписке. Ершаков тогда учился в старших классах, кавказская тема уже овладевала им. Он пролистывал издание, вырезая заметки о Чечне, и однажды, пропустив несколько страниц, замер. Там на весь разворот распласталась глава из книги Васильева «Князь Ярослав и его сыновья»."}, {"kind": "paragraph", "text": "Со стороны судьбы это был запрещённый приём. В тот момент она добила Ершакова точечным выпадом в мозг. Здравствуй, милый Эйзенштейн: «Головной отряд окончательно остановился. Стало чуть посветлее, рыцари стояли совсем близко, и дружинники с удивлением разглядывали боевые шлемы с птичьими когтями, рогами и звериными лапами на некоторых из них». И для закрепления: «Вместе с криками, хрипами и предсмертными стонами из глоток десятков тысяч людей вырывались клубы пара. Они застывали в морозном воздухе, пеленой зыбкого тумана покрывая поле сражения, и красное солнце без лучей вскоре повисло над побоищем, тускло отражаясь в клинках и латах». И для полного счастья: «Это потом объяснили, что бегущие, не знающие особенностей Чудского озера рыцари с ходу вылетели на место, где били ключи, а потому и лёд над ними был тонок. Лёд тонок, а ливонцы тяжелы, да — с бега, да — скопом. <…> И многим из настигающих ливонцев русских дружинников не повезло тоже. Распалённые скачкой кони не слушались поводьев, всадники поздно замечали опасность и десятками летели в последнюю купель вслед за рыцарями»."}, {"kind": "paragraph", "text": "Про дружинников, разумеется, не по Эйзенштейну. Но какая разница? Препарат «Средневековое военное дело» завершал начатое. Кольчужная мозаика с вкраплениями миниатюрных стрел, шлемов, щитов, мечей, топоров покрыла кости рук и ног Ершакова, забрала всё — от еле уловимого гребешка на макушке черепа до кончиков пальцев."}, {"kind": "paragraph", "text": "11"}, {"kind": "paragraph", "text": "С озера нещадно задувало. Холодный апрельский ветер пробирал насквозь. Ершаков, не вынимая рук из карманов короткой синей куртки, стоял на сером песке, глядя на коричневые камыши и насыщенный синим залив. Где-то здесь, да. Где-то здесь."}, {"kind": "paragraph", "text": "Чуть позади, на пригорке, громоздился гигантский чёрный бронзовый монумент, изображающий князя Александра Невского, пеших и конных дружинников. Чёрные сосредоточенные лица. Чёрные щиты, шлемы и доспехи. Чёрные лошади. И над ними — застывший, изогнутый, словно парус, чёрный Спас Нерукотворный."}, {"kind": "paragraph", "text": "Памятник впечатлял. Но что-то заставляло Ершакова скептически морщиться, не доверять скульптурной композиции. Он понимал: монумент — дань героическому мифу, образу, представлению о минувшем. В конце концов, стоило ли ждать чего-то особенного, прорывного от обычной отпускной поездки, от посещения популярного места? Вряд ли. Тем не менее Ершаков не торопился обратно."}, {"kind": "paragraph", "text": "— Неуютно как-то сегодня, — раздался за спиной мужской голос."}, {"kind": "paragraph", "text": "Ершаков обернулся и увидел дядьку лет пятидесяти, среднего роста, с русой бородой и открытым лбом, полноватого. Руки тоже в карманах, только куртка длинная, зелёная."}, {"kind": "paragraph", "text": "— Так апрель ведь, — нехотя произнёс Ершаков."}, {"kind": "paragraph", "text": "— Ну и что? На прошлой неделе относительно безветренные деньки стояли."}, {"kind": "paragraph", "text": "— На прошлой неделе меня тут не было."}, {"kind": "paragraph", "text": "— Я в курсе, — улыбнулся мужчина. — Вы вчера вечером приехали, да? На экскурсию?"}, {"kind": "paragraph", "text": "— Нет. Просто. Оценить, так сказать."}, {"kind": "paragraph", "text": "— А меня Максим Григорьич зовут, — не отставал мужчина. — Я историк, работаю здесь."}, {"kind": "paragraph", "text": "— Очень приятно, — сдержанно промолвил Ершаков, пожимая протянутую сухую ладонь. — Дмитрий."}, {"kind": "paragraph", "text": "Максим Григорьевич уставился на озеро, а потом внезапно спросил:"}, {"kind": "paragraph", "text": "— Вас чем зацепило?"}, {"kind": "paragraph", "text": "— Вы о чём? — не понял Ершаков."}, {"kind": "paragraph", "text": "— Ну как это о чём? Приехали сейчас. В такую рань уже на озере. Вот меня ещё в детстве Эйзенштейн погубил. А Симонов окончательно в порошок стёр своей поэмой. «В субботу, пятого апреля, / Сырой рассветною порой / Передовые рассмотрели / Идущих немцев тёмный строй…» А у вас как было?"}, {"kind": "paragraph", "text": "Ершаков снова повернулся к нему, споткнувшись о его карие смеющиеся глаза заговорщика, и неожиданно для самого себя выдохнул:"}, {"kind": "paragraph", "text": "— Эйзенштейн, сволочь…"}, {"kind": "paragraph", "text": "Максим Григорьевич заливисто, как-то по-детски, хохотнул."}, {"kind": "paragraph", "text": "— А потом?"}, {"kind": "paragraph", "text": "— А потом Ян и вся когорта."}, {"kind": "paragraph", "text": "— Понятно, — кивнул историк. — А ведь они привирали изрядно. И Сергей Михайлович, прежде всего."}, {"kind": "paragraph", "text": "— Да?"}, {"kind": "paragraph", "text": "— Да."}, {"kind": "paragraph", "text": "— Объяснитесь."}, {"kind": "paragraph", "text": "— С удовольствием! — воскликнул Максим Григорьевич. — Нам с детства что втирали? Злобный Ливонский орден точил зуб на Святую Русь! Но позвольте. Никакого Ливонского ордена не существовало. Был орден меченосцев, позже влившийся в Тевтонский на правах Ливонского ландмейстерства. Мало того, возьмите школьные карты с границами XIII века. Там нынешние Латвия и Эстония значатся под орденом. Но это упрощённый подход. Потому что Северная Эстония контролировалась Данией, а непосредственно орденские земли рассекались землями католических епископов."}, {"kind": "paragraph", "text": "— Интересно… А как насчёт вооружения?"}, {"kind": "paragraph", "text": "— А вот тут Эйзенштейн не слукавил. Стандартная рыцарская экипировка того времени — стёганая одежда с чепцом, кольчуга с кольчужным капюшоном и такими же чулками, подшлемник, шлем топфхельм и гербовая накидка сюрко поверх кольчуги. То есть никаких лат, которыми нас усиленно «кормили» советские писатели."}, {"kind": "paragraph", "text": "— Да вы ниспровергатель основ. Скрепы расшатываете?"}, {"kind": "paragraph", "text": "— Никакие это не скрепы и не основы, а сплошное шарлатанство. Вот саму свалку Эйзенштейн неплохо показал. Столкновение конницы и пехоты, суматоха боя, фланговые удары…"}, {"kind": "paragraph", "text": "— То есть не всё потеряно?"}, {"kind": "paragraph", "text": "— Не всё, но многое."}, {"kind": "paragraph", "text": "— Что же ещё?"}, {"kind": "paragraph", "text": "— Количество. У Эйзенштейна целая кавалерийская бригада снималась. Вы в курсе? И когда романистов наших читаешь, волосы шевелятся на голове. Там ведь железные лавины… Сказочники они, короче говоря. Летопись сообщает про 50 пленных немцев и 400 погибших. Но кем они являлись? Согласно европейским источникам, в битве пали всего двадцать тевтонских рыцарей и шесть угодили в плен. Если учесть, что каждого рыцаря сопровождала свита примерно из десяти бойцов, а во всём Ливонском ландмейстерстве насчитывалось максимум 100 братьев, то можно сделать вывод: в орденском войске на озере числилось от силы 30 рыцарей, наступавших в авангарде, плюс отряд дерптского епископа — вассалов 10–15 с подчинёнными. Ну и эстонское ополчение."}, {"kind": "paragraph", "text": "— Итого?"}, {"kind": "paragraph", "text": "— Итого около одной тысячи со стороны ливонцев и порядка полутора — двух тысяч с нашей. Не более. И главное разочарование: скорее всего, никто под лёд не проваливался. В ранних упоминаниях ничего об этом нет. Зато есть в рассказе о битве на реке Омовже, которая произошла за восемь лет до Ледового побоища. Тогда отец Невского Ярослав разбил гарнизоны Дерпта и Оденпе, и часть немцев действительно утонула, будучи оттеснённой на речной лёд. И вероятно, поздние авторы… кхм… позаимствовали данный эпизод для битвы на Чудском."}, {"kind": "paragraph", "text": "— Ещё скажите, что и спланированного натиска на Русь не было, — саркастически заметил Ершаков."}, {"kind": "paragraph", "text": "— Так ведь и не было! — опять хохотнул Максим Григорьевич. — Немцы кампанию в 1240-м начали. А если точнее — дерптский епископ и братья из соседних орденских владений. В основном прежние меченосцы. Они Изборск взяли и псковскую рать уничтожили. Там с нашей стороны от 600 до 800 человек полегло. Оттого и Псков сдался — всех защитников поубивали в чистом поле. А весной 1242-го Невский город отбил и в Эстонию пошёл. Но там, кстати, тоже нехорошо получилось. Ливонцы передовой полк раскатали и снова на русский берег двинулись. Ну а дальше — побоище, перемирие... Вообще, я склоняюсь к мысли, что немцами в Ледовом командовал Герман фон Буксгевден, епископ Дерпта. Его люди, к слову, первыми побежали. Зато орденский авангард наши почти полностью перебили. А магистр в рогатом шлеме пусть уж на совести Сергея Михайловича останется."}, {"kind": "paragraph", "text": "— Ну если у немцев только двадцать рыцарей погибло, то, получается, не побоище, а неизвестно что. Пустяк?"}, {"kind": "paragraph", "text": "— Почему же? 400 зарубленных и 50 попавших в плен — серьёзные потери по тем временам. Правда, большинство из убитых, естественно, не рыцари, а те, кто их сопровождал, — оруженосцы, сержанты, арбалетчики. Про эстонцев, опять же, не забывайте. Прилично выходит. А вы — пустяк… Хотя, конечно, если брать картину по Балтии в целом, битва на Чудском по масштабности не на вершине рейтинга, а где-то у подножия. Но однозначно круче той же Омовжи. Правда, чем выше по списку, тем жёстче — Раковор, Шауляй, Карузен, Ашераден, Дурбе…"}, {"kind": "paragraph", "text": "— А вы после таких разборов в истории российской не разочаровались?"}, {"kind": "paragraph", "text": "— А при чём тут разочарование? — обиженно отпрянул Максим Григорьевич. — Наоборот, ещё интересней стало! Главное ведь — не соответствие неким политическим или идеологическим концепциям. Главное — по возможности детально и достоверно представить происходившее. Сложить мозаику, пазл. Вернуть то первое чувство, возникшее в детстве при просмотре фильма. Понимаете?"}, {"kind": "paragraph", "text": "12"}, {"kind": "paragraph", "text": "Противная каспийская морось сыпала по лицу, заставляя надвигать на глаза капюшон толстовки. Застегнув молнию куртки и поправив на плече рюкзак, Ершаков обернулся на мёрзнущих коллег, вжимающих головы в плечи. Все одеты по погоде — в джинсах, осенних ботинках и куртках поверх свитеров, но, когда ты вынужден стоять на улице, морской ветер и сеющий дождь быстро одолевают. А деваться некуда. Они толпились у забора из листового железа, за которым темнел бетонный недострой. У торчавшего рядом выкрашенного в зелёный одноэтажного здания диспетчерской — сразу за ним мок небольшой дворик с открытыми воротами и асфальтовой дорожкой, ведущей в редакцию газеты, — осматривали тротуар и что-то записывали полицейские и сотрудники Следственного комитета. Тут же была припаркована испещрённая пулевыми отверстиями белая легковушка. Дождевые капли расплывались по её крыше, заднему стеклу, капоту."}, {"kind": "paragraph", "text": "Недавно здесь расстреляли главного редактора газеты, известного в Дагестане независимого журналиста, не стеснявшегося отвешивать информационные оплеухи чиновникам и силовикам. Он собирался домой и вызвал такси. Как только машина подъехала и редактор спустился, из-за угла выбежали двое в чёрных спортивных костюмах с травматами, переделанными под стрельбу боевыми, и открыли огонь. Таксист мгновенно выскочил из салона и заперся в диспетчерской. Главред попытался укрыться за автомобилем, но, получив несколько ранений, упал лицом вниз. Один из киллеров произвёл контрольный в спину. Затем к месту расправы подлетела серая «Приора», забравшая убийц. Очевидцы вызвали медиков, но пострадавший скончался в карете скорой помощи."}, {"kind": "paragraph", "text": "Корреспонденты ждали комментариев. Гладковыбритый предпенсионного возраста полковник юстиции в синем мундире, несмотря на дождь, без верхней одежды и фуражки, выйдя за ворота, кивнул телевизионщикам и, когда журналисты обступили его, произнёс дежурное:"}, {"kind": "paragraph", "text": "— Возбуждено уголовное дело по статьям «Убийство» и «Незаконный оборот оружия». Следствие ведётся. Личности подозреваемых устанавливаются. О мотивах говорить пока рано, отрабатываются разные версии."}, {"kind": "paragraph", "text": "На него посыпались вопросы."}, {"kind": "paragraph", "text": "— А правда, что профессиональный мотив является основным?"}, {"kind": "paragraph", "text": "— Есть информация, будто подозреваемые уже опознаны. Так ли это?"}, {"kind": "paragraph", "text": "— О чём свидетели говорят?"}, {"kind": "paragraph", "text": "— Больше ничего не могу сказать, — ответил полковник и повернул к воротам."}, {"kind": "paragraph", "text": "Ершаков проскользнул вперёд."}, {"kind": "paragraph", "text": "— Извините. А вы знали убитого?"}, {"kind": "paragraph", "text": "Полковник резко остановился, смерив его недоумённым взглядом."}, {"kind": "paragraph", "text": "— Молодой человек, вы о таком спрашиваете…"}, {"kind": "paragraph", "text": "— И всё же?"}, {"kind": "paragraph", "text": "Полковник покосился в сторону других репортёров."}, {"kind": "paragraph", "text": "— Вы не местный, что ли?"}, {"kind": "paragraph", "text": "— Нет."}, {"kind": "paragraph", "text": "— Из Москвы?"}, {"kind": "paragraph", "text": "— Нет."}, {"kind": "paragraph", "text": "— Видите, как у нас тут? — он кивнул на покрытое пробоинами такси. — Вам дома не сидится?"}, {"kind": "paragraph", "text": "— Не сидится, — не удержался Ершаков."}, {"kind": "paragraph", "text": "Полковник замолчал, покачал головой и шагнул во двор."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
4	mrd6-fayansovyy-lev	Фаянсовый лев	10	mrd6/mrd6-fayansovyy-lev.png	data:image/jpeg;base64,	Город спал. До рассвета больше часа. Придорожные фонари бросали жёлтые лучи на кучи смёрзшегося валунами со следами от лопат снега, а те, казавшиеся фиолетовыми, блестели мириадами искр, словно крошечными осколками стекл	[{"kind": "image", "path": "mrd6/mrd6-fayansovyy-lev.png", "caption": "Иллюстрация Екатерины Ковалевской"}, {"kind": "paragraph", "text": "Город спал. До рассвета больше часа. Придорожные фонари бросали жёлтые лучи на кучи смёрзшегося валунами со следами от лопат снега, а те, казавшиеся фиолетовыми, блестели мириадами искр, словно крошечными осколками стекла. Меж сугробов пряталась тропинка, по зиме бывшая единственной дорогой, ведшей от старых деревянных бараков через еловый пролесок в город. По ней шла, скрипя сапогами, старушка в пёстрой каракулевой дублёнке. За собой она волочила пустую тележку на двух колёсиках, которые крутились лишь изредка, когда встречались с рассыпанным песком или реагентом. Шла старушка медленно, холодный ветер мешал ей высунуть лицо из-за плотного, намотанного до самых глаз шарфа, чтобы осмотреться. Лапы пушистых елей, укутанных в белые одеяла, раскачивались от ветра и осыпа́ли шедшую сухими снежинками, приятно коловшими веки."}, {"kind": "paragraph", "text": "Вид женщина имела скорбный, жалкий. Каждый шаг давался ей с трудом, а множественные одёжки только довершали плеяду препятствий, с которой ей доводилось сталкиваться при ходьбе."}, {"kind": "paragraph", "text": "Небо, возвышавшееся над мраком леса, было заволочено облаками. А за спиной старушки, у самого горизонта, сияло зарево от теплиц да порой сверкали проблесковые маячки шедших на посадку после учебных вылетов самолётов. Маячков этих она не видела, как и не слышала гул двигателей. Зато впереди уже начала проглядывать автодорога, отрезавшая лес от города."}, {"kind": "paragraph", "text": "Старушка остановилась, поправила тяжёлую шапку и проморгалась. Она взволнованно вертела головой, пока не обнаружила у себя за спиной в нескольких шагах остов старой осины, едва торчавший из сугроба. Очевидно, он поперву остался незамеченным из-за навалившего за ночь снега. Женщина сняла варежку с левой руки и, взяв её правою, словно метлой, смахнула со своего ориентира перламутровую пудру, затем отряхнула её о подол дублёнки и надела обратно."}, {"kind": "paragraph", "text": "Через несколько минут старушка добралась до дороги и прошла несколько десятков метров вправо до дорожного знака, означающего место автобусной остановки. Она задрала рукав и взглянула на часы. Её привлёк свет фар выглянувшего из-за поворота автобуса. Свет отразился от знака и с прерывистой постепенностью становился ярче, пока вдруг не погас. Она знала, что после этого автобус прибудет на остановку через двадцать — двадцать пять секунд."}, {"kind": "paragraph", "text": "Водитель дождался, пока она пройдёт к задним сиденьям, и только потом тронулся, нагоняя упущенные секунды на пологих поворотах. В автобусе было жарко. Очевидно, печка обеспечивала комфорт не пассажиров, зашедших с мороза в зимних ансамблях, а водителя, весь день работавшего в одном свитере."}, {"kind": "paragraph", "text": "Вот уже несколько лет старушка два раза в неделю ездила на первом утреннем автобусе. Она до того аккуратно соблюдала своё расписание, что водитель иной раз простаивал на её остановке лишних несколько минут, когда не встречался с ней в привычном месте в привычный час. И ещё ни разу не случалось такого, чтобы это было напрасно. Вот проходит минута, две, и знакомая фигура, пыхтя и торопясь, появляется в зеркале. Старушка, расшаркиваясь, с извинениями торопится взобраться по ступеням и суёт ему в руки десятирублёвую монету."}, {"kind": "paragraph", "text": "Короткий период их общения занял две или три поездки. Водитель хотел перестать взимать с неё плату, а она с упёртой гордостью стояла на том, чтобы продолжить уплачивать. Была она немногословной, косноязычной и оттого казалась подозрительной и невежливой. Бороться он перестал, а по другим вопросам вытянуть из неё хоть слово не удавалось, потому впоследствии они стали изъясняться лишь движениями головы и глаз. Однако нежные чувства он всё же испытывал к ней неизменно как к милому утреннему ритуалу. Примерно такие же чувства она испытывала… нет, не к нему, а к своему осиновому пню у выхода из пролеска."}, {"kind": "paragraph", "text": "Старушка высадилась, как и обычно, на остановке у продовольственной базы и потащилась по живым лабиринтам пробуждающихся торговых мест к овощным складам. В помещении она опустила шарф, и в лицо ударил приятный тёплый воздух. Несмотря на старость, кожа у неё была гладкой, но до того тонкой, что на ней были видны множественные синие капилляры, испещрявшие её лицо до самых корней седых волос. Особенно выделялся крупный, висевший крюком нос. Он был разукрашен самыми разными цветами, вплоть до зелёного на переносице. Зеленоватая кожа темнела во впадинах у глазниц, где лежали два мелких мутных глаза с голубой радужкой. Старушка всё шевелила безгубым ртом, словно что-то бормотала, однако же это она так чесала коловший от мороза подбородок о каракулевый воротник."}, {"kind": "paragraph", "text": "Она выглядела совершенно чуждой этому миру снующих туда-сюда и сталкивающихся друг с другом подвижных продавцов и таких же подвижных покупателей. База являла собой едва ли не цельный живой организм, ну или, на худой конец, колонию муравьёв. Кругом был сущий балаган, он подчинялся внутренним законам и порядкам, которые не были очевидны обывателю. На бетонных полах вечно оказывались лужи разного происхождения, но непременно имевшие один и тот же кислый сброженный запах. Верно, бетон за годы эксплуатации впитал в себя эту закваску и стал источать знаменитый аромат при попадании на него любой жидкости, будь то вода или даже отдушка. Такими же вечными казались сырые огрызки гофрированного картона с отпечатанными на них изображениями бананов и пальм, бесконечные паллеты, никогда не пустевшие мусорные корзины. На пенопластовых подложках всегда лежала рыбья требуха, вокруг которой ошивалась свора жирных и сонных котов."}, {"kind": "paragraph", "text": "Старушка шла привычной дорогой, встречала знакомые лица и прилавки. На приёмке толпились грузовики с бессмысленными в такой мороз рефрижераторами. В воротах виднелось небо, постепенно начинавшее светлеть. За молочным отделом следовал рыбный. В некотором отдалении располагалось несколько столиков возле прилавка с выпечкой и большими термосами с горячим чаем. Ей нравилось смотреть, как озябшие с холода работники поспешно наслаждаются своим завтраком, всё споря, хохоча и ругаясь. Она представляла, как, закупившись, они разъедутся по делам, распространяя жизнь, которая рождалась здесь, на базе, в такую рань. И она ощущала себя частью этой жизни, пускай не столь органичной и шумной, но всё же будто незаменимой. Но больше завтракающих мужчин она любила лавку с корейскими салатами и закусками. Проходя мимо неё, старушка всякий раз засматривалась на экзотические соленья с удивительным ароматом и давала себе слово однажды всё-таки попробовать какую-нибудь особенно инопланетную закуску. За прилавком стояла круглая азиатка в засаленном синем фартуке, которая так же, как и водитель автобуса, любила улыбнуться и кивнуть старушке при встрече."}, {"kind": "paragraph", "text": "Она прошла всю базу, добираясь до овощного отдела, но и там не остановилась, а дошла до самого тупика, у которого торговали фруктами."}, {"kind": "paragraph", "text": "Старушка отсчитала пятьсот рублей пятидесятирублёвыми купюрами и купила три с половиной килограмма жёлтых лимонов, каждый из которых любовно выбирала. В пакет отправлялись лишь те, которые, по её ощущениям, обладали тонкой шкуркой и твёрдой мякотью. Азербайджанец, торговавший лимонами, терпел медлительную старушку иной раз минут по десять и с советами лезть перестал уж как год."}, {"kind": "paragraph", "text": "Нагрузив свою тележку лимонами, она покинула базу и пошла вдоль трассы к автобусной остановке, меся сапогами чёрный от выхлопов снег. Вскоре она поймала набитую маршрутку и, стоя у входа, добралась до центра."}, {"kind": "paragraph", "text": "Там, возле церкви Святой Троицы, был разбит рынок, на котором, в отличие от базы, торговали розницей. Начинался он у самых ворот церкви. На бордюрах вдоль ограды располагались вязальщицы со своими носками и шапками, дальше тянулись палатки со всякими безделицами, начиная от петард и фейерверков и заканчивая скалками и футбольными мячами. К появлению старушки не все тенты ещё успели натянуть. Продавцы поочерёдно помогали друг другу, борясь с ветром, который норовил вырвать у них из рук брезент. Как всегда, первым ставил палатку продавец рождественских гирлянд. Прохожие ещё продолжали активно скупать иллюминацию, несмотря на то что новый год начался уж три недели тому назад."}, {"kind": "paragraph", "text": "Сразу за лавкой с гирляндами была небольшая площадь, которую занимали безрукие и безногие музыканты и стая прикормленных голубей. Голуби постоянно толпились в ожидании завтрака. Они до того привыкли к людям, что уворачивались от пинков неохотно и лениво, а иной раз могли схлопотать так, что летели перья."}, {"kind": "paragraph", "text": "За площадью начинались продовольственные ряды. Туда старушка и держала путь. Она поставила свою тележку на ступени, ведшие в магазин электроники, и стала готовиться к торговле. Для этого у неё был приспособлен деревянный ящик, который она с помощью верёвки крепила к шее, а одним из бортов упирала в живот. Расположив на ящике лимоны и тяжёлый мешочек с мелочью для сдачи, она двинулась меж рядов."}, {"kind": "paragraph", "text": "Она торговала лимонами по тридцать рублей за штуку. Покупали их у неё чаще из жалости. При всей своей немногословности она умела бойко выкрикивать цену своего товара и настойчиво навязывалась покупателям, отвлекая от выбора продуктов, за которыми они пришли на самом деле. Она сообщала, что её лимоны привезены из солнечной Грузии, что лучше её лимонов на всём рынке не найти, что выращены они были её сестрой без использования вредной химии. Люди потом ещё долго не могли проглотить ком от обиды, что легальные продавцы не прогнали попрошайку."}, {"kind": "paragraph", "text": "А среди продавцов было заведено негласное правило не трогать «лимонщицу», как её несправедливо называли. Несправедливо потому, что она торговала не только лимонами. В летний сезон она предпочитала зелень, в августе в ход шла кукуруза, которую сборщики позволяли ей нарвать с поля в количествах, не превышающих границы приличия. На рынке она была своеобразной знаменитостью, с которой никто не имел никаких отношений, но и гнать которую никто не спешил, даже если это угрожало некоторыми убытками. Незначительные же убытки из-за «лимонщицы» действительно были. Она была до того настойчивой, что некоторые покупатели шарахались, предпочтя купить те же помидоры в другом месте."}, {"kind": "paragraph", "text": "Баланс был нарушен вчера. Торговец мясом, тучный мужчина лет пятидесяти, накричал на неё, когда из-за той сбежали покупатели. Чуть позже, остыв, мясник попросил прощения. Она же ничего не ответила, чем тут же вызвала добавочную порцию обзывательств с его стороны. Весь оставшийся день старушка сторонилась его и с опаской поглядывала на него издали. Он был хорошим торговцем, любившим своё дело. Он мог сделать скидку или отдать лучший отруб покупателю, который ему чем-то приглянулся. Много шутил, смеялся, филигранно и, что ли, уважительно обращался с мясом: не швырял его, как прочие мясники, рассекал мякоть в одно резкое и точное движение так, чтобы не оставалось «волны» и «заусенцев» на срезе. Всё у него шло в ход, даже кости, которыми он торговал за гроши. Огрызки же скармливал собакам. Имел он привычку погладить свою лысую голову, иногда забывая, что только что потрогал мясо. На эти случаи у него были припасены влажные салфетки. Старушка весь день, глядя на мясника, злилась и ревновала, что он со всеми вежлив и светел, а с ней повёл себя грубо. Её бесил его сытый и довольный вид. По внешности она сделала вывод, что он сам любитель полакомиться мясом и что-то в этом понимал. Кустистые брови, орлиный нос, карие глаза и акцент выдавали в нём южного человека, а какой мужчина с юга плохо разбирается в мясе? Наторговала она в тот день всё же хорошо, распродав все лимоны, и с чувством выполненного долга поспешила домой."}, {"kind": "paragraph", "text": "По пути старушка зашла в магазин за продуктами к супу и бутылкой кефира, который страстно любила. В очереди на кассе она столкнулась со своим обидчиком-мясником. Тот, держа в руках корзину, вот-вот собирался выкладывать продукты на ленту, когда она подошла сзади. Сама того не понимая, она будто пыталась обойти его сбоку. Он чувствовал чьё-то присутствие позади и выставлял корпус так, чтобы не дать себя обойти. Старушка же спешила приблизиться к ленте, потому что боялась: товары в руках грозили рассыпаться по полу. Обернувшись, мужчина сразу узнал «лимонщицу». Успевший раздражиться, он пустил её вперёд себя, зачем-то наговорив вдогонку каких-то неприятных колкостей. Она, вся красная, с большим трудом дождалась, пока её рассчитают и быстро двинула домой."}, {"kind": "paragraph", "text": "Теперешним же утром она решила, что больше не даст себя в обиду, и первым делом двинулась торговать к его лавке. Она с наивной детской дерзостью стала громко декламировать свой однострочный прейскурант, обращаясь не к потенциальным приобретателям лимонов, а к мяснику. Его умиляло поведение старушки, и он, улыбаясь, игнорировал её, продолжая показывать покупателю лоснящуюся мякоть свиной лопатки. Она не унималась и настойчиво зудела над ухом хмурого покупателя, который в конце концов не вытерпел и несдержанно махнул на неё рукой, словно отгонял комара. Она сказала что-то неаппетитное про мясо, и это задело гордость мясника:"}, {"kind": "paragraph", "text": "— Тётя, брысь отсюда! Ссаными тряпками погоню! — бросил он и тут же обратился к покупателю: — Два кило?"}, {"kind": "paragraph", "text": "— Он руки-то не моет. Отраву продаёт, — пробормотала старушка."}, {"kind": "paragraph", "text": "— Иди лесом, ведьма!"}, {"kind": "paragraph", "text": "Старушка предприняла ещё пару попыток образумить несчастного покупателя, который уже успел полезть в кошелёк за деньгами. Он с прежней несдержанностью отмахнулся от неё, а она в ответ плюнула в его сторону. Мясник схватил головку чеснока, валявшуюся под рукой, и бросил в «лимонщицу». Оскорблённая, но довольная, она медленно заковыляла в сторону, изображая на лице гримасу глубокого несчастья, и радовалась, когда сердобольные свидетели стычки охали и брались за горло при взгляде на неё."}, {"kind": "paragraph", "text": "В течение дня она мимоходом ещё больше пяти раз проходила возле мясной лавки и внутренне ликовала, когда мясник, завидев её издали, начинал предупредительно махать головой и руками, напуская на себя грозный вид. Она с изяществом подряхлевшей кокетки обходила его стороной, делая вид, будто и не собиралась пастись на его территории. Это был ему такой укол: мол, я, старая, обиды забываю, а ты, мужичок, всё мелочишься, как ребёнок, и думаешь, будто я тут стану истерики закатывать. Больно надо!"}, {"kind": "paragraph", "text": "Ей доставлял удовольствие не столько факт мучения обидчика, сколько осознание: он ничего не может предпринять против неё. Она безраздельно властвовала над его нервами и упивалась властью. Нищая и продрогшая, она чувствовала себя много уютнее в кишках шумного рынка, чем он в своей лавке на мягком стуле и с тепловой пушкой под ногами."}, {"kind": "paragraph", "text": "Быстро распродав все лимоны, она поспешила домой, купив по пути бутылку кефира."}, {"kind": "paragraph", "text": "Её двухэтажный деревянный барак представлял собой убогое зрелище. Должный стать временным жильём для строителей гидроэлектростанции, он вмещал в себе жильцов вот уже шестьдесят с лишним лет. Годы не пощадили его. Весь косой, с поросшей перманентным мхом двускатной крышей, он соседствовал с тремя такими же домами. Все они были выкрашены одинаковой зелёной краской, которая облупилась бог знает сколько лет тому назад. Под слоем зелёной был слой синей краски, под ним ещё более древний красный, и дальше — жёлтый. Расположись цвета не слоями, а последовательно — фасады бы выглядели жизнерадостно. Однако как есть они вгоняли в тоску, а некоторых старожилов при долгом рассмотрении и под приличным градусом шумная палитра вовсе могла погрузить в транс."}, {"kind": "paragraph", "text": "В подъезд вела тяжёлая металлическая дверь на бессмысленной пружине, которой не хватало упругости для сжатия. Лестница была сложена из подгнивших досок, которые менялись редко. Свежие доски жильцы были вынуждены брать с боем. Каждую зиму потолок на втором этаже сковывался толстой ледяной шишкой, которая, тая по весне, непременно корёжила доски. Возле каждой двери висел почтовый ящик, и почти в каждом торчало по одной-две игнорируемые платёжки. Дом вечно шумел, трещал и скрипел не то от ветра, не то от сковавшего его мороза, не то от топота жильцов."}, {"kind": "paragraph", "text": "Старушка поселилась тут совсем недавно, два с лишним года назад. Раньше они жили с мужем в самом центре, возле рынка, в небогатой, но приличной квартире с двумя комнатами. Там было уютно: всякая деталь так прикипела к месту, что казалось, будто она там будет вечно. Наживалось всё с трудом и оттого сильно ценилось. Было тесно, но захламлённой квартиру назвать было нельзя. Напротив, светлое пространство казалось уютным и живым. Старушка запомнила свой дом тёплым и защищённым. На фоне всегда что-то шумело, будь то радио или телевизор. Её Федя, вечно что-то читавший, любил отвлечь её от рутины и громко пересказать небылицу, найденную в журнале. Он кричал ей через всю квартиру, а она, шурша в кухне, не вслушивалась в смысл слов, но радовалась, что Федя, увлечённый статьёй, всё же находил в себе силы прерваться и поделиться открытием с нею. Она помнила мягкую кровать с тяжёлыми одеялами и шестью подушками, которые они по три складывали одну на другую. Возле кровати туалетный столик с хрустальной вазой, в которой они хранили всякие погремушки. В стенке на нижней полке она держала иконы, у которых часто молилась на коленях."}, {"kind": "paragraph", "text": "Детей у них с Федей не нажилось. Но были они счастливы и вдвоём. Два неразлучника, они не могли и дня провести порознь. Её, бывало, клали в больницу на операцию, а он места себе не находил. Всё ходил по дому кругами, плакал и разговаривал с иконами. Потом встречал её, долго и запальчиво рассказывал, что за время её отсутствия успело произойти. И всякая мелочь казалась обоим важной. Мир их был маленький, ограничивался домом, рынком и больницей, но он столь внимательно изучался, чувствовался, что казался бесконечно огромным. У них была целая Вселенная в двух комнатах. В ванной жил паук, которому они дали какое-то смешное имя. Они наблюдали за ним, шутили над ним. Как-то раз, застав его совершенно неподвижным, заволновались, что он умер, а выяснилось, что неподвижной была его сброшенная кутикула. За стеной жила молодая семья с ребёнком, и они с Федей подслушивали за ними и знали про них всё, что проговаривалось вслух. Каждую зиму они размораживали холодильник и относили портящиеся продукты на балкон. Продукты смотрелись там как-то странно-волшебно: непривычно и оттого необыкновенно. Как теплело, намывали до блеска окна, сменяя один другого в ролях мойщика и страховщика. А каждое лето, в начале июля, с утра, пока солнце ещё не успевало раскалить воздух, Федя выносил на улицу ковры и, развесив их на сушилке, упорно выбивал. Она ждала его, пекла блины, переворачивая их прямо пальцами с огрубевшей кожей."}, {"kind": "paragraph", "text": "Когда Федя умер, Вселенная её схлопнулась. Случилось это вечером, и она была уверена, что сама не доживёт до утра. Она этого не страшилась, но ужасно хотела. Но вот взошло солнце, а она всё ещё на земле. Было так странно, что солнце решило взойти, будто ничего не произошло. Мир её осиротел, стал по-злому бессмысленным. У неё не переставая кружилась голова, и смерть казалась близкой и необходимой. Она не переставала рыдать, обнимая его вещи. Но она продолжала жить, злясь на себя, считая себя предательницей. Разве может человек жить без сердца, без души? К вечеру второго дня ей стало ясно, что может."}, {"kind": "paragraph", "text": "Ей пришлось заниматься завершением его земных дел. Хоронить его на загородном кладбище — место они предупредительно купили вопреки её протестам — она категорически не желала. Это было далеко, а она хотела, чтоб он был рядом. Всё случилось быстро, скомканно и непонятно. Откуда-то появился человек, который предложил комнату в бараке в обмен на квартиру. Разницы как раз хватало на похороны на центральном кладбище, на поминки, на памятник. Быстро составили бумаги, подписали."}, {"kind": "paragraph", "text": "Пока она не попрощалась с Федей, никто прогонять из квартиры не стал, сочувствуя её горю, но на пятый день ей помогли сложить и перевезти вещи в барак."}, {"kind": "paragraph", "text": "Многое дорогое сердцу ушло на помойку. В убогую комнатку ничего не вмещалось. Оставила она при себе лишь самое необходимое, чтобы протянуть оставшиеся ей дни. Среди сохранённых вещей были иконы и фаянсовый бюст льва, который в восемьдесят восьмом из Тифлиса привёз брат Феди. Это была небольшая дурно сделанная скульптурка с крупный кулак, покрытая желтоватой глазурью. Под глазурью на львиный нос и глаза капнули по кляксе чёрной краски. Капнули неосторожно, и оттого лев немного косил. Широко раскрывший пасть, он, очевидно, грозно рычал, но воспринимать его всерьёз с этими косыми глазами было совершенно невозможно. Они с Федей любили этого льва, разговаривали с ним, жалели его, несчастного. Была в нём и прелесть: при правильном угле обзора у льва на ушах и гриве свет создавал волшебные перламутровые узоры."}, {"kind": "paragraph", "text": "Стоял этот лев теперь всегда возле её скрипучей кушетки, и перед сном она рассказывала ему, чего она узнала нового, как прошёл её день. Он, как всегда, не отвечал, но она знала, что лев всё слышит и радуется, что с ним говорят. А она радовалась, что он её слушал, что был рядом. Случалось, когда ей приснится страшный сон, она поднималась на подушке среди ночи и вспоминала, что рядом стоит их фаянсовый лев, и не могла этому нарадоваться. Она протягивала к нему руки, на ощупь находила его, целовала и прижимала к груди. Намёрзшийся за ночь, лев согревался от тепла её тела, а она тихонько плакала и, бывало, засыпала с ним в обнимку."}, {"kind": "paragraph", "text": "И вот теперь вечером она, всё ещё возбуждённая, рассказывала льву о стычке с мясником: как он её ругал и как она постояла за себя. Хвалилась, как она оттого вся выпрямилась, посветлела. Лев слушал её с разинутой пастью, а за окном выла вьюга."}, {"kind": "paragraph", "text": "Мелкие ледышки с треском вреза́лись в дребезжащее окно, подоконник покрывался инеем. Старушка сидела на кровати во мраке комнаты при тусклом свете абажурной лампы и радовалась, что наконец может рассказать льву что-то новое и необыкновенное. Увлечённая, как ребёнок, она не замечала, как мёрзнут её босые ноги на голых досках пола. Убогое жилище показалось ей тем вечером не таким уж гадким и невыносимым."}, {"kind": "paragraph", "text": "Ночью она долго не могла заснуть: за окном бушевало, что-то не давало ей покоя. Она прокручивала в голове сцены прошедшего дня, держа льва на груди и гладя его. Вдруг, опомнившись, она вскочила с кровати и прошла в прихожую. В темноте она нащупала висящую на гвозде дублёнку, залезла в карман и вытащила оттуда свою выручку."}, {"kind": "paragraph", "text": "Она убрала её в коробочку, которую держала под стопкой одежды в шифоньере, после чего легла, отогрелась и вскорости уснула."}, {"kind": "paragraph", "text": "Следующим утром старушка сильно удивила своего водителя, явившись на остановку в неположенный день, но он повёз её без лишних вопросов. На базе она не задерживалась и даже лимоны выбирала без дотошности. Не порадовала кивком кореянку, прошла мимо завтракающих мужчин… Она спешила продолжить свой конфликт с мясником."}, {"kind": "paragraph", "text": "Он на её появление отреагировал живо и грозно, но уже сам себе смеялся. Было нелепо всерьёз враждовать с «лимонщицей», но она была такой въедливой и приставучей, что у него не оставалось другого выхода, кроме как отвечать ей. Весь день они лаялись. Он не стеснялся в выражениях, а она стала за ним поспевать. Называла его толстым, вонючим, уродливым и глупым."}, {"kind": "paragraph", "text": "Вечером она со всё возрастающей вовлечённостью рассказывала обо всём льву, задыхаясь, сбиваясь, вспоминая упущенные подробности, особенно те, которые касались её острого злословия. Лев сиял в свете лампы, переливаясь на ушах и гриве всеми цветами радуги."}, {"kind": "paragraph", "text": "Всю неделю до воскресенья она собачилась с мясником. На четвёртый день она ему надоела. Отвечать он ей стал уже лениво, а потом и вовсе пренебрежительно, жалея её и весело поражаясь, откуда в ней столько азарта и запала. Ей его поддавки не нравились, и она находила всё новые способы уколоть, чтобы вызвать в нём живую реакцию. Стоит отдать ей должное: достать она умела."}, {"kind": "paragraph", "text": "В воскресенье на рынок она не пришла. Это был день, когда она навещала Федю. Подумывала зайти на обратном пути к мяснику на пять — десять минут, но отогнала эти мысли. А вечером раскаивалась перед львом, что пробыла на могиле не больше двадцати минут: замёрзли ноги."}, {"kind": "paragraph", "text": "С понедельника она вновь вступила в бой. Мясник уже не давал ей спуску — иной раз мог швырнуть в неё чем-нибудь. Прочие торгаши сперва тяготились конфликтом, старались их примирить, но впоследствии привыкли, а потом и вовсе смеялись над ними, в большей степени, конечно, над мясником. Все симпатии были обращены к нему, но старушку это не расстраивало. Она радовалась вниманию, которым её удостаивали, какого бы сорта оно ни было. Постепенно та стала замечать, что мясник — живой человек, у которого бывает разное настроение. В один день он был резким и злым, в другие же — каким-то задумчиво-печальным. Она же бежала сумасшедший марафон, изо дня в день пребывая в игривом расположении, которое, как глоток свежего воздуха, она почувствовала совсем недавно и никак не могла этой новизной пресытиться. В «печальные» дни мясник ей отвечал слабо, не хлёстко, а она же, словно этого не замечая, давила настойчивее, злее. Она была как разбесившаяся собака, которая не чувствует, когда следует прекратить."}, {"kind": "paragraph", "text": "Спустя месяц все уже устали, кроме неё. Мясник из одной только жалости посыпал её оскорблениями и проклятиями, изображая при этом весёлый задор. И та уже понимала, что все их склоки — какая-то сама собой сложившаяся неприличная игра, в которую страсть как хотелось играть."}, {"kind": "paragraph", "text": "Старушка стала браниться со своим врагом уже не так похабно и без прежнего желания уколоть. Всё превратилось в некий ритуал, который успел устареть, но который она, видимо, только одна на всём рынке хотела соблюдать. Потому подход её смягчился. Она чувствовала, что если перегнёт палку, то рано или поздно торговцы устанут и погонят её. Постепенно склока «лимонщицы» и мясника превратилась в нечто абсурдное: взрослый мужчина и старая женщина поносят друг друга на чём свет стоит улыбаясь, с искренней нежностью в голосе."}, {"kind": "paragraph", "text": "В марте с юга из деревни неожиданно приехал племянник, сын Фединого брата. Она застала его трущимся на пороге её халупы, когда возвращалась домой после очередной баталии со своим врагом. Вид племянник имел уставший и раздражённый. Под ногами у него валялась набитая вещами дорожная сумка."}, {"kind": "paragraph", "text": "— Где тебя носит, тётка? — несдержанно спросил он."}, {"kind": "paragraph", "text": "Она пустила его в дом, напоила чаем. Он, отогревшись, смягчился и попросил прощения за грубость. Она радовалась приезду родственника, но уже догадывалась, что визит его связан с какой-то неприятной историей. К тому же он никогда не приезжал один, без своей Люси. Было это полгода назад — больно рано он пожаловал вновь."}, {"kind": "paragraph", "text": "Опасения подтвердились. Оказалось, что с Люсей они разошлись. Загулял он, и она его погнала. Вот он и явился к тётке, поджавши хвост."}, {"kind": "paragraph", "text": "За ужином он много и подробно ругал жену, сообщал о своих планах. Говорил, что пробудет у старушки несколько месяцев, пока не найдёт работу и не встанет на ноги. Пил специально припасённую с собою водку и постепенно делался слизью, наматывая сопли на кулак. Она же мало его слушала: всё глядела в окно. Там было до того красивое небо, что она не могла оторвать взгляда. Множество мелких облачков, похожих на отару овец, сбились вместе. Сердцевины их были тяжелы и темны, но края озарялись ярким жёлто-розовым свечением. Они простирались до самого горизонта, где огарок солнца сливал их в однородную густую массу, которая, словно масло, была намазана на до боли яркий и печальный закат. Пока сидели, небо становилось всё более глубоким, облака, темнея, медленно уползали из виду. Клочок неба над горизонтом багровел, растворяясь в ночи, и сливался с острыми верхушками деревьев. И уже нельзя было сказать: небо впивается в них или они в небо."}, {"kind": "paragraph", "text": "Она попросила у соседа раскладушку для племянника и, когда вернулась с ней, застала того спящим на своей кровати. Будить его она не стала, а постелила себе на раскладушке."}, {"kind": "paragraph", "text": "Среди ночи проснулась в холодном поту, испугавшись, что он, пьяный, будет ворочаться и ненароком собьёт с пьедестала льва. Тихонько встав, чтоб не разбудить племянника, она взяла скульптуру, легла, обнявшись с нею, и продолжила спать."}, {"kind": "paragraph", "text": "Вопреки ожиданиям, бытовых хлопот с новым сожителем в её жизни меньше не стало. Напротив — их количество сильно увеличилось. Как будто заехал не один сосед, а целый табор. Возвращаясь с рынка домой, она непременно заставала одну и ту же картину: пьяный племянник спит сидя за столом или лёжа в кровати. Кругом разбросаны бутылки, окурки, раковина забита грязной посудой. Когда она мыла её, он просыпался, подходил и ругался, что она не даёт ему помогать ей по хозяйству. Она отвечала ему что-то по-матерински нежное, а он, насупившись, уходил в комнату и плюхался на кровать."}, {"kind": "paragraph", "text": "Пенсии старушки стало не хватать на двоих, к тому же кормить вскоре пришлось не только племянника, но и обретённых им друзей, которые чуть не каждую ночь засиживались на кухне до утра, громко споря и распевая песни. Во всей квартире стоял смог — племянник был теплолюбивым и отказывался открывать окно, чтобы проветривать кухню от табачного дыма."}, {"kind": "paragraph", "text": "Приходилось доставать деньги из коробочки, которую она прятала в шифоньере. Делала она это так, чтобы племянник не прознал о тайнике, а он всё дивился богатству тётки и с шутливой издёвкой называл её Буратино."}, {"kind": "paragraph", "text": "Бывало, он отсутствовал несколько дней. Говорил, что уходит искать работу, но возвращался ночью с пустыми карманами, без работы, пьяный и побитый, будил старушку и спрашивал, есть ли чего пожевать. Она самоотверженно поднималась и в полудрёме разогревала суп или второе."}, {"kind": "paragraph", "text": "Общались они мало, не ругались. Она терпеливо сносила его шумность и неблагополучность, сочувствуя его потере. Иногда ей хватало смелости заговорить о том, что ему стоит начать что-то предпринимать, чтобы совсем не захиреть. Но он принимал это в штыки, начинал обороняться, будто на него и впрямь нападали, потом дулся и ещё долго не мог простить тётке бестактность и бесчувственность."}, {"kind": "paragraph", "text": "К маю она стала всё больше тяготиться сожителем и, не в силах на него повлиять, стала проводить на рынке всё время до самого закрытия. Отдушину она находила в своём бойком сопернике, на котором отрывалась. Мясника, в отличие от племянника, старушка не боялась. Племянник же растерял своих свежеобретённых друзей и стал целыми днями просиживать дома, постепенно превращаясь в совершеннейшего пьяницу."}, {"kind": "paragraph", "text": "Любимым его занятием был интернет. Он листал приколы по несколько часов кряду и смеялся им с злобной хмуростью. Старушку он обвинял в том, что она до сих пор не провела в свою халупу интернет с вайфаем. Даже у него в деревне был вайфай! Он не понимал глупого упорства, с каким она отказывалась заниматься подведением провода в квартиру. А она была бы рада исполнить его желание, знай она, как к этому делу подступиться. Подсказок с его стороны не поступало. Он лишь злобно объявлял, что из-за её упрямства ему приходится платить за мобильный интернет гораздо больше, чем им пришлось бы платить за вайфай. Бывало, он срывался и начинал кричать на весь дом, если пропадала сеть…"}, {"kind": "paragraph", "text": "Она стала ценить минуты, когда его не было дома. Она понимала, что в общей картине это к худшему, ведь явится он очень пьяный и агрессивный. Но всё же это стоило времени, которое она могла провести наедине с фаянсовым львом…"}, {"kind": "paragraph", "text": "Однажды в конце июня она вернулась домой поздно вечером и застала племянника истерично плачущим. Оказалось, Люся поселила в их доме любовника. Он рвал на себе седые волосы и бил себя по лицу. Тётка пыталась успокоить его, говорила добрые слова, гладила и обнимала его, пока не увидела разбросанные по полу белые осколки… Это был её лев."}, {"kind": "paragraph", "text": "Когда она заплакала, он обиделся на её слёзы и даже ударил её. Как она могла думать о каком-то льве, когда Люся так подло с ним поступила!"}, {"kind": "paragraph", "text": "Она тщетно пыталась склеить льва. Это было невозможно: фигурка разлетелась на сотни мелких осколков. Старушка держала в руках кусочки его морды и пыталась узнать в них прежние черты. Они были изуродованы, но она, глядевшая на льва в упор многие-многие часы, угадывала почти каждый осколок. Особенно сильно её впечатлил один, на котором остался косящий глаз. Он был размером с ягоду чёрной смородины. С тяжёлым сердцем избавившись от всех прочих, она оставила себе на память этот самый осколок."}, {"kind": "paragraph", "text": "Старушка проплакала всю ночь. Даже когда ей удавалось заснуть, тут же просыпалась на мокрой подушке. Она старалась особенно не всхлипывать, чтобы не разбудить племянника и не вызвать его гнев. Когда рыдания не удавалось сдерживать, она с усилием утыкалась в подушку, и та поглощала стоны. Измученная, она смогла провалиться в глубокий сон только на рассвете."}, {"kind": "paragraph", "text": "В десятом часу её разбудил племянник и представил план действий. Он собирался возвращаться в деревню и взять с собою тётку. Ему пришлось извиниться за вчерашнее и уговаривать её, чтобы она согласилась. Он говорил, что не может видеть, как она живёт в этом нищем гадюшнике, а в деревне ей якобы будет хорошо и привольно. На всякий её протест у него была припасена целая порция аргументов. Она в конце концов напомнила ему, что в его доме теперь живёт другой мужчина. Так стало понятно, зачем она ему в деревне. Старушка должна была исполнить роль клея для брака племянника и его Люси. И она согласилась."}, {"kind": "paragraph", "text": "На следующий же день они ехали в поезде в сторону Ростова. После ждала нелёгкая дорога до Каменска, а оттуда на попутке до деревни."}, {"kind": "paragraph", "text": "Конечно, никто не обрадовался их появлению, но Люся приняла гостей. Племянник явил тётку Люсе с каким-то странным, одному ему понятным смыслом. Словно старушка была их дочкой и он просит жену одуматься ради неё. План не сработал. Он бросил бравировать тёткой, а она стала чувствовать себя совершенно ненужной и чужой. Никто не обращал на неё внимания. И без неё положению хватало щекотливости: под одной крышей жили муж, жена и любовник. Но и гнать старушку никто не торопился. Она сделалась своеобразным элементом фурнитуры, немым призраком, слоняющимся по дому без дела и смысла. Лишь любовник проявлял к ней редкое сочувствие и иногда веселил её разговорами."}, {"kind": "paragraph", "text": "Спустя неделю она объявила, что собирается домой. Тактично: сказала, мол, хватит, нагостилась, в гостях хорошо, да дома лучше. Держать её никто не стал. Племянник не пришёл к ней проститься, зная, что она вечером уезжает."}, {"kind": "paragraph", "text": "До поезда довёз Люсин любовник и даже посадил её."}, {"kind": "paragraph", "text": "Она сутки тащилась по России, всё глядя в окно и замечая, как изменяется мир. То пред ней стояла беспросветная стена густого леса, то вдруг глазу открывались бескрайние просторы сухих южных полей. Весь путь она думала лишь о своём мяснике, готовила остроты и втайне радовалась, что сумасшедший период её жизни подошёл к концу. Сосед по купе умилялся, когда задумавшаяся старушка вдруг ни с того ни с сего начинала улыбаться."}, {"kind": "paragraph", "text": "На следующий же день по приезде она отправилась на рынок, даже не заглянув на базу, чтобы закупиться лимонами или зеленью. Она соскучилась по своему врагу…"}, {"kind": "paragraph", "text": "Невозможно описать пустоту, в которую она провалилась, когда новый мясник сообщил ей, что враг скоропостижно скончался. Подробностей она уже не слышала: в ушах громыхало бешено заколотившееся сердце."}, {"kind": "paragraph", "text": "Вечером того же дня она умерла. В кулаке она сжимала осколок фаянсового льва. На тумбе возле койки лежала короткая записка, сообщающая, что в коробочке под вещами в шифоньере лежат деньги. В записке она обращалась к племяннику с просьбой, чтобы он на эти деньги похоронил её рядом с Федей."}, {"kind": "paragraph", "text": "Последнюю волю старушки он не исполнил, а деньги пропил за полгода."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
5	mrd6-luchshaya-uchenitsa	Лучшая ученица	43	mrd6/mrd6-luchshaya-uchenitsa.jpg	data:image/jpeg;base64,	— У Жени нет будущего в балете. Эмоциональная девочка. Очень артистичная. Но выворотность…	[{"kind": "image", "path": "mrd6/mrd6-luchshaya-uchenitsa.jpg", "caption": "Иллюстрация Лены Солнцевой"}, {"kind": "paragraph", "text": "— У Жени нет будущего в балете. Эмоциональная девочка. Очень артистичная. Но выворотность…"}, {"kind": "paragraph", "text": "— Выворотность можно развить, — Женина мама — сама наивность."}, {"kind": "paragraph", "text": "— Я вас умоляю, за пять лет не развилась, значит, это природное. Женя никогда не сможет стать хорошей балериной. Её не примут в училище. Во-первых, выворотность, во-вторых, лишний вес."}, {"kind": "paragraph", "text": "— Она уже на диете."}, {"kind": "paragraph", "text": "Мне показалось, или у неё слёзы в глазах?"}, {"kind": "paragraph", "text": "Нет, ну вот откуда это стремление: во что бы то ни стало сделать из дочери балерину, даже не понимая, что такое училище-интернат. Да девчонки там друг друга сжирают. Только зря намучается. И по школьным предметам на «красных лебедей» съедет. Потому что там не обучают, а растят рабочих лошадей для сцены."}, {"kind": "paragraph", "text": "— Думаю, Жене не стоит продолжать заниматься. Разве что для себя, — наверное, жестоко, но зато честно, решила я. — До летних каникул четыре месяца. Этот класс она может закончить, но в следующий я её не переведу."}, {"kind": "paragraph", "text": "Женька очень сильная. Всё слышала, посмотрела на меня — ледяной взгляд. А потом на занятии работала лучше всех. Особенно у станка."}, {"kind": "paragraph", "text": "— Батман, батман. Гранд батман, девочки, выше, зафиксировали верхнюю точку. Женя, молодец! Держим спинку, — та же стужа в серых глазах."}, {"kind": "paragraph", "text": "Но плие плохое. Нет выворотности. Я не хотела, чтобы Женя потратила впустую несколько лет. Хотя с таким характером самое место в балете."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "После занятий в студии я учила танцевать стриптизёрш. Ибо зарплаты хореографа не хватит даже на несколько пар американских пуантов. Смешно: русская балетная школа, Большой театр, «Щелкунчик», «Лебединое озеро», но лучшие пуанты делают в Штатах, причём на нескольких фабриках. А у нас много лет только в городе на Неве, в одной единственной мастерской. Помню, как однажды родственница привезла из тогда ещё Ленинграда пятнадцать пар. Розовых, атласных. Мне завидовали все девчонки в интернате. Пуанты были дефицитом, лимит на год — двенадцать-тринадцать пар плюс концертные. А тут сразу пятнадцать! Что мне за них только не предлагали! Я чувствовала себя если не Богом, то Дьяволом. Дьяволом в белоснежной пачке."}, {"kind": "paragraph", "text": "Стриптиз имеет к балету примерно такое же отношение, как шашки к спорту. Если в идеале, нужны внешность, растяжка, гибкость, сильные руки, чувство ритма и огонь в глазах. И всё. Жете, пике, шанжман де пье — да стриптизёрши и не слышали, что это такое. А вот «классная задница», «дай сиськи потрогать», «раздвинь ноги» — каждую ночь. По сути, учу их двигаться для того, чтобы им выкрикивали это как можно чаще."}, {"kind": "paragraph", "text": "— Я категорически против, чтобы ты там работала, — слышу подобное от мужа практически ежедневно, — с этими шлюхами."}, {"kind": "paragraph", "text": "— Они не шлюхи. Хотя, может, и шлюхи. Но честные. У них просят голую задницу — они её демонстрируют. А им за это платят, никакого обмана, — отвечаю."}, {"kind": "paragraph", "text": "— И всё-таки не понимаю, почему ты оставила студию?"}, {"kind": "paragraph", "text": "— Я много раз говорила."}, {"kind": "paragraph", "text": "— Неужели только поэтому?"}, {"kind": "paragraph", "text": "— Не только. Знаешь, я не очень сильный человек. Я намного слабее учениц. Со стриптизёршами это допустимо, с будущими балеринами — нет. Ты даже не представляешь, насколько бывают сильными девочки."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Иерархия всюду. В балетном классе прежде всего."}, {"kind": "paragraph", "text": "— Намочите пол, — требую я. — Поскользнётесь."}, {"kind": "paragraph", "text": "Ни одна не рвётся полить из лейки. Придётся самой выбрать из этих якобы неженок. Помню, как впервые попросила их — пятилетних, смотрящих на меня сияющими глазёнками, — побрызгать пол. Наперегонки кинулись. Прошёл год, два, три… Стоят. Ни одна не желает позаботиться обо всех. И потом, когда я назову имя, чуть окропит середину, зато щедро намочит собственное место у станка. Неужели я тоже так поступала?"}, {"kind": "paragraph", "text": "В балетном классе несколько видов изгоев: солистки и такие, как Женя. Без данных. Остальная добротная, но серая масса ненавидит первых, но раболепствует перед ними, снисходительно относится ко вторым, но периодически их подтравливает. Изящные девочки-облака — предмет повышенного внимания мальчишек-ровесников — живут по закону волчьей стаи: они вместе охотятся, но у каждой своя доля добычи."}, {"kind": "paragraph", "text": "А в стриптизе нет изгоев. Здесь всё по-взрослому. Есть разогрев. Есть самки. Тут все солистки, просто разного качества и с разным заработком. И это совершенно не связано с умением танцевать или величиной бюста, это другое. В клубе Инна одна из лучших. У неё второй размер и неполный шпагат, но мужики пускают слюни уже от одной её походки. И наоборот, Ника: грудь «мечта дембеля» и страсть, пребывающая в вечном анабиозе."}, {"kind": "paragraph", "text": "Тут не надо поливать пол. Зато надо пользоваться дорогим тональным кремом. У танцовщиц от шеста постоянные синяки, приходится маскировать."}, {"kind": "paragraph", "text": "— Нет, ну что за сука опять намазалась дешёвкой?! У меня все руки и ноги чёрные! — подобное можно услышать еженощно. — Мне что, сумки обыскать?!"}, {"kind": "paragraph", "text": "Дешёвый тональный крем окисляется: «шестовичка», крутящаяся после экономной коллеги, оттирается от чёрных пятен весь перерыв."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Партия Кармен. Кто из балерин не мечтает исполнить её? Все. Пусть даже на провинциальной сцене. Помню, как сама когда-то трепетала, примеряя алую пачку с чёрным корсажем. Но я-то уже училась в институте. Конечно, это просто бред: взять вариацию из «Кармен-сюиты» для девяти-десятилетней девочки. И дело не в сложности, а в темпераменте. Очень яркая роль. По силам Жене. Но что за Кармен с такой выворотностью? У Жени потрясающие руки: в них и ветер, и пламя, и сумасшествие, и смерть, и полное откровение. Но выворотность…"}, {"kind": "paragraph", "text": "— Ужасное шассе, — покачала я головой, но Женя продолжила учить движения вслед за Ириной — солисткой, на которую пал мой выбор. — Так, все свободны. Завтра репетируем на сцене. Ирина, Света, Юля Мищенко, Юля Бобылёва, Лариса — к девяти часам. И чтобы были уже разогретые. Остальные к одиннадцати в класс, — я уже начала собираться домой."}, {"kind": "paragraph", "text": "Женя стояла, прислонившись к двери. Какая бледная! Сколько она сейчас весит?"}, {"kind": "paragraph", "text": "— Ты кого-то ждёшь? — спросила я."}, {"kind": "paragraph", "text": "— Вас. Можно я тоже завтра приду к девяти? — И нарочито равнодушно добавила: — Мне всё равно утром нечего делать."}, {"kind": "paragraph", "text": "Я тронула её за руку."}, {"kind": "paragraph", "text": "— Ты вообще что-нибудь ешь? Знаешь, нельзя так резко худеть. К тому же…"}, {"kind": "paragraph", "text": "— Можно я приду завтра к девяти? — повторила она и спрятала руки в карманы куртки."}, {"kind": "paragraph", "text": "— Женя, понимаешь…"}, {"kind": "paragraph", "text": "— Я смогу. Вот увидите, смогу, — уверенно сказала она. — Я выучила все движения. Я постоянно репетирую."}, {"kind": "paragraph", "text": "Мы вышли на улицу. Я обняла Женю за плечи."}, {"kind": "paragraph", "text": "— Кроме балета есть ещё много чего. Не менее замечательного."}, {"kind": "paragraph", "text": "— Я знаю, — кивнула она. — Но можно я приду?"}, {"kind": "paragraph", "text": "— Нет. — К чему давать ненужную надежду? — Ты не справишься. Кармен будет танцевать Ирина."}, {"kind": "paragraph", "text": "— Справлюсь."}, {"kind": "paragraph", "text": "— Мне на остановку. До свидания, — улыбнулась я."}, {"kind": "paragraph", "text": "— До свидания, — уже в спину с металлическими нотками: — Я буду танцевать Кармен! Буду!"}, {"kind": "paragraph", "text": "На следующее утро Женя пришла к девяти и так старательно занималась, что я даже несколько раз подсказала:"}, {"kind": "paragraph", "text": "— Подбородок выше… Чуть порезче… Пальчики раскрой, не зажимайся."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Для стриптизёрш я не указ. Я и не стремлюсь. Просто работаю над их пластикой и пытаюсь придать номерам больше художественности. Клуб дорогой, и контингент, который приходит сюда отдохнуть, одним сниманием нижнего белья не удивишь. Поэтому каждый номер — история и характер. Но это для меня главное. Главное для танцовщиц — яркий костюм и выгодный ракурс."}, {"kind": "paragraph", "text": "— Встань боком и прогнись… В чём дело? — репетирую я с Инной."}, {"kind": "paragraph", "text": "— У меня сбоку грудь плохо смотрится. Маленькая."}, {"kind": "paragraph", "text": "— Она у тебя в принципе небольшая. Но очень красивая, — сколько раз я уже это говорила?"}, {"kind": "paragraph", "text": "— Маленькая. Второй размер."}, {"kind": "paragraph", "text": "— У меня тоже второй. И хватает."}, {"kind": "paragraph", "text": "— Конечно, хватает, если только мужу показывать! А ты выйди на сцену и попробуй не материться, когда какой-нибудь козёл крикнет: «Снимай трусы и вали отсюда, плоскодонка!» Придушила бы!"}, {"kind": "paragraph", "text": "— Что бы тебе посоветовать… Или обращай внимание на каждого и выходи на сцену сразу без трусов, или танцуй так, чтобы у всех мужиков ширинки лопнули. Ну так что? — улыбаюсь я."}, {"kind": "paragraph", "text": "— Как ты там говоришь, боком прогнуться?.."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Если есть какой-нибудь балетный бог, то он сотворил чудо. Женя буквально за месяц выросла на несколько голов. Но самое поразительное — куда только делась плохая выворотность? Из аутсайдеров сразу стала явным лидером. И вообще, теперь на сцене смотрелась эффектней многих девочек: высокая, худая, темноволосая, чернобровая. Однажды после занятий подошла ко мне:"}, {"kind": "paragraph", "text": "— Я собираюсь в августе поступать в училище. Как думаете, у меня есть хоть небольшой шанс?"}, {"kind": "paragraph", "text": "— Женечка, у тебя миллион шансов. Если хочешь, я поеду с тобой. И вообще, будем перезваниваться, — я нарадоваться этой девочкой не могла."}, {"kind": "paragraph", "text": "— Правда, поедете? Конечно, конечно, хочу! — Женька запрыгала и захлопала в ладоши."}, {"kind": "paragraph", "text": "Она была очень внимательной ученицей. Юные балерины вообще-то намного серьёзней обычных сверстниц. И мы — хореографы — относимся к ним, как к взрослым людям. Это бесконечная цепочка, ведь так относились к нам. Хороший хореограф, как и хороший тренер, должен быть всегда немного недосягаем для учеников — я старалась следовать балетному кодексу. Но это детское проявление чувств так тронуло, что я обняла Женю и поцеловала в макушку. А она посмотрела на меня абсолютно счастливыми глазами."}, {"kind": "paragraph", "text": "Партию Кармен я бы Жене не отдала. Ирина вполне с ней справлялась. Я готовила Женю для других постановок: теперь так многое хотелось с ней успеть. Но за неделю до концерта Ирина заболела бронхитом, пришлось срочно шить второй костюм для Жени. Костюм Ирины не подходил: Женя была намного выше. На последних репетициях танцевала превосходно. Я уже знала, что это моя лучшая ученица. Такие бывают лишь раз за всю карьеру, да и то далеко не у каждого хореографа."}, {"kind": "paragraph", "text": "В день концерта пришла Ирина. Сказала: просто посмотреть. Они такие, эти маленькие балерины: будут заниматься самоистязанием, глядя, как другие танцуют их партии. Женька — уже загримированная и в костюме — надевала пуанты, чтобы в последний раз повторить сложные места, Ирина сидела на скамейке рядом с ней, а я занималась с другими девочками. Не знаю, о чём они говорили, только Женя подбежала ко мне и попросила:"}, {"kind": "paragraph", "text": "— Можно мы обе будем солистками? Ира справится. Она же так хотела танцевать Кармен."}, {"kind": "paragraph", "text": "— Как это обе? — удивилась я."}, {"kind": "paragraph", "text": "Подошла Ирина."}, {"kind": "paragraph", "text": "— Я не подведу. Я каждый день занималась, когда температуры не было. Я вам сейчас покажу, — Ирина встала в центр."}, {"kind": "paragraph", "text": "Ни единой помарки. Как будто и не отсутствовала эти две недели."}, {"kind": "paragraph", "text": "— А как же ты? — тихонько спросила я у Жени. — Кармен одна, обеим на сцену нельзя."}, {"kind": "paragraph", "text": "— А меня там и не будет, — сказала девочка и хитро улыбнулась."}, {"kind": "paragraph", "text": "Уверена, на сцене всё было хорошо, судя по аплодисментам. Я не смотрела на Ирину. Я глядела на Женю. За плотным бархатным занавесом, отделяющим нас от полного зала, было только два человека: Женя — страстная Кармен и я — единственный зритель. Она исполнила потрясающе эту свою первую сольную партию. У меня комок в горле стоял, настолько Женя была божественна. И не нужен был яркий свет софитов и декорации, чтобы разглядеть истинный талант. Я и сейчас закрываю глаза и вижу её — юную Кармен, лучшую ученицу."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "— И всё-таки я считаю, тебе лучше вернуться в студию, — в сотый раз бурчит муж, глядя, как я собираюсь к «честным шлюхам»."}, {"kind": "paragraph", "text": "— Я знаю, что ты так считаешь, но я никогда не вернусь, — в сотый раз отвечаю я."}, {"kind": "paragraph", "text": "Не люблю заниматься с Никой. У неё приличная техника, но всё равно для меня она улитка, зачем-то выползшая на сцену. Прохладная улитка в раковине абсолютного равнодушия. И плевать, быстрая звучит музыка или медленная, дрожит ли воздух от возбуждения, или ночь уже устала от страсти и хочет лишь неги и финального аккорда — улитка не оставляет раковину."}, {"kind": "paragraph", "text": "— Как можно танцевать с такими пустыми глазами? — Я пытаюсь скрыть раздражение, но выходит плохо. — Представь, что я богатый клиент. Давай, отбери у меня деньги."}, {"kind": "paragraph", "text": "Улитка вяло ползает сначала по сцене, потом возле меня и предлагает купить по дешёвке бюстгальтер."}, {"kind": "paragraph", "text": "— Себя продавай, себя, — едва не смеюсь. — Пообещай взглядом, что этой ночью нет запретов. Можно всё, абсолютно всё. Ну же!"}, {"kind": "paragraph", "text": "Улитка обещает, что не покинет раковину ни за какие деньги."}, {"kind": "paragraph", "text": "— Знаешь, у меня была ученица, которая в десять лет исполнила Кармен. Я тебе по секрету скажу, не хуже Плисецкой: идеально чисто, с недетским кокетством. В десять лет. А ты голой не можешь станцевать и пяти процентов страсти. Проснись наконец!"}, {"kind": "paragraph", "text": "Я зову другую стриптизёршу."}, {"kind": "paragraph", "text": "Ника не уходит, наблюдает, а потом вдруг выдаёт:"}, {"kind": "paragraph", "text": "— У меня идея. А может, мне тоже стать Кармен? Короткая красная юбочка, корсет…"}, {"kind": "paragraph", "text": "Хохочу. Ника — Кармен. Надо такое придумать!"}, {"kind": "paragraph", "text": "После занятий гуляю по стареющему скверу и вспоминаю Женю. Как она сейчас? Я давно не звонила. Надо набрать. Сегодня же."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Это было очень жаркое лето. Город плавился на сковороде из асфальта и бетона. В июне я отдыхала на море, а в августе собиралась ехать с Женей в училище. В конце июля начинались занятия в балетной студии — мы должны были всё отшлифовать перед поступлением."}, {"kind": "paragraph", "text": "Всё-таки странно устроено человеческое сердце. Не удался у меня в то лето отпуск. Была замечательная погода, всё складывалось как нельзя лучше, а я ходила сама не своя и даже несколько раз расплакалась. Просто так, без причины."}, {"kind": "paragraph", "text": "Отдохнувшие и посвежевшие девочки болтали без умолку. Я показывала аккомпаниатору курортные фотографии. В классе, заглядывая в зеркала, хозяйничало солнце. Такой прекрасный день."}, {"kind": "paragraph", "text": "Женя опоздала. Поздоровалась."}, {"kind": "paragraph", "text": "— Переодевайся и к станку."}, {"kind": "paragraph", "text": "— Можно вас на минуту."}, {"kind": "paragraph", "text": "Я вышла в коридор."}, {"kind": "paragraph", "text": "— Я не буду поступать в училище. Извините. Я пуанты принесла. Новые, с того года остались. Вот, — и протянула пакет."}, {"kind": "paragraph", "text": "— Почему? — от неожиданности я взяла. — Ты поступишь! Если ты думаешь…"}, {"kind": "paragraph", "text": "— У меня родители в аварию попали. С папой всё в порядке, а мама… Я не буду поступать. Я вообще больше не буду заниматься. Врачи говорят, понадобится много времени… Я не буду, — и опустила глаза. — До свидания! — Она быстро направилась к выходу."}, {"kind": "paragraph", "text": "— Женя, стой! А как же твоя мечта? И мама так хотела, чтобы ты стала балериной. Как же так? — Проклятые слёзы, не сейчас, не надо. — Может, осенью вернёшься? А на следующий год будем поступать."}, {"kind": "paragraph", "text": "Женя посмотрела так, будто это мне было десять лет. Улыбнулась."}, {"kind": "paragraph", "text": "— Вы сами бы смогли танцевать, когда такое? А потом время будет потеряно — навсегда."}, {"kind": "paragraph", "text": "— Женечка, мама поправится, я уверена. А ты… Ты ведь очень талантливая. Ты лучшая, — я отказывалась верить, что эта девочка оставит балет, цеплялась за любой шанс. — Знаешь, можно окончить школу и поступить в институт культуры, будешь хореографом, как я. Можно после школы…"}, {"kind": "paragraph", "text": "— Кроме балета есть ещё много чего. Помните, вы сами говорили? — Грустно улыбнулась и ушла, не оборачиваясь."}, {"kind": "paragraph", "text": "Женина мама полностью восстановилась, но врачи были правы: понадобилось много времени. Ещё несколько лет я преподавала в студии. Некоторые девочки поступили в училище и стали балеринами. Это были очень способные ученицы. Новый набор я делать не стала. Зачем? Зеркала в этом классе никогда уже не отразят девочку, способную в десять лет исполнить партию Кармен, как Женя. Такая ученица бывает лишь единожды. И это счастье, что она у меня была. Лучшая ученица. Настоящая балерина."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1379	911	10
6	mrd6-obeschanie	Обещание	44	mrd6/mrd6-obeschanie.png	data:image/jpeg;base64,	Утро 1 апреля 1837 года, как и полагается хорошей шутке, выдалось на удивление тёплым, несмотря на мрачные тучи и событие, которое должно было состояться с часу на час в районе Тукуланы. Для человека, что не интересуется	[{"kind": "image", "path": "mrd6/mrd6-obeschanie.png", "caption": "Иллюстрация Маргариты Царевой при помощи Midjourney"}, {"kind": "paragraph", "text": "Утро 1 апреля 1837 года, как и полагается хорошей шутке, выдалось на удивление тёплым, несмотря на мрачные тучи и событие, которое должно было состояться с часу на час в районе Тукуланы. Для человека, что не интересуется путешествиями и всячески лишён энтузиазма заниматься географическими изысканиями, стоит отметить, что эта территория принадлежит ныне Якутии с ближайшим населённым пунктом Саамыс-Кумага (село Булгунняхтах). Сам же район, как и следует из названия (с якутского «Тукуланы» означает «место, занесённое песком»), уже давно напоминает верблюжий горб, где постоянные ветра и мерзлота сдвигают песчаные параболы в сторону тайги, лишая реку Лену некогда высокого загромождения. Ещё место славится пирамидальными камнями-ветрогранниками или дрейкантерами, а также фульгуритами — это такой спёкшийся песок, формирующийся ударом молнии."}, {"kind": "paragraph", "text": "На границе с лесом, где расположились тонкие берёзы, топорные сосны и дикие кустарники, можно встретить разных птиц, запасливых белок, неспешных зайцев и медведей, порою выбредающих на песчаное поле неизвестно зачем. Но сегодня в обычно дикой и заброшенной Тукулане собралось уж слишком много приезжих служащих на пару с военными и местных жителей, которых мёдом не корми, а покажи очередное представление, где несгибаемое правосудие вновь восторжествует под натиском флотской удавки, именуемой эшафотским узлом."}, {"kind": "paragraph", "text": "Среди традиционных одежд, таких как оноолоох, бууктаах и кытыылаах сон, явно выделялись доломаны, поверх которых были надеты серые ментики, обложенные мехом, с пуговицами в несколько рядов, со шнурками и петлями. Так можно было сразу определить хоть и казённый, но всё же праздничный мундир. Без сучка и задоринки, сливаясь со своими костюмами, проглядывались сосредоточенные лица военных, справляющихся о состоянии установленного эшафота на предмет неполадок. Муравьиная стая выполняла свои обязанности молча, образуя обобщённое пятно на фоне своего командира и его первого помощника в это воскресное утро."}, {"kind": "paragraph", "text": "Старший палач Игорь Матвеевич Правонравов, ввиду отсутствия нужды следить за выполнением приказов, с нескрываемой печалью наблюдал за зыбью воды, стараясь как можно реже отвечать взволнованному помощнику."}, {"kind": "paragraph", "text": "— Игорь Матвеевич, ну ведь это полнейшее безумие! — причитал молодой Пётр, как можно заметнее жестикулируя перед лицом старшего чина, нервно озираясь на собравшуюся толпу людей. — Ведь и дураку понятно: голубчика мы больше не увидим, если только где-нибудь на другом конце земного шара, ей-богу!"}, {"kind": "paragraph", "text": "Палач, казалось, только пуще погружался в свой внутренний монолог, делая вид, что никого не слышит. Помощник же и не думал отступать, чувствуя личную ответственность за возможный срыв мероприятия и сурового выговора со стороны судейского аппарата. Можно даже предположить, что молодой человек боялся, как бы самому не оказаться в списке виновных, которым суждено забраться по деревянным ступеням без возможности после спуститься на своих двоих."}, {"kind": "paragraph", "text": "— Лучше бы вы давеча оповестили о своих планах — тогда бы я хоть дома удавился, в кругу близких. Так нет, вам же хочется, чтобы головы наши слетели в глуши под хмурым небом, ей-богу! Это ведь ещё матушке и жене придётся тратиться на билет, дабы лицезреть постыдную расправу над эдаким дураком, как я. А ведь какие надежды были когда-нибудь стать вами, человеком высших нравов, которого детям ставили в пример!"}, {"kind": "paragraph", "text": "— А уже не ставят?"}, {"kind": "paragraph", "text": "— Ещё ставят, но, поверьте, как только по вашей выходке приговорённый не приедет даже не то чтобы ко времени, а просто исчезнет, нас тут же снимут с должностей, отправив на плаху."}, {"kind": "paragraph", "text": "Главный помощник многозначительно замер, надеясь хотя бы сейчас вразумить своего начальника, но тот только весело ухмыльнулся, вернувшись к своим прежним делам, если их так вообще можно было назвать."}, {"kind": "paragraph", "text": "В то же время, обильно загребая песок штиблетами, в сторону командира бежали двое пронырливых людей, взявшихся буквально из ниоткуда, а может, и вынырнувших из-за спин плетущихся вдали зевак."}, {"kind": "paragraph", "text": "На одном из спотыкающихся гостей был уже видавший виды суконный плащ, зато брюки, выбиваясь из-под подола только лишь краями, представляли идеальный образец недавно купленного и превосходно подшитого одеяния. Спутник сего господина представлял куда более жалкое зрелище, чьи обноски и вовсе стыдно описывать. Достаточно заметить, что в руках у этого человека наблюдались планшет и несколько замечательно заточенных карандашей, которые явно свидетельствовали о причастности хозяина к тонким искусствам."}, {"kind": "paragraph", "text": "Завидев периферийным зрением диковатую пару, Игорь Матвеевич учтиво отвлёкся от своих мыслей, ожидая диалога с узнанными лицами. Помощнику Петру оставалось только молча наблюдать за сценой, которая развернулась в следующие минуты."}, {"kind": "paragraph", "text": "Подбежав вплотную к командиру, жуликоватый мужчина в суконном плаще молча пожал тому руку, начав показательно глотать воздух ртом, дабы подчеркнуть усилие, которое было совершено для данной встречи. Спустя некоторое количество секунд пришедший заговорил:"}, {"kind": "paragraph", "text": "— Ужасно извиняюсь, Игорь Матвеевич. С поездом, который должен был доставить нас вовремя для освещения такого грандиозного события и для которого мы удостоились чести быть выбранными вами, случилась пренеприятнейшая история…"}, {"kind": "paragraph", "text": "Не дав товарищу закончить, молодой человек безразлично встрял в разговор, сказав то, от чего у провинившегося встали бы волосы дыбом, если могли:"}, {"kind": "paragraph", "text": "— Да, барин проспал! Всю ночь до отъезда кутили в доме блудилища."}, {"kind": "paragraph", "text": "— Что ты несёшь, окаянный?! — неистово огрызнулся представитель прессы на штатного художника."}, {"kind": "paragraph", "text": "Командир, не дожидаясь развития перебранки, обратился к журналисту напрямую:"}, {"kind": "paragraph", "text": "— Евгений Александрович, ваш товарищ изложил правду или смеет насмехаться над ситуацией, пытаясь перевести в шутку серьёзность сложившихся обстоятельств?"}, {"kind": "paragraph", "text": "Евгений А. Лукьянов, кардинально сменившись в лице после обращения многоуважаемого командира, буквально сжался до клеща, сознательно пропищав:"}, {"kind": "paragraph", "text": "— Было дело, виновен! Но можно ли винить мужчину в том, что он оказался околдован потребной девкой?"}, {"kind": "paragraph", "text": "— С таким давеча лихим пузырём, барин, вас бы не спасла и непотребная девка, да хоть сама большуха пришлась бы бесполезной."}, {"kind": "paragraph", "text": "— Да заткн... — гаркнул было на журналиста человек, пойманный на очередной лжи, но Игорь Матвеевич снова вмешался, показав рукой знак «стоп»."}, {"kind": "paragraph", "text": "— А вы, голубчик, — обратился командир к художнику, — откуда знаете такие пикантные подробности про товарища? Неужто свечку держали?"}, {"kind": "paragraph", "text": "— Ну не свечку, но верный десница барина забавлялся по свою отведённую руку с не менее распутной шельмой, учитывая обстоятельства, при которых выяснилось, что денег она своих не стоит, особенно под оговорённым выше дурманом. Зато, прошу заметить, выгляжу я куда сподручнее Евгения Александровича, а причиной тому всё та же лихая, которая решила меня не отпускать. Поэтому в каком-то смысле у барина имеется хоть какая-никакая, а совесть. Извольте уточнить, можно ли начать выполнять свои прямые обязанности?"}, {"kind": "paragraph", "text": "И, не дожидаясь ответа, Алёша откинул защитный лист с альбома, начав воодушевлённо зарисовывать невозмутимую физиономию Игоря Матвеевича."}, {"kind": "paragraph", "text": "Лукьянов было замахнулся на товарища, но вовремя успел сменить траекторию движения, ловко выкорчевав из рукава, словно фокусник, заготовленный блокнот. Его фальшивая улыбочка сосредоточилась на командире."}, {"kind": "paragraph", "text": "— И право, Игорь Матвеевич, к чему же нам тратить ваше драгоценное время? Позвольте приступить к своим прямым обязанностям. Хочу задать вам несколько вопросов, ответы на которые, я просто уверен, будут ну очень, очень интересны нашим читателям!"}, {"kind": "paragraph", "text": "— Валяйте, — безразлично отозвался Правонравов, уставившись на полюбившуюся водную зыбь."}, {"kind": "paragraph", "text": "— Итак, Игорь Матвеевич, начнём с одного из главных вопросов: почему вы избрали столь отдалённое от столицы место для свершения правосудия? Всё-таки почти четыре тысячи вёрст — не шутки."}, {"kind": "paragraph", "text": "— Видите ли, подобный выбор места был связан с личными этическими соображениями, где казнь даже в отдалённой черте нашей благоустроенной столицы виделась мне уж в больно вульгарных тонах. А здесь… душа, если таковая имеется у приговорённого, как бы получает шанс вернуться к отцам, пройдя долгий путь по не столь благоустроенным землям. И эта деталь, которая вам может показаться смешной, позволяла мне до сих пор оставаться на своём посту в здравии без чувства вечного вопроса: а не грешным ли дельцем я промышляю?"}, {"kind": "paragraph", "text": "Рука журналиста виртуозно прыгала по листку, судя по всему, дословно записывая сказанное респондентом."}, {"kind": "paragraph", "text": "— Но как вы тогда объясните своё желание осветить, казалось бы, рядовой случай в ходовом журнале, отпустив осуждённого сначала на волю, а затем заявив, что он самолично приедет на собственную казнь?"}, {"kind": "paragraph", "text": "— Просто одна из форм гордыни, голубчик, не более. Захотелось уйти на заслуженный отдых красиво, дабы все помнили, кто был такой Игорь Матвеевич! — чрезмерно помпезно выкрикнул командир."}, {"kind": "paragraph", "text": "В разговор встрял Алёша:"}, {"kind": "paragraph", "text": "— Премного прошу прощения, но, Игорь Матвеевич, могли бы вы ещё вот так же величаво вскинуть свой пальчик в небо и насупить брови? Буквально на пять минуток, не более."}, {"kind": "paragraph", "text": "— Просьба отклоняется."}, {"kind": "paragraph", "text": "— Понял… Ничего страшного, нарисуем-с по памяти."}, {"kind": "paragraph", "text": "Лукьянов продолжил интервью:"}, {"kind": "paragraph", "text": "— Позвольте уточнить сразу две нескромные детали дела — так сказать, справиться о сути."}, {"kind": "paragraph", "text": "— Позволяю."}, {"kind": "paragraph", "text": "— Уточните для наших читателей, за какое такое дельце гражданин… э-э-э…"}, {"kind": "paragraph", "text": "— Голицын Лев Николаевич, — удружил помощник командира."}, {"kind": "paragraph", "text": "— Сердечно благодарю. За какое такое дельце гражданин Лев Николаевич Голицын получил высшую меру наказания и, собственно, к какому времени он должен явиться?"}, {"kind": "paragraph", "text": "— Умышленное убийство собственной жены. А явиться голубчик должен… — Игорь Матвеевич ловко вынул карманные часы, сверившись с набежавшими стрелками. — Ровно через четверть часа."}, {"kind": "paragraph", "text": "Помощник Пётр снова застонал. Интервьюер подметил обеспокоенность, которая, надо признаться, была очень даже обоснованной."}, {"kind": "paragraph", "text": "Евгений продолжил допытываться:"}, {"kind": "paragraph", "text": "— Позвольте разрешить ещё один уточняющий вопросец…"}, {"kind": "paragraph", "text": "— Откуда во мне такая уверенность?"}, {"kind": "paragraph", "text": "— Поражаюсь вашей проницательности!"}, {"kind": "paragraph", "text": "— Скажем так: это секрет, который касается исключительно меня и гражданина Голицына. Но будьте уверены: Лев Николаевич прибудет без опозданий."}, {"kind": "paragraph", "text": "— Какие же споры вы породите среди людей, уважаемый командир, если ваше пророчество сбудется!"}, {"kind": "paragraph", "text": "Игорю Матвеевичу совсем разонравился разговор с таким недотёпой, который ещё смел при знакомстве обозвать себя лучшим в своём деле. Но зачем гадать, как Лукьянов получил столь высокую должность? Ведь можно простить убогому оплошности, дабы не терзать свои нервы понапрасну, и просто переключить разговор в иное русло."}, {"kind": "paragraph", "text": "— Евгений Александрович, извольте показать вам и немного рассказать про сам процесс, пока мы дожидаемся нашего званого гостя. — Командир жестом руки предложил журналисту проследовать к уже готовому эшафоту."}, {"kind": "paragraph", "text": "— Буду крайне вам признателен! Алексей, вы портретик закончили-с?"}, {"kind": "paragraph", "text": "— Да, барин, получился у нас тут вылитый Наполеон на своём верном Маренго."}, {"kind": "paragraph", "text": "— Будем надеяться, — вступился помощник за командира, — что вы изволите шутить, иначе у вашего работодателя будут большие проблемы. А вы, как самое что ни на есть виновное лицо в сей грязной карикатуре, о которой я смею лишь догадываться, получите равное преступлению наказание."}, {"kind": "paragraph", "text": "Пётр вытянул шею, пытаясь разглядеть зарисовку, но Алёша ловко сменил испачканный своими трудами лист оттенка слоновой кости на новый, как бы показывая оппоненту кукиш."}, {"kind": "paragraph", "text": "Четыре фигуры бодрым шагом двинулись к эшафоту, который с каждым пройденным метром терял облик привычного фона и становился всё более грозной конструкцией, внушающей волнение и даже в какой-то степени страх."}, {"kind": "paragraph", "text": "Перед журналистом и Алёшей, который сразу же начал делать набросок сей конструкции, предстал классический эшафот из наскоро сколоченной древесины, чья платформа, на удивление, уже имела следы многолетней эксплуатации. Причём Евгений признал в установке именно тот самый эшафот, который ранее видел в столице на другой показательной казни."}, {"kind": "paragraph", "text": "Командир, искоса наблюдавший за сменой выражения лица и ждавший именно такой реакции, довольно кивнул журналисту, снова опередив его вопрос:"}, {"kind": "paragraph", "text": "— Вы совершенно правы. Ещё один секрет нашей нелёгкой работы раскрыт. Свою гордость мы возим везде, где планируется провести публичную казнь."}, {"kind": "paragraph", "text": "— Но не казнокрадское ли это предприятие? Не сподручнее было бы воспользоваться местными ресурсами?"}, {"kind": "paragraph", "text": "— И да, и нет, — серьёзно ответил Игорь Матвеевич. — Видите ли, мы обязаны следовать уставу и прописанным правилам проведения. В данные списки также входят и пункты, посвящённые оборудованию, которое должно перед использованием пройти регистрацию, лицензирование и техническое обслуживание с печатью главного представителя по надзору качества и безопасности…"}, {"kind": "paragraph", "text": "— Безопасности? — Алёша, постоянно будучи подшофе, брызнул весёлой слюной."}, {"kind": "paragraph", "text": "Игорь Матвеевич в очередной раз проигнорировал дерзость художника. Он лишь смотрел на смеющегося в полном молчании и продолжил говорить сразу, как тот кончил своё одинокое блеяние:"}, {"kind": "paragraph", "text": "— Самая пикантная часть агрегата заключается в люковом механизме, который должен раскрыться не слишком резко, но и не слишком медленно, дабы заключённый получил ровно то наказание, которое прописано в его документе."}, {"kind": "paragraph", "text": "Командир жестом пригласил подняться, чтобы газетчики рассмотрели нехитрый механизм поближе."}, {"kind": "paragraph", "text": "Дрожащей ногой Евгений опробовал люк на предмет надёжности."}, {"kind": "paragraph", "text": "— Получается, приговорённый просто встаёт в серёдку, на шею накидывается петля, а затем люк открывается и того? — Мужчина состроил карикатурную рожицу покойника с высунутым набок языком."}, {"kind": "paragraph", "text": "— Что вы, если бы было всё так просто! Приговорённый должен встать ногой на одну створку, а другой — на вторую, да так, чтобы его вес был правильно распределён. Иначе открытие люка может сработать неверно, а это приведёт к известным печальным последствиям."}, {"kind": "paragraph", "text": "— Разве само повешение не есть печальное последствие? — снова встрял Алёша."}, {"kind": "paragraph", "text": "— Правильно проведённая процедура казни является лишь исполнением приговора, не более. И раз уж вы об этом заговорили, то сразу обмолвлюсь, что в случае, если в процессе происходят огрехи, исполнителей вполне справедливо отчитывают и штрафуют."}, {"kind": "paragraph", "text": "— Последний вопросец. — Евгений как-то лениво шмыгнул носом, в придачу глупо чавкнул языком. — А что случится, если люк откроется слишком быстро или слишком медленно?"}, {"kind": "paragraph", "text": "— В первом случае осуждённому сломает шею, отчего он умрёт не от повешения. Во втором же сонные артерии надорвутся недостаточно, дабы осуждённый умер именно от гуманной асфиксии. Последуют страшные мучения, которые могут продолжаться до получаса, а это — нарушение прав человека."}, {"kind": "paragraph", "text": "В воздухе повисло неопределённое молчание. Даже Алёша как-то сник, только покачал головой, словно соглашался с услышанным. Наравне с молчанием ведомый лишь инстинктами командир устремил свой взгляд на восток, где на горизонте одного из песчаных горбов одиноко шагал человек в чёрном костюме, не похожий ни на заплутавшего служащего, ни на местных зевак. Такая исключительная разница говорила даже самым невовлечённым зрителям, что навстречу своей запланированной смерти идёт Голицын Лев Николаевич, осуждённый за умышленное убийство своей жены."}, {"kind": "paragraph", "text": "Лев Николаевич предстал перед присутствующими хоть и крепко сложенным, но всё же стариком выше среднего роста, с короткими и напрочь седыми волосами. Нижнюю же часть лица обрамляла неухоженная борода, от которой по щекам расползлись не менее удручающие морщины, словно они были вырванными корнями деревьев. Если бы не чёрный костюм, можно было смело сказать, что осуждённый всю жизнь проработал рыбаком на югах и что ему нужно было надевать не строгий костюм, а забродные сапоги с лохмотьями, — всё равно помирать. Фигура Голицына стремительно увеличивалась в размерах, с каждым аршином привлекая всё больше народу."}, {"kind": "paragraph", "text": "Нескончаемо довольный Игорь Матвеевич неспешно спустился с эшафота, направившись навстречу женоубийце. Лев Николаевич смотрел на своего палача и его компанию с чистой совестью, не выказывая никаких лишних эмоций. Если бы не знание сложившихся обстоятельств, можно было даже предположить, что обвиняемый никакой не обвиняемый вовсе, а самый настоящий товарищ, появившийся здесь не по поручению, а просто так, справиться о делах да здоровье."}, {"kind": "paragraph", "text": "Рядовые солдаты с изумлением уставились на гостя, побросав выполнять возложенные на них мелкие поручения. Парочка особо ответственных хотела было броситься к мужчине, дабы взять его под уставной конвой, но Правонравов жестом остановил подчинённых. Алёша уже вовсю зарисовывал гостя. Сам же горе-журналист от обуявшего волнения попросту проглотил язык, наблюдая вместе с остальными чудесное появление человека, которого никто в действительности не ожидал увидеть воочию."}, {"kind": "paragraph", "text": "Осуждённый остановился перед своим палачом на расстоянии вытянутой руки, еле заметно кивнув вместо приветствия."}, {"kind": "paragraph", "text": "— Позвольте узнать причину, по которой вы умертвили свою благоверную! — слишком уж резко выкрикнул журналист, но, опомнившись, добавил: — Будьте добры…"}, {"kind": "paragraph", "text": "— Не вашего ума будет."}, {"kind": "paragraph", "text": "— Тогда почему не сбежали?! Извольте спросить…"}, {"kind": "paragraph", "text": "— Обещал."}, {"kind": "paragraph", "text": "Тут уже не выдержал Правонравов, загоготав на извиняющийся манер, как бы показывая пример устойчивого сочетания «и смех и грех»."}, {"kind": "paragraph", "text": "— Прошу всех присутствующих извинить меня, в том числе уважаемого Льва Николаевича. Просто… Не объяснить мне такого проступка, но… — Командир ещё раз козырнул на заключённого, который и сам расплылся в улыбке."}, {"kind": "paragraph", "text": "Журналист на пару с Алёшей и помощником командира недоумённо тупил взгляд, не понимая, что же произошло такого заразительного. Он решил пойти на отчаянные меры, проявив настойчивость в адрес Голицына."}, {"kind": "paragraph", "text": "— Прошу, ответьте на заданные мною вопросы, ведь читатели хотят знать, да и не забывайте своё положение, которое обязывает вас к подчинению высшим инстанциям. Игорь Матвеевич, скажите…"}, {"kind": "paragraph", "text": "— Будет с вас и того, что имеете, — только и ответил командир."}, {"kind": "paragraph", "text": "— Пора бы и кончать, — подытожил приговорённый."}, {"kind": "paragraph", "text": "Без чьего-либо сопровождения покорный судьбе старик неспешно забрался по казённым ступеням эшафота, где самостоятельно под призрачное эхо изумлённой публики просунул голову в петлю, после чего проверил надёжность плавающего узла. К моменту, когда женоубийца правильно расставил ноги на люке, к нему подошёл командир, который только пожал крепкую руку рыбака."}, {"kind": "paragraph", "text": "Журналист, совсем потерявший голову от абсурдности происходящего, надеялся, что хотя бы прозвучит обвинительная речь, после которой заключённому дадут право слова. И вот тогда, если уму с хорошей фантазией набраться смелости, то он может предположить, что приговорённый голубчик и сойдёт до простого люда, кем он и являлся до приговора. Тогда-то на его испуганном лице покажется маленький ребёнок, не желающий умирать и которому есть что сказать. Разверзнется ли правда из уст убийцы перед небытием?"}, {"kind": "paragraph", "text": "Но и тут Евгений вместе с зеваками в очередной раз пришли в серьёзнейшее замешательство, когда палач молча спустил рукоять механизма."}, {"kind": "paragraph", "text": "Люк под Голицыным открылся не слишком быстро и не слишком медленно. Тело приговорённого пропало из видимой части ровно наполовину, акцентируя теперь картину не на фигуре, что стояла на эшафоте, а на портрете, который даже в секунды смерти оставался безмолвным, хоть неконтролируемая мимика и выражала страдания от нехватки кислорода. Через двадцать секунд конвульсии тела начали менять свой поспешный ритм, который окончательно сошёл на нет к завершению минуты. Ещё через пятнадцать секунд приглашённый врач подтвердил смерть Льва Николаевича Голицына, обвиняемого в убийстве жены, с которой он прожил почти тридцать лет."}, {"kind": "paragraph", "text": "Осмелевший Евгений Александрович подскочил к спускающемуся командиру:"}, {"kind": "paragraph", "text": "— Как вы изволите объясниться о произошедшем?"}, {"kind": "paragraph", "text": "— Перед вами?"}, {"kind": "paragraph", "text": "— Не только передо мной, но хотя бы перед читателями журнала или вот этими людьми! — Журналист махнул в сторону расползающейся толпы якутов. — Что я, по-вашему, должен написать в статье?"}, {"kind": "paragraph", "text": "— Пишите ровно то, что увидели, голубчик."}, {"kind": "paragraph", "text": "На этом, не прощаясь, Игорь Матвеевич поманил своего помощника, после чего две фигуры начали быстро удаляться, срастаясь с дымкой позднего утра."}, {"kind": "paragraph", "text": "Солдаты спохватились снимать тело казнённого. Более внушительная группа принялась разбирать эшафот, складируя каждую дощечку по длине, после обматывая стороны толстой бечёвкой для сподручной транспортировки. Только Евгений с Алёшей стояли как вкопанные, не понимая, чего же тут такого произошло."}, {"kind": "paragraph", "text": "В попытке собрать хоть какой-то материал горе-журналист кинулся к зазевавшейся местной даме, дабы прояснить пусть крошечные, но детали."}, {"kind": "paragraph", "text": "— Премного извиняюсь. Ей-богу, не смел бы тревожить вас, коль не было моё положение столь плачевным. Видите ли, я припоздал на событие, о котором следовало бы написать очень важную статью в большой журналец, и... В общем, не смог я с должным подходом организовать свой труд — ну вы поймите, такое стряслось! Беда с поездом, сами понимаете, машины могут ломаться, не то что мы, журналисты… — Тут Евгений самым нелепейшим образом посмеялся, а после продолжил оправдываться в надежде, что кивающая дама снизойдёт до положения и поможет закрыть многие пробелы…"}, {"kind": "paragraph", "text": "После того, как он закончил, женщина спросила:"}, {"kind": "paragraph", "text": "— Туох диэтиҥ?"}, {"kind": "paragraph", "text": "А когда вместо ответа она увидела краснеющего от злобы приезжего, то тут же поспешно ретировалась в сторону удаляющихся соплеменников."}, {"kind": "paragraph", "text": "Евгений от всей души кинул наземь блокнот, начав втаптывать его в непослушный песок. Алёша же залился самым искренним смехом, иногда повторяя: «Туох диэтиҥ?»"}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Восемь дней спустя в московском ресторане «Яр», расположившемся по адресу: переулок Столешников, 66 в атмосфере табачного смога, звенящих посудин и непрерывного гама, праздновался уход на пенсию Игоря Матвеевича Правонравова."}, {"kind": "paragraph", "text": "Ввиду того, что официальная часть в воинском корпусе была закончена давеча утром, приглашённые успели нехило так заправиться, потеряв какую-либо нужду в собственной совести. Приятный казус застиг и самого виновника торжества, которого можно было разглядеть в южной части зала в компании верного помощника Петра и нескольких близких по чину товарищей."}, {"kind": "paragraph", "text": "Неподалёку от указанного стола тёрлось ещё одно знакомое лицо, на котором, правда, теперь имелась непривычно отросшая щетина, какая бывает у запойных людей, забывающих следить за своим внешним видом. Евгений Александрович, уже достаточно поддатый, стоял чуть ли не в экстремально диагональном положении, опёршись на несущую колонну, и пристально наблюдал за Правонравовым, стараясь уловить каждое сказанное им слово."}, {"kind": "paragraph", "text": "Разумеется, Игорь Матвеевич знал о незваном госте, ведь он, будучи человеком всё ещё порядочным, отдал распоряжение пустить бывшего журналиста на закрытое застолье."}, {"kind": "paragraph", "text": "Пётр искоса поглядывал на бледного гостя, чувствуя себя в его присутствии железом на сковороде. Не отводя взгляда от тунеядца, молодой человек обратился к бывшему командиру:"}, {"kind": "paragraph", "text": "— Игорь Матвеевич, честное слово, этот убогий так и будет пилить наш столик взглядом? Мне мясо в горло не лезет."}, {"kind": "paragraph", "text": "— А вы, Пётр, более тщательно поработайте ножичком — маленькие кусочки должны решить ваше несчастье, — весело ответил командир в отставке."}, {"kind": "paragraph", "text": "— Я серьёзно, сжальтесь! Пусть безобразный исчезнет!"}, {"kind": "paragraph", "text": "— Я так понимаю, покоя вы мне не дадите на собственных проводах?"}, {"kind": "paragraph", "text": "— При всём уважении, так и буду ныть!"}, {"kind": "paragraph", "text": "Игорь Матвеевич оставил в покое окорок, запил крепким, дабы освежить дух, и, поймав взгляд Евгения Александровича, подозвал к себе."}, {"kind": "paragraph", "text": "Лукьянов, пошатываясь, подошёл к столу, но не посмел сесть на свободный стул."}, {"kind": "paragraph", "text": "— Здравствуйте, Игорь Матвеевич, чем обязан такому вниманию?"}, {"kind": "paragraph", "text": "Добронравов радушно козырнул на своего помощника, затем снова сосредоточив рассредоточенный взгляд на собеседнике."}, {"kind": "paragraph", "text": "— Да вот вы тут, к несчастью, пугаете моего товарища своим безумным взглядом, голубчик. Я вас пропустил сюда не для устрашения, а чтобы вы хорошенько отдохнули."}, {"kind": "paragraph", "text": "Евгений Александрович смерил Петра ненавистным взглядом, решив никак не комментировать сложившуюся ситуацию. Да и коль уж маски сорваны, был ли смысл поддерживать вежливый тон? Бывший журналист только спросил:"}, {"kind": "paragraph", "text": "— Как вам статья, уважаемые-с? А иллюстрация?"}, {"kind": "paragraph", "text": "— Мне очень жаль, Евгений, — как ни в чём не бывало ответил Добронравов, — что вас и Алексея отстранили от работы после столь… как бы это сказать, вопиющего случая. Мне, право, очень жаль. Готов вас заверить: я к этому никак не причастен."}, {"kind": "paragraph", "text": "— Вы, уважаемый Игорь Матвеевич, — смутьян неожиданно закричал как проклятый, так что в одночасье в ресторане сделалась тишина, — ещё как причастны! Уж поверьте мне, ещё как! И ладно, тогда промолчали, не раскрыв секрета, как же вам удалось этого поганого старика заставить прийти на собственную казнь в назидание за мой промах. И даже ладно, что после такого материала работодатели отправили меня на улицу, так вы и после не ответили! Чего же теперь? Урок усвоен, премного вам благодарен. А теперь, Игорь Матвеевич, откройте секрет. Хотя бы сейчас! Ведь я место себе потерял, сна не нахожу, мучаюсь по такому пустяку, как дитя малое. Ну ей-богу, не томите!"}, {"kind": "paragraph", "text": "Тут подбежали двое коренастых официантов, которые без лишних слов взяли в тиски крикуна, поволочив его на выход, как последнего забулдыгу, не смогшего уплатить по счёту."}, {"kind": "paragraph", "text": "Игорь Матвеевич крикнул вслед утаскиваемому гостю, который только рычал и сквозь зубы повторял обидчикам: «Отпустите, не имеете права!»"}, {"kind": "paragraph", "text": "— Простите, Евгений Александрович, но вам, право, нельзя доверить и такую малость, как культурный разговор. Прощайте, голубчик!"}, {"kind": "paragraph", "text": "Как только журналист пропал из поля зрения, гости вышли из ступора, возобновив весёлую шумиху. Виновник же торжества занял руки газетой, в который раз живо окинув взглядом статью горе-журналиста."}, {"kind": "paragraph", "text": "Тут встрял Пётр:"}, {"kind": "paragraph", "text": "— Игорь Матвеевич, а действительно, вы ведь и мне так не рассказали о фокусе…"}, {"kind": "paragraph", "text": "— О фокусе?"}, {"kind": "paragraph", "text": "— Как вам удалось рыбака уговорить прийти на собственную казнь?"}, {"kind": "paragraph", "text": "— Ты правда хочешь знать, Пётр?"}, {"kind": "paragraph", "text": "— Извольте, коль теперь я командир, посвятить в тайну."}, {"kind": "paragraph", "text": "— Тебя ещё официально не назначили."}, {"kind": "paragraph", "text": "— Вопрос времени."}, {"kind": "paragraph", "text": "Добронравов усмехнулся."}, {"kind": "paragraph", "text": "— Говорить ты начал уже как командир."}, {"kind": "paragraph", "text": "— Ну так что?"}, {"kind": "paragraph", "text": "Игорь Матвеевич театрально оглянулся по сторонам, затем пальцем поманил друга поближе к себе и только на ухо посвятил молодого человека в тайну, которую больше никто не знал и никогда не узнает:"}, {"kind": "paragraph", "text": "— Рыбак этот, Петя, очень любил свою жену. И когда она смертельно заболела, он выполнил последнюю просьбу умирающей, избавив бедняжку от дьявольских мучений. Понимаешь? Ведь он сам сдаваться пришёл, только попросил немного времени с дочкой повидаться."}, {"kind": "paragraph", "text": "— И вы согласились?"}, {"kind": "paragraph", "text": "— А ты бы не согласился?"}, {"kind": "paragraph", "text": "— К чему же тогда представление?"}, {"kind": "paragraph", "text": "— Коль умирать, Петя, так с музыкой, как и уходить на покой, — с грустной улыбкой подытожил Игорь Матвеевич, с чувством шлёпнув газетой по столу."}, {"kind": "paragraph", "text": "Над скудным текстом, за который и был с позором уволен Лукьянов, красовалась карикатура Алёши, где командир оказался изображённым на манер Наполеона, что восседал на своём гарцующем Петре."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
10	mrd6-ispytanie	Испытание	48	mrd6/mrd6-ispytanie.png	data:image/jpeg;base64,	***	[{"kind": "image", "path": "mrd6/mrd6-ispytanie.png", "caption": "Иллюстрация Екатерины Ковалевской"}, {"kind": "paragraph", "text": "***"}, {"kind": "paragraph", "text": "Эта история случилась в первой четверти XVI века в Вероне. Из-за поздних ночных размышлений, ставших привычными в последние годы, дьякон церкви Святого Зенона долго не мог уснуть. Дьякон Морриконе, так его звали, был уже стар; мысли о смерти стали для него обыденными и не пугали, как в молодости, а сделались чем-то вроде заботы о завтрашнем дне. Можно сказать, что он думал о ней как о предстоящем визите в деревушку Меццане-ди-Сотто за вином или о помощи пресвитеру на завтрашней службе."}, {"kind": "paragraph", "text": "Дьякон очень заботился о своём благополучии как на земле, так и на небе, поэтому ход его мыслей в ту ночь был примерно таков: «Итак, я скоро умру. Мне кажется, что с таким здоровьем я не продержусь и пяти лет. — Тут Морриконе положил руку на свой живот, словно проверяя, на месте ли его больной желудок. — Что меня ждёт? Мне непременно нужно попасть в рай. Но чист ли я перед Господом? Может, за мной водятся грехи, о существовании которых я запамятовал? Кажется, я не сделал ничего дурного. Может, и не был совершенен, но уж точно не убивал и не прелюбодействовал. — Тут он беззаботно улыбнулся. — Я всегда чтил Божий Закон, честно служил Господу и людям, пускай всего лишь в чине дьякона. Может, это и скромное достижение, но разве не в скромности заключена добродетель? А с каким упорством я работал! Я и до сих пор в строю, несмотря на недуги и возраст. Думаю, что Господь не оставит это без внимания. Да, я несколько склонен к винопитию. Кое-кто даже смеётся над тем, что я каждую неделю хожу через весь город в предместье, чтобы купить там вино. Но вино плохо не само по себе. Просто многим оно затуманивает разум и превращает людей в животных. Мне же оно только согревает и веселит сердце, оставляя чистым мой разум и не смущая душу, поэтому никакой пагубы не несёт. А что до моих визитов в Меццане-ди-Сотто, то я не виноват, что только там делают вино, от которого у меня нет изжоги. Итак, — подходил он к заключению, — всё должно быть хорошо. Не натворить бы мне дел за то время, что ещё осталось. — Тут Морриконе снова усмехнулся. — Думаю, что меня ждёт рай. Уверен в этом. Тогда откуда эта тревога? Чего я боюсь?»"}, {"kind": "paragraph", "text": "Помимо мыслей о смерти, дьякон часто задавался философскими вопросами. В эту осеннюю ночь, например, он размышлял о загробной судьбе язычников. Морриконе недавно перечитал книгу Данте и думал о том, что все великие люди древности не попали в рай, а находятся в Лимбе. Неважно, насколько хорошим человеком ты был, но если ты не знаком с учением Христа, то в рай тебе вход закрыт. Разумеется, существовало исключение для ветхозаветных праведников. «Но Сократ, Цинциннат и Эпикур? — размышлял Морриконе. — Ведь они были прекрасными людьми, самыми достойными из язычников. Кто же виноват, что они родились не в то время и совсем не в том месте?! Почему они должны томиться в аду? Я уверен: знай они учение Христа, они бы с ним согласились и уверовали. Справедливо ли то, что произошло с ними? Странно, полвека я служу Господу и не могу ответить на такой простой вопрос. Не кроется ли в моих мыслях нечто богохульное? На всякий случай необходимо уточнить у пресвитера. Так или иначе, мне беспокоиться не о чем, ведь я крещён. А всё же обидно, что достойно прожитая жизнь этих титанов древности не избавила их души от томления в аду»."}, {"kind": "paragraph", "text": "Наконец дьякон уснул, решив, что со своими сомнениями он разберётся завтра."}, {"kind": "paragraph", "text": "На следующий день Морриконе напросился на ужин к своему пресвитеру. С отцом Агнози, настоятелем прихода, его связывали дружеские отношения, хотя втайне дьякон завидовал пресвитеру и считал, что тот занял завидную должность благодаря высоким покровителям. Морриконе было обидно, что сам он к своим шестидесяти пяти годам не достиг священнического сана и не мог самостоятельно совершать богослужения и читать проповеди, а лишь выступал в роли помощника. Также дьякону было известно о некоторых грешках Агнози (впрочем, не слишком серьёзных), о чём он любил при случае посплетничать. В то же время Морриконе признавал необыкновенное умение Агнози помогать людям мудрыми советами. Именно за таким советом он и отправился к пресвитеру."}, {"kind": "paragraph", "text": "Агнози, в свою очередь, считал Морриконе исполнительным помощником и человеком, которого не нужно постоянно укреплять в вере. Единственное, что не нравилось пресвитеру, так это то, что Морриконе не умел держать язык за зубами и частенько говорил лишнее, чтобы привлечь к себе внимание других."}, {"kind": "paragraph", "text": "Во время трапезы они держались друг с другом подчёркнуто вежливо и уважительно. Агнози знал, какое вино предпочитает Морриконе, и потчевал дьякона его любимой вальполичеллой."}, {"kind": "paragraph", "text": "— Как ваш желудок? — спросил настоятель."}, {"kind": "paragraph", "text": "— Неплохо, — ответил Морриконе. — Пока я пью это вино, у меня всё в порядке, но стоит воздержаться хотя бы на день, как тут же начинаются сильные боли."}, {"kind": "paragraph", "text": "— Досадно, — участливо произнёс Агнози. — А вы не хотели бы на время отойти от дел и заняться лечением?"}, {"kind": "paragraph", "text": "— Ни в коем случае! — воскликнул дьякон. — Ничто не может помешать мне исполнять свои обязанности и усердно служить Господу!"}, {"kind": "paragraph", "text": "— Рад слышать, Морриконе, я никогда не сомневался в вашем ревностном отношении к службе, — сказал Агнози."}, {"kind": "paragraph", "text": "Он догадывался: помимо прочего, Морриконе боится остаться без работы ещё и потому, что тогда его пристрастие к вину выйдет из-под контроля."}, {"kind": "paragraph", "text": "— Недуги приносят страдания нашему телу и благо нашей душе, если мы принимаем их со смирением и не ропщем, — сказал Морриконе, после чего в третий раз осушил свой бокал и умиротворённо откинулся на спинку стула."}, {"kind": "paragraph", "text": "— Это сущая правда, — добродушно согласился Агнози."}, {"kind": "paragraph", "text": "Дьякон почувствовал, что пришло время задать мучивший его вопрос."}, {"kind": "paragraph", "text": "— Святой отец, скажите, как вы относитесь к тому, что все великие люди древности, не познавшие Христа, обречены томиться в аду? — спросил он."}, {"kind": "paragraph", "text": "— Вы выбрали хорошую тему для разговора, мой друг, — кивнул Агнози. — Я понимаю, что вас беспокоит, когда-то меня тоже интересовал этот вопрос. Вы, должно быть, считаете несправедливым такое положение дел?"}, {"kind": "paragraph", "text": "— Я не знаю, но, возможно, в этом есть что-то... достойное сожаления, — осторожно проговорил дьякон. — Однако вы сказали, что вас это тоже беспокоило. Как вы ответили на этот вопрос для себя?"}, {"kind": "paragraph", "text": "— Что значит «для себя»? — пресвитер поднял брови. — Если есть ответ, то он одинаков для всех."}, {"kind": "paragraph", "text": "— Это справедливо и мудро. — Морриконе почтительно склонил голову. — Тем более мне хотелось бы его услышать."}, {"kind": "paragraph", "text": "— Мой друг, вы помните, почему Господь допускает зло, если сам Он представляет собой абсолютное благо? — спросил Агнози."}, {"kind": "paragraph", "text": "— Конечно, просто Его пути неисповедимы. Нам, смертным, не дано понять волю Господа; к этому выводу приходит, например, Иона, — без запинки ответил дьякон."}, {"kind": "paragraph", "text": "— Вот именно, Морриконе, здесь та же ситуация. Да, нам многое кажется несправедливым, но что мы знаем о справедливости? Мы не в состоянии постичь замысел Господа и можем только повиноваться ему. Не мучайте себя праздными размышлениями. О чём вам волноваться?"}, {"kind": "paragraph", "text": "— Я понял вас, святой отец, — ответил просиявший лицом Морриконе. — Что ж, постараюсь не думать об этом. И благодарю вас за мудрый совет."}, {"kind": "paragraph", "text": "— Вопросов, которые кажутся нам неразрешимыми, очень много, — продолжал между тем Агнози. — Но давайте не будем пытаться решать их здесь. Мы всё узнаем после смерти. Тогда-то и начнётся наша настоящая жизнь. — Агнози мечтательно улыбнулся. — Мы ничего не потеряем, если не успеем понять, как устроен мир, и многим рискуем, если поймём его неправильно. Вот почему мы и говорим о неисповедимости путей Господних. Мы говорим это нашим прихожанам, это же мы должны говорить себе в минуты собственных душевных терзаний."}, {"kind": "paragraph", "text": "— Благодарю вас, святой отец! — воскликнул Морриконе. — Мне действительно стало гораздо спокойнее!.."}, {"kind": "paragraph", "text": "Оставшуюся часть вечера они провели за игрой в шахматы, в которой дьякон по традиции поддавался Агнози."}, {"kind": "paragraph", "text": "Морриконе прощался с пресвитером в хорошем настроении — сказывались ободряющие наставления и кувшин вальполичеллы. Но сам путь до дома оказался для него тоскливым и мрачным — всё-таки эта осень плохо действовала на дьякона. Непонятно, почему он уже давно не мог чувствовать красоту этого времени года. Возможно, осень, как это ни банально, напоминала ему о собственных старости и увядании. Эта грязь под ногами и хмурое небо неизменно приводили дьякона в состояние меланхолии, от которого ему хотелось избавиться, ведь в нём не было ничего приятного и обнадёживающего. Дорожная грязь налипла на башмаки, затрудняя ходьбу. Вытаскивая из неё ноги, Морриконе пытался себя успокоить. Ему не о чем переживать. Жизнь прожита, и он провёл её пристойно, намного пристойнее большинства других людей. Ему есть чем гордиться. Он точно попадёт в рай. Почему идёт этот противный моросящий дождь? Почему холодный ветер пробирается ему под одежду? Было чувство, что мир вокруг слишком стар и измождён, как и сам дьякон. И всё-таки Морриконе решил не унывать, ведь впереди его ожидает вечная жизнь. Земная жизнь проходит, и пора готовиться к следующей."}, {"kind": "paragraph", "text": "Дьякон вернулся домой и снова взялся за Данте, ведь ему следовало заранее изучить место своего будущего пребывания. «Интересно, на какое из десяти небес я попаду? — подумал он. — Нужно всех предупредить, чтобы молились о спасении моей души, и в особенности отца Агнози; думаю, его молитвы будут иметь большой вес». Дьякон открыл окно, вдохнул промозглый воздух и посмотрел на тёмное небо. Было холодно, но он не стал закрывать окно, потому что в прохладной комнате ему лучше спалось. Морриконе лёг в постель и вскоре заснул с улыбкой умиротворения на морщинистом лице."}, {"kind": "paragraph", "text": "***"}, {"kind": "paragraph", "text": "Он проснулся от яркого света, который проникал через закрытые веки. «Неужели сегодня солнечный день?» — подумал дьякон, открыл глаза и тут же в испуге зажмурился. Какое-то время он лежал, замерев и даже не дыша. Потом Морриконе решился, рывком сел на постели и заставил себя открыть глаза и осмотреться."}, {"kind": "paragraph", "text": "Он находился в чужой и совершенно незнакомой комнате с драпированными стенами и дверным проёмом, откуда и лился яркий свет. Немногочисленная, но элегантная мебель, в том числе и ложе, на котором он проснулся, что-то смутно напоминали дьякону. Он с изумлением смотрел на стул с дугообразными ножками, превращавшимися в спинку, на низкий стол с прямоугольной столешницей, на украшенный резьбой ларь. «Где я? — потрясённо думал Морриконе. — Как я сюда попал? Неужели я в раю? Ну конечно! Где ещё может быть так светло?!» В этот момент он увидел свои руки и обомлел. Это были не его руки; молодые и крепкие, они не могли принадлежать ему, как не принадлежала и эта диковинная комната!.."}, {"kind": "paragraph", "text": "В полном смятении Морриконе осмотрел своё тело, вернее, те его части, которые он мог увидеть без помощи зеркала. По виду это было тело юноши, почти обнажённое, только чресла прикрывала треугольная повязка. Да и ощущал себя Морриконе соответственно. Обычно утренний подъём давался ему тяжело, его старое тело болело и противилось необходимости начинать новый день. Но сейчас дьякон не испытывал никакой боли, а, напротив, чувствовал лёгкость и полноту жизненных сил. «Итак, я молод, чувствую себя живее всех живущих, но где я всё-таки нахожусь?» — думал он. Мысль о рае уже не казалась убедительной и не разрешала всех вопросов. Слишком земным и реальным казалось Морриконе всё, что его окружало."}, {"kind": "paragraph", "text": "Он стал внимательно осматривать комнату и увидел на столе предмет, показавшийся ему зеркалом. Это и впрямь оказалось круглое бронзовое зеркало с ручкой. Отражение в нём испугало и заворожило Морриконе — отражение молодого, умного и прекрасного лица. Дьякон не мог оторвать от него взгляд и любовался им, как некогда любовался собою Нарцисс. Пугало же его то, что у самого Морриконе никогда, даже в юности, не было таких выразительных глаз, высокого прямого лба и твёрдого подбородка. «Я никогда не был таким, — в ошеломлении думал дьякон. — Неужели я оказался в теле другого человека? Но как такое возможно? Очевидно, что я не в раю! Тогда где я и что всё это значит? Быть может, я просто вижу сон?»"}, {"kind": "paragraph", "text": "Ступая по глинобитному полу, он подошёл к дверному проёму и увидел узкую галерею с колоннами, а за ней — внутренний двор, вымощенный каменными плитами, по периметру которого группировались жилые и хозяйственные постройки, а внутри росли зелёные деревья и белели статуи. Между ними расхаживал петух весьма редкой окраски — чёрный с красными вкраплениями. Тогда Морриконе и подумал: «Не могут же, в конце концов, в раю водиться петухи»."}, {"kind": "paragraph", "text": "Не придумав ничего лучшего, дьякон вернулся в свою постель и стал ожидать развития событий. Из комнаты, где он находился, вела дверь во внутренние покои дома, собственно, даже не дверь, а однотонная занавесь. И за ней дьякон периодически улавливал какие-то негромкие звуки. «Рано или поздно кто-то придёт сюда, и, может быть, тогда хоть что-то прояснится», — подумал Морриконе."}, {"kind": "paragraph", "text": "И впрямь спустя непродолжительное время за занавесью раздались быстрые шаги, и белая округлая рука откинула тяжёлую ткань. В комнату вошла женщина в длинном пеплосе (дьякон удивился тому, что знал, как называется её одежда)."}, {"kind": "paragraph", "text": "— Ты уже проснулся, Ксеноген, — сказала женщина приятным глубоким голосом. — Я принесла тебе одежду."}, {"kind": "paragraph", "text": "Странно, что язык, на котором она произнесла эти слова, был чужим для дьякона. Тем не менее он всё понял."}, {"kind": "paragraph", "text": "Между тем женщина подошла к Морриконе и протянула ему белый хламис (!)."}, {"kind": "paragraph", "text": "— Спасибо, мама, — неожиданно для себя ответил он на том же языке."}, {"kind": "paragraph", "text": "— Как тебе сегодня спалось?"}, {"kind": "paragraph", "text": "— Как всегда, хорошо. Однако я видел очень странный сон. Будто бы я старик и живу в какой-то непонятной стране, в каком-то странном городе, где большинство людей одеты в чёрное. Там я чувствовал великую грусть."}, {"kind": "paragraph", "text": "— Чего только не приснится! — улыбнулась женщина. — Надеюсь, этот сон не испортил твоего настроения?"}, {"kind": "paragraph", "text": "— Вовсе нет."}, {"kind": "paragraph", "text": "Дьякон заметил, что не может контролировать свою речь, вернее, речь юноши, в теле которого он находится. Слова срывались с губ помимо его воли. Так, он называл эту женщину матерью и даже знал её имя — Ипатия. Мало того, он знал, что у него есть отец, который сейчас в военном походе, и что у них состоятельная семья."}, {"kind": "paragraph", "text": "Но важнее всего было другое: несмотря на то, что он был не властен над речью юноши, дьякон превосходно управлял его телом и с каждой минутой чувствовал себя в нём всё увереннее."}, {"kind": "paragraph", "text": "Но что за странный сон приснился этому Ксеногену? Неужели вся жизнь Морриконе была лишь сонным видением этого юноши, жившего в античности? Но как тогда понять, что у дьякона были собственное сознание и память, никак не связанные с жизнью Ксеногена? Голова у Морриконе шла кругом. Вдруг он вспомнил слова мудрого Агнози, который только вчера (!) советовал ему не обременять себя лишними вопросами. Именно так и решил поступить Морриконе: ни о чём не думать и ждать, пока всё прояснится само собой. Тем более что находиться в молодом и красивом теле под ясным небом Эллады было так приятно!.."}, {"kind": "paragraph", "text": "— Вставай, а то опоздаешь, — сказала женщина."}, {"kind": "paragraph", "text": "«Куда?» — хотел было спросить Морриконе, но тут же вспомнил. Он ходил туда каждый день и обучался владению оружием и боевому построению. А до этого он одиннадцать лет учился чтению и письму, постигал премудрости арифметики, геометрии, астрономии, а также музыки и занимался многими видами спорта: борьбой и кулачными боями, бегом, метанием диска и копья... Пока перед его мысленным взором проносились картины детства и юности, женщина ушла, оставив его одного."}, {"kind": "paragraph", "text": "«Итак, я в теле другого человека и нахожусь в Древней Греции, — резюмировал Морриконе. — Да как же такое возможно?» Дьякон упал на колени, чтобы воззвать к Господу в мольбе, но вдруг понял, что не знает, о чём ему молиться, о чём просить Бога. Чего он хочет? Вернуться назад, в слякотную Верону и своё дряхлеющее тело, чтобы тихо дожидаться смерти? Морриконе горестно вздохнул. Нет, не этого ему хотелось. Напротив, он ощущал такое горячее стремление жить, такой восторг перед открывающимися для него возможностями, что сама мысль о смерти казалась кощунственной. И дьякон снова решил не делать поспешных выводов и предоставить событиям идти своим чередом."}, {"kind": "paragraph", "text": "На улицу Морриконе вышел не без приключения: открывая дверь, он едва не сбил с ног прохожего."}, {"kind": "paragraph", "text": "— Стучать надо, чтоб тебя!.. — сказал тот озлобленно. И дьякон вспомнил, что здесь действительно очень узкие улицы, а двери домов открываются наружу, и чтобы выйти, необходимо изнутри постучать в дверь. Эта история его развеселила, а прохожий обиделся всерьёз и удалился, что-то сердито бурча себе под нос."}, {"kind": "paragraph", "text": "Дьякон же испытывал всё большее чувство восторга. Он был в центре великой культуры, о которой так много читал и слышал. «А что, если я встречу Сократа? — подумалось ему. — Интересно, какой сейчас год?» Ему хотелось побежать от радости и оттого, что он вновь способен быстро бегать, и Морриконе с трудом сдерживал свой пыл."}, {"kind": "paragraph", "text": "Ему не нужно было задумываться о том, куда свернуть; быстрые ноги Ксеногена сами несли его по уличному лабиринту. Он припоминал имена всех людей, которых мог встретить здесь, и думал, что знает о Ксеногене всё. Неожиданно в голову к нему пришла странная мысль, и он замедлил шаги. «А кто же я на самом деле — Ксеноген или Морриконе? — спросил себя дьякон. — У меня такое чувство, что я провёл здесь всю жизнь, все свои восемнадцать лет. Но и жизнь в Вероне я тоже помню отлично. Кем же мне считать себя?..»"}, {"kind": "paragraph", "text": "Размышления Морриконе прервала шумная толпа догнавших его молодых людей."}, {"kind": "paragraph", "text": "— Ксеноген, ты тащишься, словно черепаха! — крикнул один из юношей и подхватил дьякона под руку."}, {"kind": "paragraph", "text": "— Я сравнил бы тебя с Ахиллом, да только ты всё-таки меня настиг, — весело парировал тот."}, {"kind": "paragraph", "text": "— Всё шутишь, — засмеялся его спутник."}, {"kind": "paragraph", "text": "Друзья окружили Морриконе. Было так приятно смотреть в их приветливые молодые лица, лучащиеся счастьем. Вчерашний дьякон был в центре внимания, а это всегда доставляло ему удовольствие. Он вдруг вспомнил свою одинокую жизнь в Вероне: прилежное служение в храме, уединённое чтение книг, визиты в Меццане-ди-Сотто... Да, ещё редкие вечера в обществе отца Агнози. Но даже духовные беседы с пресвитером, которые он так ценил, нельзя было сравнить с тем лёгким непринуждённым разговором, что он вёл сейчас со своими приятелями. Морриконе почувствовал, что ни за какие сокровища мира не согласился бы вернуться в свою веронскую жизнь."}, {"kind": "paragraph", "text": "А разговор становился всё оживлённей и всё больше увлекал Морриконе… как вдруг он похолодел и сердце его упало. Это случилось в тот миг, когда его уста произнесли слова: «Клянусь Зевсом!» Дьякон понял, что уже не первый раз вымолвил это имя, а также имена других богов. «О господи, они же язычники! — ошеломлённо подумал Морриконе. — Они не слышали Благую весть! Они даже не иудеи. О каких богах я тут говорил? Я упомянул Зевса! Ещё и поклялся его именем. Какое богохульство! Но с другой стороны, если я Ксеноген, то я тоже язычник! Так кто же я — эллинский юноша или дьякон церкви Святого Зенона? Если я Ксеноген, то после смерти я попаду в ад! Язычникам нет спасения. Что же теперь мне делать?» Вся весёлость вмиг слетела с него, и Морриконе погрузился в тягостные размышления."}, {"kind": "paragraph", "text": "А день шёл своим чередом. Юноши овладевали воинскими навыками и излучали боевой задор. И только Морриконе не мог отделаться от своих переживаний, его не радовали даже собственные сила и ловкость. В таком разладе душа дьякона пребывала почти до вечера, пока он не принял окончательного решения. «Я невиновен в том, что со мной случилось, — рассуждал Морриконе. — Я не просил Господа посылать меня сюда. Живя в Вероне, я оставался добрым христианином. Теперь же я такой, как все эти юноши, как все жители этого города, как мои отец и мать. Значит, я должен вести себя по их правилам». И Морриконе почувствовал, как с его плеч упала великая тяжесть."}, {"kind": "paragraph", "text": "Но когда он вернулся домой, его ожидало последнее и самое страшное испытание. Дело в том, что Ипатия невольно поставила его перед выбором, уклониться от которого Морриконе не мог."}, {"kind": "paragraph", "text": "— Как прошли занятия? — спросила она."}, {"kind": "paragraph", "text": "— Очень хорошо, мама, но я сильно устал."}, {"kind": "paragraph", "text": "— Тогда выполни мою последнюю просьбу, Ксеноген, и я тебя больше не потревожу."}, {"kind": "paragraph", "text": "— Какую просьбу?"}, {"kind": "paragraph", "text": "— Пришли вести от отца. Он сообщает, что был ранен, но сейчас уже поправляется. Отец просит тебя принести его любимого петуха в жертву Асклепию."}, {"kind": "paragraph", "text": "Морриконе растерялся. Ему предлагали совершить языческий ритуал — принести жертву богу врачевания, что для дьякона было самым настоящим святотатством."}, {"kind": "paragraph", "text": "Он нерешительно направился во внутренний двор и долго смотрел на того самого петуха — чёрного, с красными вкраплениями... Ипатия уже дважды окликала своего сына. Когда она позвала его в третий раз, Морриконе понял, что нужно действовать."}, {"kind": "paragraph", "text": "Дьякон ещё раз отметил, какое ловкое тело ему досталось, ведь он поймал петуха за считаные секунды. Священный алтарь располагался тут же, во дворе. Морриконе стоял перед мраморным жертвенником, в одной руке он держал за лапы петуха, а другой сжимал ритуальный нож. Ему казалось, что весь мир замер в ожидании и смотрит на него. «Чего я хочу? — в который раз за этот безумный день спросил себя Морриконе. — Я хочу попасть в рай. Пускай я живу задолго до нашей эры, задолго до прихода Христа, но я знаю Его учение, и если я буду ему следовать, то окажусь в раю. Согласно легенде, Рифей верил в приход мессии — и вот он на небе. Ещё Троян спасся, но за него молился сам Папа, а кто будет молиться за меня? Отец Агнози, будь он неладен? Он даже не знает, что я здесь! Хорошо, допустим, я останусь верен Христу, но тогда я не должен сидеть сложа руки. Мне придётся проповедовать, а значит, умереть за веру или, в лучшем случае, оказаться в изгнании. Но как же я не хочу уходить отсюда!.. Я хочу жить здесь и наслаждаться полнотой своего бытия. Но если я останусь, то буду должен почитать здешних богов и исполнять все религиозные обряды. Я могу прожить счастливую жизнь, но уж точно не попаду в рай»."}, {"kind": "paragraph", "text": "«Я мог бы оправдаться тем, — продолжал он, — что не только получил чужое тело, но стал другим человеком, то есть Ксеногеном. Увы, то, что я знаю об этом юноше всё, не сделало меня им, иначе у меня отняли бы память о жизни в Вероне. Я — Морриконе, дьякон церкви Святого Зенона, чья душа пребывает в чужом теле, следовательно, мне придётся отвечать за свой выбор»."}, {"kind": "paragraph", "text": "Однако всё существо Морриконе протестовало против этой мысли и искало способ обойти её. «С чего я вообще взял, что попаду на небо? — вопрошал дьякон. — Так ли праведно я жил? Да, не убивал, не прелюбодействовал, не крал чужого, но, возможно, за мной водятся другие грехи? Точно! Я всегда завидовал отцу Агнози! Я распускал о нём слухи, иногда абсолютно лживые. Господи, да я негодяй, которому прямая дорога в ад! Мне просто повезло оказаться здесь! У меня есть шанс начать всё заново, прожить долгую счастливую жизнь в другом теле и другом времени!.. Но нет, пожалуй, я несу вздор»."}, {"kind": "paragraph", "text": "Тем временем чёрный петух старался вырваться из его крепкой руки, и Морриконе подумал, что и сам он вот так же судорожно пытается спасти себя. Он вспомнил, как проснулся этим утром. Как ему было хорошо, когда солнечный свет наполнял не только его комнату, но и всё его существо. Как он смотрел на своё отражение в бронзовом зеркале... Его пугала мысль об изгнании, а что, если его вообще казнят? Заставят выпить яд, например. Морриконе содрогнулся и взмахнул остро отточенным ножом. На алтарь хлынула тёплая кровь."}, {"kind": "paragraph", "text": "В тот же миг всё поплыло перед глазами Морриконе. Внутренний двор с жертвенником стал растворяться, и на его месте проявился неф храма Зенона, лицо спешащей к нему Ипатии сделалось лицом отца Агнози. Затем всё обрушилось, словно декорации на сцене театра. Морриконе оказался один посреди ничем не заполненного пространства. Он увидел, как сверху к нему стремительно приближается ангел с зазубренным ножом — весь в пламени грозного огня. И единственным, что успел произнести бедный дьякон, были слова о том, что последнего и самого тяжкого в своей жизни испытания он не выдержал."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
7	mrd6-vechnyy-zov	Вечный зов	45	mrd6/mrd6-vechnyy-zov.png	data:image/jpeg;base64,	Неделю я постился. Питался только варёным овсом, горохом да чёрным хлебом. Это было частью творческого процесса. Без устали я исписывал ни в чём не повинные листы бумаги. Строчил, как после допроса с пристрастием. Хотел 	[{"kind": "image", "path": "mrd6/mrd6-vechnyy-zov.png", "caption": "Иллюстрация Екатерины Ковалевской"}, {"kind": "paragraph", "text": "Неделю я постился. Питался только варёным овсом, горохом да чёрным хлебом. Это было частью творческого процесса. Без устали я исписывал ни в чём не повинные листы бумаги. Строчил, как после допроса с пристрастием. Хотел написать рассказ о том, как живётся в здоровом теле здоровому духу."}, {"kind": "paragraph", "text": "Чувствовал я себя отлично. Мог ещё пару недель так продержаться — лопать овёс и горошницу. Факультативное отшельничество тоже влияло благоприятно. От избытка энергии я начал обливаться холодной водой и делать гимнастику. Наутро восторженно просыпался и по-доброму зверел. Однако надолго меня не хватало. Начинало мерещиться, что я на полпути к небесам, теряю плотность и взлетаю. Ощущение приятное, но невыносимое в общении с людьми — хотелось прыгать, кувыркаться и громко петь в ответ на их глупости."}, {"kind": "paragraph", "text": "Осознавая, что в состоянии бодхисаттвы мне пока нет места среди обычных людей, я возвращался на землю в поисках приключений."}, {"kind": "paragraph", "text": "Добровольная ссылка проходила в подмосковном Пущине. Друзья дали ключи от пустующей квартиры, где можно было вволю бодаться со свободой выбора. Один в маленьком городке и в такой же миниатюрной тесной квартирке, я чувствовал себя спокойно, пока не возникло желание активно поучаствовать в жизни и с удовольствием оскоромиться. Оно появилось, как только я об этом написал."}, {"kind": "paragraph", "text": "Я отложил ручку и вышел в прихожую. Прислушался. Тишина. Выглянул. Никого. Квартиры были расположены в длинном коридоре, где постоянно ходили и что-то делали. А сейчас никого. Я натянул вязаную шапочку, делавшую меня похожим на неунывающего бродягу из артхаусного фильма, и вышел во двор. Ни души. Не с кем даже парой фраз переброситься."}, {"kind": "paragraph", "text": "— Кто ищет — вынужден блуждать, — подбодрил я себя словами из «Фауста»."}, {"kind": "paragraph", "text": "До моего слуха донеслись звуки шагов — кто-то быстро спускался по лестнице. Я оживился. Вышел мелкий подросток, деловито спросил огня, прикурил и исчез в темноте."}, {"kind": "paragraph", "text": "— Приключений на сегодня маловато, — проговорил я. — Надо же, ведь и сходить в гости не к кому."}, {"kind": "paragraph", "text": "Я вздохнул. Уже год, как я перебрался из Сибири в столицу, обтирая боками чужие углы. Но и в большом городе мне дышалось через раз. В его суете я видел мелькание спиц огромного колеса бхавачакры, летевшего с горы в пропасть. Разве в городах есть настоящая свобода? В них люди скрываются от свободы, как должники. Как говорил мой деревенский приятель, «большой город — плохое место для того, чтобы быть хорошим парнем». Иногда, переутомившись быть перекати-полем, я начинал думать, что пора обзавестись собственным домом. Но представив, как из года в год смотрю в одно и то же окно, гадая, кто постучит в дверь, я срывался с насиженного места в поисках того, что получше, и не находил."}, {"kind": "paragraph", "text": "С Оки подул холодный ветер — я поднял ворот. Ветер подул сильнее — на крыше печально загудели, качаясь, антенны. Глядя на них, я вспомнил чьи-то строчки: «И плавают среди тумана реи, как чёрные могильные кресты»."}, {"kind": "paragraph", "text": "«Надо сниматься с якоря, — подумал я, — приключения здесь не светят»."}, {"kind": "paragraph", "text": "Только я вернулся и уставился в зеркало прихожей, любуясь на небритую рожу и бродяжью шапочку, как в дверь постучали."}, {"kind": "paragraph", "text": "На пороге стояла миловидная девушка."}, {"kind": "paragraph", "text": "— А Оли Персиковой здесь нет? — спросила она."}, {"kind": "paragraph", "text": "«Сама ты как персик, — подумал я. — Так бы и съел тебя, малышка»."}, {"kind": "paragraph", "text": "Но вслух многозначительно произнёс:"}, {"kind": "paragraph", "text": "— Нет пока что…"}, {"kind": "paragraph", "text": "Девушка на мгновение задумалась."}, {"kind": "paragraph", "text": "— Проходи, подождём её вместе, — предложил я."}, {"kind": "paragraph", "text": "— Спасибо, не могу, — смутилась девица и спешно отступила."}, {"kind": "paragraph", "text": "Я не стал её удерживать. Но, увидев на столе ручку и раскрытую тетрадь, решил, что Оля Персикова — подходящее имя для героини весёлого рассказа, и стал записывать рождавшиеся в голове образы."}, {"kind": "paragraph", "text": "Камамбер для Оли Персиковой"}, {"kind": "paragraph", "text": "Всё началось с того вечера, когда Антону стали мерещиться два самурая, следовавшие за ним по улицам. Они мелькали в толпе где-то за спиной и не подходили ближе. Они таскались за ним всюду и не спускались только в метро, но стоило Антону выйти наверх, самураи появлялись вновь."}, {"kind": "paragraph", "text": "Он рассказал об этом своей подруге Оле Персиковой, когда они гуляли по Смоленской набережной. Она долго смеялась и посоветовала не засиживаться перед компьютером и пораньше ложиться спать. Антон вернулся домой и лёг спать раньше обычного. Ему приснилось, что они с Олей в отеле «Золотое кольцо» сидят в ресторане «МОМОЯМА», что в переводе с японского «Персиковая гора», пьют тёмное пиво «Кирин», едят лапшу ширатаки из конняку и смотрят на ручей с карпами."}, {"kind": "paragraph", "text": "— К вашим услугам также татами рум и тэппанъяки, — улыбаясь, предлагал узкоглазый официант."}, {"kind": "paragraph", "text": "Наутро по дороге на работу, листая журнал в метро, Антон наткнулся на статью о традиционной японской эстрадной песне в стиле энка, когда исполнитель использует определённые мелодические ходы и у него обязательно должен быть гортанный, чуть вибрирующий вокал."}, {"kind": "paragraph", "text": "«Наверное, как у Игги Попа после уроков горлового пения», — подумал Антон, с трудом представляя, что из этого может получиться."}, {"kind": "paragraph", "text": "Также говорилось, что энка невероятно популярна в Японии, как шансон во Франции, как романсы в России."}, {"kind": "paragraph", "text": "«Разве у нас популярны романсы? Нет, наверное, энка — это типа наших блатных песен», — решил Антон."}, {"kind": "paragraph", "text": "На выходе в кармане завибрировал мобильник — звонил приятель. Он сообщил, что сегодня в клубе «Китайский лётчик Джао Да» будет выступать группа «Два японца»."}, {"kind": "paragraph", "text": "— Они что, правда японцы? — спросил Антон, переваривая такие совпадения."}, {"kind": "paragraph", "text": "— Нет, что ты! Русские. Откуда-то из Владивостока."}, {"kind": "paragraph", "text": "— А, понятно, — сказал Антон, хотя ему было ничего не понятно."}, {"kind": "paragraph", "text": "— Пойдёшь?"}, {"kind": "paragraph", "text": "— Наверное."}, {"kind": "paragraph", "text": "— Окей, тогда в полседьмого у выхода из метро."}, {"kind": "paragraph", "text": "— Ладно."}, {"kind": "paragraph", "text": "Выйдя на улицу, Антон прошёл два квартала и оглянулся. Самураи толклись где-то сзади, и вид у них был смурной, словно они вчера весь день пили саке и в конце застолья не поели отядзукэ."}, {"kind": "paragraph", "text": "«У самурая вид смурной, потому что он бухой», — невесело подумал Антон и прибавил шагу."}, {"kind": "paragraph", "text": "Потом резко свернул на перекрёстке и притормозил. Постоял. Никого. Выглянул. Тоже никого. Тогда он позвонил Оле."}, {"kind": "paragraph", "text": "— Привет, Оль, пойдёшь на концерт?"}, {"kind": "paragraph", "text": "Когда они обо всём договорились и решили, где встретятся, Антон не выдержал и признался:"}, {"kind": "paragraph", "text": "— Я опять их видел."}, {"kind": "paragraph", "text": "— Кого?"}, {"kind": "paragraph", "text": "— Самураев этих. В толпе маячили за спиной."}, {"kind": "paragraph", "text": "Оля ничего не ответила и положила трубку. Послушав гудки, Антон осмотрелся и пошёл дальше."}, {"kind": "paragraph", "text": "Рабочий день пролетел быстро, и чуть раньше обычного Антон улизнул из офиса. Надо было перекусить. Он вошёл в кафе, где они договорились встретиться, и решил, не дожидаясь Оли, что-нибудь съесть. Почему-то в меню ему больше всего приглянулся сыр камамбер, порезанный ломтиками, с веточками свежего розмарина. Антон слышал от кого-то, что это вкусно."}, {"kind": "paragraph", "text": "— А у вас ничего из японской кухни нет? — на всякий случай спросил Антон."}, {"kind": "paragraph", "text": "Официант принял это за попытку быть оригинальным и лишь замотал головой."}, {"kind": "paragraph", "text": "Не успел Антон попробовать, что же ему принесли, как за окном увидел самураев. Они стояли на противоположной стороне улицы и делали какие-то знаки. Антон даже сначала и не понял, что знаки адресуются ему. Разинув рот, он смотрел на мужиков в больших конусных соломенных шляпах, скрывавших их лица, как на чудо света, пока до него не стал доходить смысл знаков: самураи его подзывают."}, {"kind": "paragraph", "text": "С опаской Антон вышел."}, {"kind": "paragraph", "text": "— Вам чего? — крикнул он прямо через дорогу."}, {"kind": "paragraph", "text": "Самураи закивали и даже пару раз поклонились до самой земли."}, {"kind": "paragraph", "text": "«Да что там, ладно, подойду, — решил Антон, — не съедят же они меня. Может, у них важное дело ко мне. Не зря же они ходят по пятам»."}, {"kind": "paragraph", "text": "— Вам чего? — повторил вопрос Антон, приблизившись к самураям, но сохраняя порядочную дистанцию."}, {"kind": "paragraph", "text": "— Мы с братом выиграли ваше покровительство в маджонг, — на отличном русском доложил самурай."}, {"kind": "paragraph", "text": "— Во что?"}, {"kind": "paragraph", "text": "— Это такая игра в кости."}, {"kind": "paragraph", "text": "— А-а. И что?"}, {"kind": "paragraph", "text": "— Мы с братом ронины."}, {"kind": "paragraph", "text": "— Кто?"}, {"kind": "paragraph", "text": "— Самураи без сюзерена."}, {"kind": "paragraph", "text": "— Без кого?"}, {"kind": "paragraph", "text": "— Без хозяина-покровителя."}, {"kind": "paragraph", "text": "— И что?"}, {"kind": "paragraph", "text": "— Теперь наш покровитель — это вы, — сказал самурай."}, {"kind": "paragraph", "text": "А тот, который молчал, закивал что есть силы, пугая прохожих."}, {"kind": "paragraph", "text": "— Почему это я? — не зная, как объяснить самураям, что они ошиблись, спрашивал Антон."}, {"kind": "paragraph", "text": "— Потому что мы выиграли ваше покровительство."}, {"kind": "paragraph", "text": "— У кого?"}, {"kind": "paragraph", "text": "Самурай назвал незнакомое имя."}, {"kind": "paragraph", "text": "— Мне это имя ничего не говорит, — пожал плечами Антон. — В чём дело? Это что, розыгрыш? Вас прислал кто-то из моих друзей?"}, {"kind": "paragraph", "text": "— Никакой ошибки, сэнсэй. Приказывайте."}, {"kind": "paragraph", "text": "— Что приказывать?"}, {"kind": "paragraph", "text": "— Что угодно, мы всё выполним. Найдём вам невесту и убьём ваших врагов."}, {"kind": "paragraph", "text": "— Зачем? — испугался Антон."}, {"kind": "paragraph", "text": "— Любое ваше желание для нас закон! — хором и грубо, словно обещая убить его самого, проорали самураи, отчего один прохожий, соскочив с тротуара, чуть не попал под машину."}, {"kind": "paragraph", "text": "— Так, тише, тише, я всё понял, — стал успокаивать самураев Антон, хотя ничего не понимал. — Вы… это… пока ничего не предпринимайте без меня, встретимся завтра и решим, чем вам заняться. У меня сейчас встреча с девушкой. Завтра, а?"}, {"kind": "paragraph", "text": "— Сайко! — воскликнули хором самураи и исчезли, словно их и не было."}, {"kind": "paragraph", "text": "Антон глупо уставился на то место, где только что видел двух мужиков в просторных халатах и шароварах."}, {"kind": "paragraph", "text": "— Антон! — услышал он голос Оли."}, {"kind": "paragraph", "text": "Она стояла возле входа в кафе. Не понимая, что происходит, Антон подошёл к подружке. Вместе они вернулись за столик, и тут только он понял, что Оля с ним разговаривает."}, {"kind": "paragraph", "text": "— А? Что? — ошалело воскликнул Антон."}, {"kind": "paragraph", "text": "— Что это в тарелке? Третий раз спрашиваю тебя, — говорила Оля. — Ты в порядке?"}, {"kind": "paragraph", "text": "— Да… в порядке. Это сыр, камамбер… для тебя."}, {"kind": "paragraph", "text": "— М-м, вкусняшка! — пробуя, хвалила Оля. — А ты чего не ешь?"}, {"kind": "paragraph", "text": "— Думаю."}, {"kind": "paragraph", "text": "— О чём?"}, {"kind": "paragraph", "text": "— О самураях."}, {"kind": "paragraph", "text": "— Слушай, это уже не смешно, — серьёзно сказала Оля. — Ещё одно слово о них, и я обижусь."}, {"kind": "paragraph", "text": "— Хорошо, но… А как же концерт?"}, {"kind": "paragraph", "text": "— Что за концерт?"}, {"kind": "paragraph", "text": "— Ну концерт. Сегодня выступают два…"}, {"kind": "paragraph", "text": "— Что два?"}, {"kind": "paragraph", "text": "— Два… два… Забыл. Ладно, пошли, уже пора."}, {"kind": "paragraph", "text": "— Пошли. Сейчас, только съем ещё кусочек сыра."}, {"kind": "paragraph", "text": "Оля доела, и они пошли на концерт."}, {"kind": "paragraph", "text": "Первая часть рассказа была написана. Отложив ручку, я посмотрелся в зеркало и покрутил пальцем у виска."}, {"kind": "paragraph", "text": "— Будешь сочинять такие рассказы — никто за тебя как за писателя и гроша ломаного не даст, — сурово сказал я отражению."}, {"kind": "paragraph", "text": "— Это почему же? — удивилось оно."}, {"kind": "paragraph", "text": "Но я лишь пожал плечами — мол, само разбирайся."}, {"kind": "paragraph", "text": "— А мне и не надо ломаных грошей, — обиделось отражение и отвернулось."}, {"kind": "paragraph", "text": "Было поздно, я включил на проигрывателе диск ‘Camembert Electrique’ группы Gong и лёг спать. У меня была давняя привычка — ставить на ночь на реверс негромкую психоделическую или этническую музыку, и ночь проходила в астральных путешествиях. Под утро приснилась Оля Персикова: она нещадно ругала за то, что я дал ей ещё одну жизнь и теперь ей придётся жить с каким-то Антоном, которого она никогда не знала и знать бы не хотела. «Вот глупая, — подумал я во сне, — чего ей надо от меня?» Но она упорно повторяла моё имя:"}, {"kind": "paragraph", "text": "— Петя… Петя…"}, {"kind": "paragraph", "text": "Я открыл глаза и увидел Анчу Баранову. Она прилетела из Америки, хотя по моим расчётам это должно было произойти завтра. Квартира принадлежала ей. До меня здесь дежурил какой-то малец, судя по всему, растяпа, так как в аквариуме сварились рыбки, а в горшке завяло не политое вовремя молодое деревце граната. Я был ни в чём не виноват. Ну если только в том, что родился без царя в голове и порылся, как в своей, в богатой Анчиной библиотеке."}, {"kind": "paragraph", "text": "Анча поохала над катастрофами в квартире и принялась рассказывать о Балтиморе, где проводила опыты на мышах в микробиологической лаборатории. Она вспомнила, что в Балтиморе есть знакомая в иммигрантском издательстве и можно попробовать отдать мою книгу о моряках."}, {"kind": "paragraph", "text": "— Кому она там нужна? — сомневался я."}, {"kind": "paragraph", "text": "— Всё-таки Балтимор стоит на побережье, их должна прельстить морская тематика твоей книги, — уверенно подытожила Анча."}, {"kind": "paragraph", "text": "— Да… но море у меня из вина…"}, {"kind": "paragraph", "text": "— Ерунда! Корабли как настоящие, моряки на них плывут к далёким берегам. Всё выдержано в морской эстетике. Ведь так?"}, {"kind": "paragraph", "text": "— Так-то так, но… — неуверенно согласился я."}, {"kind": "paragraph", "text": "— Всё, устала, устала, просто валюсь с ног! — пожаловалась Анча. — Сорок восемь часов на ногах, аэропорт, самолёт, таможня... Мы ещё с подругой сходили перед вылетом на дискотеку."}, {"kind": "paragraph", "text": "— Куда?"}, {"kind": "paragraph", "text": "— На дискотеку."}, {"kind": "paragraph", "text": "— И как там дискотеки?"}, {"kind": "paragraph", "text": "— Молодёжи, тинейджеров мало, тусят в основном от тридцати и старше."}, {"kind": "paragraph", "text": "— Наверное, скоро тоже начну ходить на дискотеки, — только и нашёл я что сказать."}, {"kind": "paragraph", "text": "Анча закрыла глаза. Я пошёл на кухню посмотреть, что можно съесть без вреда для здоровья. Только заглянул в пустой холодильник, как рядом появилась Анча."}, {"kind": "paragraph", "text": "— Как у тебя с работой? — спросила она."}, {"kind": "paragraph", "text": "— Уволился со стройки: кидалово началось."}, {"kind": "paragraph", "text": "— Ты бы устроился давно в какой-нибудь журнал — статьи писать или редактором."}, {"kind": "paragraph", "text": "— Пробовал. «Пишете, — говорят, — неформат, много ошибок и отсебятины»."}, {"kind": "paragraph", "text": "— Ещё попробуй, не на стройке же зимой работать."}, {"kind": "paragraph", "text": "— Понятное дело."}, {"kind": "paragraph", "text": "— На, пусть будут, у тебя же их всё равно нет, — протянула Анча пятисотрублёвую банкноту."}, {"kind": "paragraph", "text": "Я взял — правда, пусть будут."}, {"kind": "paragraph", "text": "Анча тихо посапывала во сне, я оделся и пошёл в магазин. Купил сыра, орехов и маленькую бутылочку мартини, похожую на соску. Вернувшись, я до сумерек цедил из неё и листал «Новеллистику эпохи Эдо»."}, {"kind": "paragraph", "text": "Вечером я уже был в пути и клевал носом. Тёмные тёплые внутренности большого автобуса были как утроба миролюбивого животного, и всё вокруг, проплывая во мраке, тоже было частью полусна. Но вот небо впереди засветилось. Огни города, точно посадочные маяки космодрома, указывали на окончание полёта. Навстречу, зазывая рекламными плакатами и обещая забвение, выскакивал разноцветный, похожий на балаган мир."}, {"kind": "paragraph", "text": "Отзвонив по знакомым телефонам, я понял, что домашнее тепло в ближайшие часы не улыбается, и отправился в центр города."}, {"kind": "paragraph", "text": "В конце сверкающего зала Елисеевского магазина, в буфете, в одном из последних оплотов советской эпохи, за кофе и пирожным я представлял мир, где моё желание управляет происходящим. А что тут невозможного? Русский психиатр Павел Ковалевский без шуток рассказывал о воспитании «неведомых способностей» путём уравновешивания духа. Главное — соблюдать гигиену и строгую диететику тела и духа. Чем я, собственно, и занимался последнюю неделю, балансируя на грани esse oportet ut vivas, non vivere ut edas (нужно есть, чтобы жить, а не жить, чтобы есть)."}, {"kind": "paragraph", "text": "Глянув на вход, я сморгнул, сетуя на зрение. Из двенадцати миллионов человек, поселившихся в этом городе, на зов откликнулись мои друзья, кому я названивал час назад."}, {"kind": "paragraph", "text": "— Вот ты где! — тоже удивились Стёпа и Вера. — А мы только что гуляли по бульвару и тебя вспоминали, а ты рядом, в Елисеевском сидишь!"}, {"kind": "paragraph", "text": "Они недавно вступили в законный брак и светились от счастья."}, {"kind": "paragraph", "text": "— Разговелся малость, — не скрывал радость и я. — Присоединяйтесь, друзья! Сегодня праздник: в Японии отмечают День благодарности труду."}, {"kind": "paragraph", "text": "— Ха-ха, мы своё наотмечались!"}, {"kind": "paragraph", "text": "Молодожёны взяли зелёный чай и по куску черничного пирога."}, {"kind": "paragraph", "text": "— Пойдёшь на концерт в «Китайский лётчик»?"}, {"kind": "paragraph", "text": "— На какой ещё концерт? — насторожился я."}, {"kind": "paragraph", "text": "— Сергей и Егор Летовы."}, {"kind": "paragraph", "text": "— Хм, почти как два японца, — улыбнулся я."}, {"kind": "paragraph", "text": "— Чего? — не поняли молодожёны."}, {"kind": "paragraph", "text": "— Круто, говорю, но я в режиме экономии. Ездил на неделю в Пущино, пока вы в Барнауле были. Как там, как всё прошло?"}, {"kind": "paragraph", "text": "— Нормально, в Сибири давно зима, сугробы. Чуть не окоченели на мосту, пока замок цепляли."}, {"kind": "paragraph", "text": "Молодожёнов переполнял позитив, с ними было легко говорить. Не хотелось вторгаться в их идиллию вопросами о ночлеге и брать в долг. Они предлагали одолжить денег на концерт, но я молча покачал головой. Я дозвонился до приятеля, у которого можно было переночевать, и стал прощаться."}, {"kind": "paragraph", "text": "— Ты какой-то задумчивый сегодня, — пожимая руку, сказал молодой муж."}, {"kind": "paragraph", "text": "— Может, влюбился, — улыбнулась его жена."}, {"kind": "paragraph", "text": "— Или рассказ новый сочиняешь, — набросил версию Стёпа."}, {"kind": "paragraph", "text": "— Пока."}, {"kind": "paragraph", "text": "Каждый день мы расстаёмся с теми, кого любим, чтобы встретиться вновь. И для того чтобы наступила новая встреча, нам не нужно договариваться и назначать её, записывать номера телефонов и адреса. Мы вплетены в судьбы друг друга, оплавлены общей жизнью, и стоит лишь послать зов — встреча сама нас найдёт."}, {"kind": "paragraph", "text": "Вечно что-то зовёт. Сегодня дорога, завтра море или горы, послезавтра любимый человек. И во сне слышен далёкий шёпот — зовут непрочитанные книги, неувиденные страны, ненаписанные истории, нерождённые дети, неразбуженные миры, забытые родители и друзья. Надо слушать и откликаться. Жизнь зовёт, предлагая себя и никому и ничего не обещая взамен."}, {"kind": "paragraph", "text": "Расставшись с друзьями, я ещё прошёлся вниз по Тверской, постоял у спуска в метро, прислушиваясь, не зовёт ли кто или что. А ведь звало:"}, {"kind": "paragraph", "text": "Концерт был так себе. «Два японца» походили на богатых клоунов, взявшихся за инструменты. Скучая, Оля Персикова лениво пресекала попытки Антона напиться. Но тот держался за приятеля, и к полуночи они напробовались «Заводного мандарина» и «Абрикосового Джао» так, что еле держались на ногах. После концерта поймали машину и поехали по домам. Оля решила заночевать у Антона."}, {"kind": "paragraph", "text": "Когда такси подъезжало к дому на Воробьёвых горах, Оля заметила две странные фигуры в тени каштана. Они шагнули к ней, лишь Оля стала помогать Антону выбираться из машины."}, {"kind": "paragraph", "text": "— Мы здесь, хозяин! — воскликнули два самурая."}, {"kind": "paragraph", "text": "Оля была сообразительной девушкой с крепкими нервами."}, {"kind": "paragraph", "text": "— Это вы следили за Антоном? — спросила она."}, {"kind": "paragraph", "text": "— Он наш сюзерен! — громко сообщили самураи."}, {"kind": "paragraph", "text": "Таксист с тревожным подозрением рассматривал странную компанию в зеркало обзора."}, {"kind": "paragraph", "text": "— Несите сюзерена в дом! — скомандовала Оля."}, {"kind": "paragraph", "text": "Самураи взяли Антона под руки и понесли в дом. Когда Антона положили на кровать, он на мгновение приоткрыл глаза, расширил их, увидев грозные узкоглазые лица с жуткими бровями, что-то промычал и замер."}, {"kind": "paragraph", "text": "— Где же вы будете жить? — спросила Оля. — Однокомнатная квартира Антона будет маловата для вас."}, {"kind": "paragraph", "text": "— Мы ждём поручение от хозяина!"}, {"kind": "paragraph", "text": "— Какое?"}, {"kind": "paragraph", "text": "— Любое. Мы должны выполнить любое его поручение!"}, {"kind": "paragraph", "text": "— И что он решил?"}, {"kind": "paragraph", "text": "— Хозяин сказал, что даст его сегодня!"}, {"kind": "paragraph", "text": "— Придётся вам подождать до утра. Куда же вас положить…"}, {"kind": "paragraph", "text": "— Мы будем ждать за дверью!"}, {"kind": "paragraph", "text": "Самураи исчезли так быстро, что Оля даже занервничала. Ночь она провела постоянно вздрагивая. Рядом храпел и постанывал Антон."}, {"kind": "paragraph", "text": "Утром, только Антон добрался до холодильника и налил сок, в доме появились самураи. Оля слышала из комнаты, как они напугали Антона."}, {"kind": "paragraph", "text": "— Доброе утро, хозяин!"}, {"kind": "paragraph", "text": "— А, е… О господи! Это вы… Я что-то должен вам?"}, {"kind": "paragraph", "text": "— Мы должны исполнить любое ваше поручение!"}, {"kind": "paragraph", "text": "— У меня нет никаких поручений, можете отдыхать. Давайте я запишу ваши телефоны и позвоню на днях."}, {"kind": "paragraph", "text": "— Мы должны исполнить любое ваше поручение!"}, {"kind": "paragraph", "text": "— Э… это что ж с вами делать-то? — мучился Антон. — У меня всё есть, мне ничего не надо…"}, {"kind": "paragraph", "text": "— Мы должны выполнить любое ваше поручение! — рявкнули самураи."}, {"kind": "paragraph", "text": "— Ой, голова… Ладно, я сейчас что-нибудь придумаю."}, {"kind": "paragraph", "text": "Антон заглянул в комнату."}, {"kind": "paragraph", "text": "— Оль, тебе чего-нибудь надо?"}, {"kind": "paragraph", "text": "Оля спряталась под одеяло."}, {"kind": "paragraph", "text": "— Понятно, — пробормотал Антон."}, {"kind": "paragraph", "text": "Он опять открыл холодильник, чего-то налил. «Вискарь хлещет», — догадалась Оля."}, {"kind": "paragraph", "text": "— Ну что же, друзья, — оживился Антон. — Я вам вот что могу предложить. Поезжайте на родину, в Японию, и привезите мне оттуда настоящий самурайский меч."}, {"kind": "paragraph", "text": "Самураи молча поклонились и исчезли."}, {"kind": "paragraph", "text": "— Буду их коллекционировать, — сказал Антон уже Оле, залезая в постель."}, {"kind": "paragraph", "text": "Через несколько дней Антон не то чтобы забыл о самураях. Просто произошедшее настолько не вписывалось в реальность, что могло казаться только сном."}, {"kind": "paragraph", "text": "Ещё через неделю Антон, возвращаясь от Оли, в окнах своей квартиры увидел свет и удивился. Он точно знал, что не оставлял его включённым."}, {"kind": "paragraph", "text": "На кухне сидели самураи и играли в карты, на которых вместо привычных мастей были яркие изображения растений и животных. Увидев Антона, самураи встали, молча поклонились и протянули ему то, о чём он просил. Не успел Антон даже подумать, что делать с мечом, как один из самураев сурово произнёс:"}, {"kind": "paragraph", "text": "— Наш господин был дальновиден: мы прибыли в тот день, когда этот меч готовились отправить вам. Ваш покровитель совершил сэппуку. Теперь и вам надлежит свершить то же."}, {"kind": "paragraph", "text": "— Что?! Я не хочу никакой сэппуки, — испуганно произнёс Антон."}, {"kind": "paragraph", "text": "— Мы поможем, хозяин! — пообещали самураи. — Ватанабэ-но Цуна говорил своему вассалу Урабэ-но Суэтакэ: «Сердце воина должно быть подобно сердцу труса». Это значит, что самурай обязан каждый день быть готовым к концу."}, {"kind": "paragraph", "text": "— К какому концу?"}, {"kind": "paragraph", "text": "— К смерти!"}, {"kind": "paragraph", "text": "Антон побледнел."}, {"kind": "paragraph", "text": "Звонок застал Олю за туалетом, она готовилась ко сну."}, {"kind": "paragraph", "text": "— Оля! Оля! Они вернулись! — кричал в трубку Антон."}, {"kind": "paragraph", "text": "— Кто вернулись?"}, {"kind": "paragraph", "text": "— Самураи! Они выполнили моё поручение!"}, {"kind": "paragraph", "text": "— Ну и молодцы, с почином тебя. А чего ты так нервничаешь?"}, {"kind": "paragraph", "text": "— Теперь они хотят моего конца!"}, {"kind": "paragraph", "text": "— Что они хотят? — спросила Оля."}, {"kind": "paragraph", "text": "— Чтобы я совершил сэппуку."}, {"kind": "paragraph", "text": "— Что ещё за гадость?"}, {"kind": "paragraph", "text": "— Это значит вспороть себе живот!"}, {"kind": "paragraph", "text": "— Какой ужас! Гони их прочь, ты же их сюзерен!"}, {"kind": "paragraph", "text": "— Они говорят, что, так как я их сюзерен, они обязаны мне помочь, если я по каким-то причинам этого сделать не смогу."}, {"kind": "paragraph", "text": "— Что это значит?"}, {"kind": "paragraph", "text": "— Они помогут мне вспороть живот! Вот что это значит!"}, {"kind": "paragraph", "text": "— Тогда вызывай полицию."}, {"kind": "paragraph", "text": "— И что я скажу?"}, {"kind": "paragraph", "text": "— Что тебя хотят убить."}, {"kind": "paragraph", "text": "— Может, для начала ты приедешь и поговоришь с ними?"}, {"kind": "paragraph", "text": "— Думаешь, это поможет? А что я им скажу?"}, {"kind": "paragraph", "text": "— Давай попробуем. Скажешь, что здесь так нельзя, что это глупо, что придётся обратиться кое-куда."}, {"kind": "paragraph", "text": "— Хорошо, завтра вечером. Твои самураи не спешат тебя отправить на тот свет?"}, {"kind": "paragraph", "text": "— Да вроде нет. Они принесли несколько книг и говорят, что я должен их обязательно прочесть."}, {"kind": "paragraph", "text": "Оля не отнеслась всерьёз к разговору. Она воспринимала эту историю с самураями как оригинальную, но не совсем удачную театральную постановку, которая скоро должна закончиться."}, {"kind": "paragraph", "text": "Придя на следующий день, Оля открыла дверь своим ключом и застала Антона читающим книгу, рядом на пакете из Дома книги лежал кодекс Бусидо. Антон читал негромко вслух, словно боясь потерять хоть слово:"}, {"kind": "paragraph", "text": "— «Само собой разумеется, что самурай обязан хорошо владеть искусством мато, касагакэ и инуумоно…» О как!"}, {"kind": "paragraph", "text": "— Что у нас ещё страшного произошло? — обратилась Оля, видя, что её появление не замечено. — Как живёте, как животик?"}, {"kind": "paragraph", "text": "— Привет. Всё хорошо, — улыбнулся Антон."}, {"kind": "paragraph", "text": "— А сапуки?"}, {"kind": "paragraph", "text": "— Сэппуку. Это, как выяснилось, не такая уж страшная вещь."}, {"kind": "paragraph", "text": "— То есть вспарывать живот — это не страшно?"}, {"kind": "paragraph", "text": "— Совсем не страшно."}, {"kind": "paragraph", "text": "— Слушай, Антон, может, теперь ты расскажешь, что значит эта история с самураями? Чья это затея?"}, {"kind": "paragraph", "text": "— Мне очень повезло, — подмигнул ей Антон, — меня позвали."}, {"kind": "paragraph", "text": "— Куда тебя позвали?"}, {"kind": "paragraph", "text": "— Туда, где мы с тобой встретимся как равные."}, {"kind": "paragraph", "text": "— Антошка, тебя что, самураи на наркотики подсадили? Где встретимся, как какие равные? В клубе транссексуалов, что ли?"}, {"kind": "paragraph", "text": "— Оль, ну что за глупости!"}, {"kind": "paragraph", "text": "— Ты ещё скажи, что я дура! — вспылила Оля. — Вы тут меня разыгрываете неизвестно с кем, а я ведусь на ваши глупости! В самураев они играют!"}, {"kind": "paragraph", "text": "Оля обиделась и ушла, хлопнув дверью. Она пришла через день взять розовую кофточку, чтобы пойти на день рождения к подруге. В доме было неестественно чисто и прибрано, розовая кофточка, аккуратно сложенная, лежала на видном месте, а на ней — бумажный журавлик. Антона не было, да и вообще ничто в доме не напоминало о нём, как будто он здесь никогда и не жил. Только на кухне стояла миска с рисом и воткнутыми вертикально палочками. И ещё любимая красная тарелка Антона лежала, перевёрнутая, чуть в стороне, а поверх неё — большой зеленоватый ломоть камамбера."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
8	mrd6-potok	Поток	46	mrd6/mrd6-potok.png	data:image/jpeg;base64,	Предупреждали вещатели: от Солнца отвалился кусок и устремился к Земле. Придумали странные люди из телевизора магнитные бури и аномалии. Напугали легковерных. И забронировали место под солнцем — так, на всякий случай. Со	[{"kind": "image", "path": "mrd6/mrd6-potok.png", "caption": "Иллюстрация Маргариты Царевой при помощи Midjourney"}, {"kind": "paragraph", "text": "Предупреждали вещатели: от Солнца отвалился кусок и устремился к Земле. Придумали странные люди из телевизора магнитные бури и аномалии. Напугали легковерных. И забронировали место под солнцем — так, на всякий случай. Соломку подстелили."}, {"kind": "paragraph", "text": "Что нам до бабьих сказок? Пошли они все к колдуну Иванову. Тот хоть и врал, но врал порядочно — без подтекста. Честно врал. Не корысти одной ради. Всё какие-то запотевшие лампы за окном разглядывал и транслировал прогнозы на всю Россию. И попадал в точку, а не пальцем в небо, как современные вещатели погоды. Выбритые до блеска, с прямой спиной."}, {"kind": "paragraph", "text": "Колдуну верил, им — нет. Что может сделаться мертвецу?"}, {"kind": "paragraph", "text": "Прогнозируют вспышку насилия — о, над этим можно подумать. Зачем?"}, {"kind": "paragraph", "text": "И почему главный у них удивительно похож на серого кардинала, под мантией которого выпирают звёзды чином не меньше майора?"}, {"kind": "paragraph", "text": "«Ожидаются солнечные бури, жара, которой не было больше ста лет. Не только метеозависимые — практически все почувствуют недомогание. Возможны обмороки, беспричинная агрессия. В городе увеличится количество суицидов и преступлений психогенного характера» — вывеска на учёном сайте, где любое утверждение кажется смешным. Утверждение случайно угаданных обстоятельств. Оксюморон. Пальцем в небо — о небе. Смешно."}, {"kind": "paragraph", "text": "И что же это такое — «психогенный характер»? Я знаю: это соломка, которую подстилает товарищ майор."}, {"kind": "paragraph", "text": "Мне не страшно — я в аду и без инфернальных басен из центра."}, {"kind": "paragraph", "text": "С весны прошлого года работаю в ритуальном цехе «Поток». Я в потоке, вижу соратников по цеху и тех, кто скоро будет внутри потока, а там окажемся все. Потому что все мы обречены на поток. Это не пальцем в небо, и это не смешно."}, {"kind": "paragraph", "text": "Режу буквы на камне (как заповедал Бог — «в поте лица своего»), высекаю надгробные надписи, точками расписываю гранит. И пью. Пью много — потому что не пить в потоке нельзя. Многолико и быстро истечение в вечность. Не родник, а фонтан. Точнее — поток. Не успеваем остановить конвейер. Не боги мы. Всего лишь проводники усопших. А их — последнее время — так много, что от одного этого хочется выпить. Не то с горя, не то с радости. Для гравёра «Потока» чужая смерть — не горе, а заработок. А он дополнительным не бывает — его всегда мало, даже когда покойников много. Очень много. И не поймёшь: с радости иногда запиваешь или с горя. Ответ очевиден: не с радости и не с горя, а с тяжёлой работы, на которой невозможно не пить."}, {"kind": "paragraph", "text": "Мы сами немного похожи на покойников: лица серые от постоянной выпивки, пыльные от мраморной крошки, дубильные от солнечного загара и грязи."}, {"kind": "paragraph", "text": "Работы много, бригадир выходных не даёт. И вроде как бьётся за трезвость, но пить позволяет — лишь бы не на глазах, не публично то есть, а тайно. Потому что невозможно по десять часов в день рубить одни и те же буковки и не сойти от однообразия и жары с ума. А когда сходишь с ума, рука может дрогнуть — и вместо буквы «О» получится буква «Ё». Брак в работе, в которой брак невозможен. Буквы из памяти не сотрёшь, а входить в вечность с браком не позволяют корпоративная честь и хороший заработок. А ещё архангел, который стоит на пороге вечности: в потоке не может быть ошибок. Брачного змия не пропустит."}, {"kind": "paragraph", "text": "Бригадир делает вид, что не замечает водки. Готов простить тайно сброшенные в речку расколотые от неосторожных ударов мраморные заготовки плит. Кладбище разбитых памятников — на дне водоёма, подальше от посторонних глаз. Представляю себе шок и трепет какого-нибудь заблудившегося водолаза или полицейского-подводника, который ныряет в поисках тела, а находит целое кладбище. Заранее скорблю о его душевном здоровье."}, {"kind": "paragraph", "text": "Мой памятник на дне водоёма тоже есть, не исключение."}, {"kind": "paragraph", "text": "Испортил надпись: «Любим. Помним. Скорбим». Резец слетел с насечки и съехал в кювет. То был день моей последней целомудренной трезвости. После него я начал пить вместе со всеми — влился в коллектив. Старый гравёр Игнат обучал меня искусству рубки буквы «О» и помог расправиться с загубленным памятником. Мне стали сниться кошмары — в них я до тошноты высекал буквы, одни и те же. Мой резец срывал гладкие покровы плиты и углублялся в вечность, путались потусторонние нейронные связи, я вскакивал в холодном поту с постели и тянулся к бутылке. Мужики понимающе кивали — они прошли эту гравёрную инициацию. Если поток вошёл в сон — значит, ты настоящий гравёр «Потока». До этих пор ты лишь ученик."}, {"kind": "paragraph", "text": "«Не начинайте работать, пока не примете первый стакан», — заповедь от мастера Игната."}, {"kind": "paragraph", "text": "В августе я нарушил эту заповедь и поранил палец: резец соскользнул и ударил болезненно, кровь хлынула в лунки «Любим. Помним. Скорбим». Лёва, работавший рядом, протянул мне бинт, вату и водку и предложил передохнуть на крыше цеха. Крыша раскалялась, как сковородка в аду, но у нас не было другого места для отдыха. Потому что бригадир Корней мог не заметить водку и расколотую плиту, но всегда видел, когда гравёр отдыхает. Этого он вынести не мог."}, {"kind": "paragraph", "text": "Лёва — мой приятель: высокий, худой и манерный не по стати. Матом не ругается, носит рыжую бородку, как у дьякона, длинные волосы, пьёт много и не пьянеет. В его крови течёт какое-то армянское высокородие. Учился в университете на химика, бросил, взялся зарабатывать деньги. Говорит, что химия дала ему знания о том, что всё есть поток. Из праха берётся, в прах возвращается. Мудрец."}, {"kind": "paragraph", "text": "Крыша — единственное место в цеху, где можно укрыться от бригадира. Мы называем час на крыше адмиральским, а два часа — поездкой в Сочи. Тела дымятся от металлического настила, а мы коптимся от водки и усталости."}, {"kind": "paragraph", "text": "Собственно, в потоке я понял, что водка может спасать и от жары. Стакан тут же выходит через потовые поры, стекает потоком — и становится легче. Это как горячий чай в южных широтах. Только у нас вместо чая — водка. Заметьте: не вино и не пиво, а водка — чистый продукт. Вино и пиво в потоке не спасают, дают временное облегчение, по утрам превращая в «трясунов». А у нас хирургия: руки должны прочно держать молоток или кувалду и бить по скарпелю снайперски. Промахнёшься — получишь отдачу двойную: ужалишь палец до синевы, раскроишь плиту."}, {"kind": "paragraph", "text": "— Что думаешь делать сегодня? — спросил Лев. — Хочешь, я тебя с подругой Маринки познакомлю?"}, {"kind": "paragraph", "text": "— У меня есть женщина, Лёвка. Она холодная, как могильная плита, и ждёт меня по ночам трезвым. А я прихожу пьяный, полоумный и горячий, как крыша. Она боится меня, потому что я не могу спать. Руки рубят буквы, а поток сносит крышу. Но Вика терпит меня. За деньги, которые мы тут зарабатываем. Вика считает, что когда-нибудь люди перестанут умирать бешеным потоком и нам дадут отпуск."}, {"kind": "paragraph", "text": "— Наивная. Моя женщина знает, что поток не остановить. Поэтому мы спим в разных комнатах. Маринка ходит в церковь и молится. Думает, что Бог слышит её молитвы. Она смирилась. Говорит, что через год мы сможем открыть своё дело."}, {"kind": "paragraph", "text": "— Какое?"}, {"kind": "paragraph", "text": "— Цех ритуальных услуг."}, {"kind": "paragraph", "text": "Я рассмеялся, отхлебнул из горлышка и потянулся за бутербродом."}, {"kind": "paragraph", "text": "— Жара, Лёва, ты сходишь с ума. Какое новое дело в потоке? Ты царь Соломон?"}, {"kind": "paragraph", "text": "— Мы с Маринкой открыли новый состав для памятников. Лёгкий, пластичный, на века. Она же у меня на химфаке училась. Я тоже."}, {"kind": "paragraph", "text": "— Хочешь делать памятники из пластика? Заказчики не поймут. Покойникам похер, а живые тебя не поймут. Память должна быть из камня. А у тебя нет денег на покупку резаков и шлифовальных машин. Ты останешься тут, Лёв, и мы будем пресмыкаться перед Корнеем, а жена твоя продолжит ходить в церковь и думать, что её слышит Бог. И я тоже останусь в потоке, хотя и мечтаю совсем о другом."}, {"kind": "paragraph", "text": "— Может быть, ты прав, а может, и нет. Время покажет."}, {"kind": "paragraph", "text": "— Людей умирать меньше не будет — это факт. Без работы не останемся — тоже факт. Надо только пережить этот месяц. Чтобы не оказаться внутри потока. Если я там окажусь, заранее прошу тебя, друг, не высекать банальности: «Любим. Помним. Скорбим». А что-нибудь с юмором, типа: «Он шёл по жизни, чуть шатаясь». И, ради Бога, не делай пошлую розочку под надписью."}, {"kind": "paragraph", "text": "— Не буду, — лениво ответил приятель. — На том свете точно нет ритуальных мастерских?"}, {"kind": "paragraph", "text": "— Нет, Лёва, там этим занимаются черти."}, {"kind": "paragraph", "text": "— Так о чём ты мечтаешь?"}, {"kind": "paragraph", "text": "— Две мечты у меня, и они друг с другом борются. Хочу в деньгах не потерять — и чтобы людей умирало поменьше. Взаимоисключающие вещи. Как считаешь?"}, {"kind": "paragraph", "text": "— Так глубоко не копаю. Я химик. Из праха взят — в прах вернёшься. Хорошо быть химиком и верить в Бога. Маринка верит в Бога и в химию. Я — только в химию. У нас гармония."}, {"kind": "paragraph", "text": "Август аномальной жары, без дождей."}, {"kind": "paragraph", "text": "Город плавится под солнцем."}, {"kind": "paragraph", "text": "У нас нет выходных."}, {"kind": "paragraph", "text": "По субботам и воскресеньям наблюдаем с крыши стайки тёмных старух, которые направляются в церковь вымаливать небесную влагу, но Бог почему-то не слышит молитв. Или слышит, но проверяет на преданность — как многострадального Иова. Бабушки в чёрных платках — святые. Дорога до храма — испытание, а ещё выстоять внутри под гласы священника — это подвиг. Меня в храме хватает на пять минут: выскакиваю оттуда пулей. Хоть и работаю с вечностью — наедине с ней могу в тишине выдержать не больше минуты. Минуты молчания. Потом начинаю суетиться и убегать в спасительный шум и работу. Неужели на том свете не будет работы? С ума можно сойти!"}, {"kind": "paragraph", "text": "Мы лежим с Лёвой на раскалённой крыше и смотрим на стайку старух. Корней приедет вечером. А ближе к ночи мы пойдём с Лёвой в бухгалтерию ругаться: каждую неделю нас стараются обмануть. Выбиваем по тысяче знаков, приходим с бумажками, где всё подсчитано и расписано, а бухгалтерша Машка делает круглые глаза и утверждает, что у неё в табеле не тысяча знаков, а восемьсот и что заплатит она нам только за то, что Корней утвердил в табеле. Бригадир и любовница Машка получают от заказчиков за каждый выбитый знак по сотне, а нам достаётся по четвертаку — «чистая бухгалтерия». Наверное, поэтому Лев хочет открыть своё дело."}, {"kind": "paragraph", "text": "— Святые старушки. Идут по жаре в храм. Выпрашивают дождь. Мне кажется, они не тому Богу молятся. Или не так молятся. Я не силён в богословии, но слышал, что у нас Бог — это любовь. А зачем у любви что-то выпрашивать? Она всё даёт сама."}, {"kind": "paragraph", "text": "— Моя Маринка тоже верит, что Бог её слышит."}, {"kind": "paragraph", "text": "— Нужен дождь, Лёва, иначе мы друг друга перебьём памятниками. С ума сойдём. Представляешь комедию? Гравёры «Потока» перебили друг друга памятниками."}, {"kind": "paragraph", "text": "— Ты сколько уже работаешь?"}, {"kind": "paragraph", "text": "— С прошлой весны."}, {"kind": "paragraph", "text": "— Дождик пойдёт, когда Лёха Лягушатник из соседнего дома начнёт надувать через соломинки лягушек и швырять их под колёса машин. Не видал?"}, {"kind": "paragraph", "text": "— Нет. Кто это?"}, {"kind": "paragraph", "text": "— Дурачок местный по прозвищу Леший. Когда старухи проходят мимо его дома в церковь, он будто просыпается. И совершает свои обряды. Безобидные, на первый взгляд. Соседи его в психушку сдают регулярно, а он людей любит. В прошлом году было такое же лето. Лёха набрал на болоте лягушек, надул их через соломинку и пошёл швырять под машины. А утром рванул дождь."}, {"kind": "paragraph", "text": "— Вот чертило! Неужели правда? Чокнутого лягушатника Бог услышал, а наших праведных бабушек — нет?"}, {"kind": "paragraph", "text": "— А кто тебе сказал, что бабушки праведнее Лешего?"}, {"kind": "paragraph", "text": "— Ладно, дружище, нам нужно тоже начать колдовать, иначе от жары загнёмся."}, {"kind": "paragraph", "text": "— Мы и без того каждый день колдуем. Долбим резцами по камню, считаем знаки — и уже наплевать на слова. А слова хорошие. Нас с тобой, Серый, только черти услышат."}, {"kind": "paragraph", "text": "— Так я с ними каждую ночь разговариваю."}, {"kind": "paragraph", "text": "— Это пройдёт. Поработаешь ещё годика три — тебе на всё совсем наплевать будет. И на чертей тоже. Спать станешь как младенец, без снов. Ночью — соска с водкой, утром — соска с водкой, днём — работа с водкой. Скоро трезветь будешь от водки, а пьянеть от трезвости. Признак мастерства. Игнат такой. В трезвости никогда не подойдёт к камню: знает, что скарпель влево или вправо уйдёт."}, {"kind": "paragraph", "text": "— Пошли в поток. А то Корней явится. У него же чутьё на крышу. На раскалённую крышу цеха. У нас всё наоборот: наверху ад, внизу рай. Хоть какая-то прохлада."}, {"kind": "paragraph", "text": "Мы с Лёвой спустились вниз осторожнее, чем забирались. И как будто трезвее. Отдохнули славно — теперь можно за дело. Скарпель лежит в мраморной пыли на плитке, на которой выкошены: «Любим. Помним. Ско…». Взял инструмент, добил в два счёта, записал в бумажку ещё 23 знака. Точки и кавычки идут в заработок. А Корней с Машкой у нас эти знаки воруют. Нехорошо зарабатывать деньги на горе людей и ещё своих обворовывать. Но мы с Лёвой люди принципов. Что положено — отдай. Не богохульствуй. Конечно, спрашивать долги с Корнея — это всё равно что биться головой о каменное надгробье: услышишь в ответ лишь хруст собственной лобной доли. Сотрясением отделаешься, если уж больно упрямо начнёшь долбить. Но мы с Лёвой люди принципов."}, {"kind": "paragraph", "text": "Жара ушла к вечеру, засвистели какие-то пташки ночные. В воздухе разлилась нега. Ночной город обожаю. Идёшь по проспекту пешком, ноги и руки такую силу чувствуют, что, кажется, взял бы и землю свернул, как Архимед. Дайте мне только точку опоры. И никакого похмелья — потому что в крови ещё гуляет водка с раскалённой крыши, бродит по телу, как брага в самогонном аппарате. И хорошо на душе, радостно — как у молитвенных бабушек, если молебен принёс дождь. Нет дождя — вечерами земля отдыхает. Остывает ненадолго. Наверное, и крыша приятно прохладная — после двадцати одного не был."}, {"kind": "paragraph", "text": "У Машки в конторе свечение, как у монашки в келье. Сидит, красавица, над бухгалтерскими премудростями, колдует. Машка — тёмная худая девица, похожая на актрису из сериала про цыган. Глаза огромные, влажные и ласкающие, но последнее предназначено женатому Корнею. И что она в нём нашла? Пузо навыпуск, плечи как церковный колокол — не обхватишь, — рыжие усы подковкой и наглый взгляд. Ни дать ни взять — ростовщик с большой дороги. В прошлом боцман, в девяностые сошёл на берег с тремя контейнерами импортных шмоток, продал их, прикупил оборудования, договорился с бандитами, сделал кому надо несколько бесплатных захоронений — и вот он, почти царь иудейский. Командир похоронной армии."}, {"kind": "paragraph", "text": "— Привет, Масяня. Как дела?"}, {"kind": "paragraph", "text": "Красавица принимает наши бумажки и быстро переносит циферки в табель — так быстро, чтобы мы не заметили синевы под её левым глазом."}, {"kind": "paragraph", "text": "— Корней? — спрашивает Лёва."}, {"kind": "paragraph", "text": "— Жена его приезжала. Скандал устроила. Доработаю лето — уйду в школу. Детей учить снова буду. Надоело всё."}, {"kind": "paragraph", "text": "— По какому предмету училка? — интересуюсь."}, {"kind": "paragraph", "text": "— По математике."}, {"kind": "paragraph", "text": "— Тогда понятно, почему бухгалтер. Сегодня все наши знаки оплатишь? Не как обычно?"}, {"kind": "paragraph", "text": "— Сегодня всё оплачу. Надоело. Бухгалтерия надоела, жена Корнея — всё надоело. Кондиционер не может купить, бизнесмен хренов! Боцманом был — боцманом остался. Широты в нём много, глубины нет. Злые все."}, {"kind": "paragraph", "text": "— Потерпи, Масяня, жара схлынет — люди снова добрыми станут. Магнитные бури, слыхала? Ожидается всплеск насилия. Ты это, кажется, уже на своей шкурке почувствовала. Потерпи немного — Леший надует своих лягушек через задницу, и хлынет дождь."}, {"kind": "paragraph", "text": "— У нас всё через одно место, — смеётся Масяня."}, {"kind": "paragraph", "text": "— Ты смеёшься, красавица, — значит, не всё потеряно. Смех сквозь слёзы — это к дождю. Не унывай. Корней — сволочь, но он нам работу даёт."}, {"kind": "paragraph", "text": "— Ладно, мальчики, идите отдыхать. За мной заедут. А вас дома жёны ждут."}, {"kind": "paragraph", "text": "Побрели устало в раздевалку, по пути пересчитывая наличный заработок. И улыбались — широко и нагло. Давно так не улыбались."}, {"kind": "paragraph", "text": "Синева под глазом Масяни помогла получить честно заработанное. Несправедливость в одном отыгралась на правде в другом. В Машке вдруг проснулась училка: честное, светлое, униженное и оскорблённое существо — персонаж Достоевского. А всего-то нужно было приложить к нежному глазу красавицы кулак разгневанной законной супруги Корнея."}, {"kind": "paragraph", "text": "Почему так? Чтобы добиться правды, необходимо кого-то побить. Есть что-то ненастоящее в этой формуле. Несвободное. Какая-то праведность поневоле."}, {"kind": "paragraph", "text": "А завтра? Что будет завтра с Машенькой, когда обида на жену боцмана рассеется в обильных подарках бригадира? Снова проснётся бестия и урежет с нас часть заработка в пользу начальства? Так оно и будет. На том и держится поток."}, {"kind": "paragraph", "text": "Зачем очищать его искусственными наслоениями — шлюзами, порогами, фильтрами? В мутном потоке не видно подводное кладбище. Никто не придёт и не спросит. А Корней станет богаче и наглее. Жизнь — это и есть мутный поток. Слабые ручейки родниковых источников разбавляют тёмные воды, но не очищают. А кто они, эти слабые ручейки? Святые старушки, вымаливающие дождя, и Леший, надувающий лягушек через задницу — ради любви к человечеству. Только не мы с Лёвой."}, {"kind": "paragraph", "text": "В раздевалке собрали остатки недопитой водки, переоделись, сели за стол и выпили. Потом покурили и тронулись в путь. Я — в стареньких джинсах и футболке с надписью «Ч». Что означает, не знаю. Мне наплевать, лишь бы удобно было. А Лев надел белую рубашку и чёрные штаны — не даёт гравёру покоя высокородная армянская кровь. Что ж, его дело. Я проще. Неважно, как и во что одет, главное — сколько наличности в карманах."}, {"kind": "paragraph", "text": "Наш заработок — через «конверт». Боцман не для того бесплатные захоронения у высших устраивает, чтобы налоги платить. Корней — жук. Его бизнес подразумевает умение ладить с живыми, чтобы не обижать покойников. На том свете налоговой нет. А ритуальный цех — блокпост на границе с вечностью. Кто же решится его проверять из земных, если впереди небо? А у неба границ нет — там всё общее."}, {"kind": "paragraph", "text": "Кто возвращался домой после адского рабочего дня, тот понимает, что есть рай на земле. Говорить ни о чём не хочется, мышцы гудят, как высоковольтные провода, тело — в невесомости. Тронь нас — выскочит разряд молнии и сразит наповал. Мы идём спокойно и радостно, но наши лица как бы говорят окружающим: не прикасайтесь, высокое напряжение, убьёт. Не хватает лишь черепа с костями. Может быть, моя буква «Ч» на футболке — об этом?"}, {"kind": "paragraph", "text": "В воздухе разливается нега. Встречаются прохожие: гуляют влюблённые парочки, резвятся подростки, город пробуждается от жары. И когда люди спят? Ещё больше интересно — когда они работают? Иногда кажется, что в нашем городе летом люди вообще не работают, а только отдыхают."}, {"kind": "paragraph", "text": "Я хорошо отличаю лица живых от мёртвых. Вторые — в потоке, в котором мы с Лёвой проводники. «Живые» — лица чужие, не свои, они как будто только что из эдемского сада: веселятся, как ангелы, удивляются жизни, как дети, в них неистребимая жажда жить. Свои — лица из потока: серые, с погасшими глазами, усталые и разочарованные, циничные, непотребные, словно вырезанные из камня. Трезвые в опьянении и пьяные в трезвости. Наши лица. Свои."}, {"kind": "paragraph", "text": "Те, другие, — как апостолы в Пятидесятницу, когда на них снизошёл дух святой и они показались мёртвым «пьяными», — такой эффект зазеркалья."}, {"kind": "paragraph", "text": "Мне тоже иногда кажется: человек в радости — это ненормальный человек. Разве можно сегодня быть в радости? Радуются и веселятся сегодня святые — люди, не утратившие способность радоваться. О Господи, как я завидую этим детям Божьим! Хорошей завистью. Белой."}, {"kind": "paragraph", "text": "Недалеко от светлого сверкающего пятачка гостиницы — развилка. Лев идёт направо, я — налево. Мне добираться до Балтийского района, Лёва живёт в центре."}, {"kind": "paragraph", "text": "— До завтра, — протягивает руку приятель и смеётся. — Смотри, не сверни куда-нибудь. Тебя ждёт женщина — холодная, как пиво, и крепкая, как вино."}, {"kind": "paragraph", "text": "— Не сверну. Надеюсь, что завтра Леший надует своих лягушек. И хлынет дождь. Мозги плавятся."}, {"kind": "paragraph", "text": "Иду мимо церкви. Возле кованой изгороди курит охранник. Я его знаю: Костя с Ленинского, инвалид войны. У него время от времени мина в голове начинает тикать часовым механизмом — он становится замкнутым и неразговорчивым, берёт отгулы и ложится в стационар. Потом настоятель его снова принимает сторожем. Жалеет. Костю многие знают в городе: он свой повсюду. Не живой и не мёртвый — особенный какой-то. Дурачок. Типа Лешего. Такие — неопределимы. Они ближе к живым, чужим то есть, но одновременно в них много «своей» мёртвости."}, {"kind": "paragraph", "text": "Получил ранение в голову и контузию ещё во время Первой Чеченской. Прозвище у Кости — остаточный позывной: Череп. Теперь он вполне олицетворяет название: лысина с трагическим проёмом отливает синевой лунного света, борода сползает на грудь. Здороваюсь."}, {"kind": "paragraph", "text": "— Отработал? Замолвил бы за меня словечко перед своим боссом — я бы научился. На рынок звали в мясной отдел, отец Евгений не пускает. Говорит, что в мясном цехе мне нельзя: крови много, суеты, людей. Крыша поедет. А у вас как? Ничего?"}, {"kind": "paragraph", "text": "— У нас? — Смеюсь. — Крыша давно едет. Ты у отца Евгения спроси. Но, скорее всего, к нам он тебя не благословит. У нас без водки нельзя, а тебе нельзя с водкой."}, {"kind": "paragraph", "text": "— Почему без водки нельзя?"}, {"kind": "paragraph", "text": "— Без водки с ума сойдёшь быстрее. Нашему боссу нужен поток, понимаешь? А трезвый в потоке не может. Ему отдохнуть иногда хочется, и брак от усталости больше. Поток сам себя организовал. Невозможно быть трезвым в потоке. Теперь понял?"}, {"kind": "paragraph", "text": "— Теперь понял. Не дурак. Но ты всё-таки поимей в виду. Может быть, уволится кто, работник потребуется — словечко замолви. Тягостно тут в церкви. От безделья тягостно. Хоть бы враг какой пошёл. Я б его… я б его… — И по сторонам озирается, будто потерянный автомат ищет. — Я б его, блядь, сапёрной лопаткой в голову. Он мне в пяту как змий, а я его в голову. Один удар сапёрной лопаткой — и нет головы. Он мне в пяту, а я в голову, понимаешь, Серый? Змий мне в пяту, а я его…"}, {"kind": "paragraph", "text": "Заклинило Черепа на сапёрной лопатке и змии. Бывает."}, {"kind": "paragraph", "text": "— О, это я понимаю, Костя. А если он тебя в голову? Ты его в пяту?"}, {"kind": "paragraph", "text": "— Что? — Череп выходит из самогипноза. — Об этом я не подумал. — Качает головой в недоумении. — Спасибо, что подсказал. Теперь думать буду. Если он меня в голову… Эх, йофама, надо к отцу Евгению подойти и спросить. Что делать, если враг в голову, а не в пяту? Знаю, что скажет. У нас враг невидимый — духи злобы поднебесной. Так и говорит иногда в церкви на проповеди: у нас, говорит, у православных, главный враг — это мы сами. В нас самих сидит дух злобы поднебесной. С ним и надо воевать. Как это, Серый? Я сам себя должен в голову, что ли? Долбить? Эх, йофама…"}, {"kind": "paragraph", "text": "Сторож отшвырнул от себя окурок, как бикфордов шнур, заходил взад-вперёд в задумчивости, а я отправился дальше — в сторону огней проспекта и гостиничной суеты. На пятачок, где таксисты ждут клиентов, где бродят ночные граждане без «церковных затей» и заморочек, где много разных ручейков стекаются в единый ночной городской поток, в котором всем хорошо — особенно летом, в жаркие ночи. Как в Сочи."}, {"kind": "paragraph", "text": "Бабушки (не святые) торгуют цветами с дач, а под полами балахонов держат ключи от квартир — на ночь, за деньги и бутылки своей наливной. Знаю: делают это не корысти ради, как колдун Иванов. Бабушки — люди старой закалки. Они почти все — в потоке. Ждут лишь гласа, вопиющего с неба, готовятся заранее, без ропота, и копят деньги на похороны."}, {"kind": "paragraph", "text": "А ещё — скажу по секрету (узнал как-то от Кости): бабушки эти, не святые, собирают копеечку на вставные челюсти. Да, не вру. Хотят выглядеть в гробах невестами Христовыми, просят внуков обязательно надеть перед погребениями новые зубы и косы, хранимые с юности, сунуть под подушки в гробы. Когда явятся красавицами перед Христом, он и простит их — как дев евангельских, которые с сосудами масла и огоньками светильников вышли встречать Жениха. Не вру. Мне об этом церковный сторож рассказывал. А Череп не врёт. Не умеет."}, {"kind": "paragraph", "text": "Вдоль широкого мощёного тротуара растут липы. Время уже к полуночи, засиделись мы с Лёвой за остатками трапезы цеховой. Надо такси брать — и домой к Вике. Заждалась, красавица. Не то чтобы только меня, но меня с наличностью, которой сегодня чуть больше, чем всегда. Вот что может с человеком сделать синева под глазом. Думаю, наверное, поступок Машки сравним с надуванием лягушек Лешего — поступок святой. Потому как в один момент ветхая (в смысле — мёртвая) Масяня преобразовалась в раскаявшуюся грешницу: в училку без выкрутасов, в Марию Магдалину, в девушку, воскресшую из погребённых романов Фёдора Михайловича. Случилось чудо, надо признать. Завтра пойдёт дождь. Если не пойдёт — стану циничным и въедливым, как Фома неверующий."}, {"kind": "paragraph", "text": "Иду в сторону лип, под которыми что-то происходит. Возня какая-то, шум, плач едва ли не детский. Что-то там происходит нехорошее, я примерно предполагаю что. И обычно в чужие мутные ручейки не забираюсь, тем более не ныряю с головой — своего потока мутного хватает. Но тут что-то внутри меня ёрзает, покоя не даёт. Видно, проснулся внутри какой-то дух, который вышел на поле борьбы Бога и дьявола, за сердце схватил. А внутренний голос шепчет: «Пойди и дай кому-нибудь в морду, если увидишь несправедливость. Сотвори подвиг — такой же высокий, как сегодня Машка сотворила. И ещё не успел Лягушатник, которому воздастся от людей за любовь к людям: побьют Лешего за лягушек, а он просто преисполнился всеобщей любви. Пойди и дай скверному человеку в морду, душу отведи и разряд накопленных в жару молний низвергни на землю»."}, {"kind": "paragraph", "text": "Долго не противился внутреннему голосу и пошёл под липы. А там сутенёр издевается над подопечной. В белой рубашке тягает за волосы ночную фею, которой от силы лет восемнадцать. Она тоже вся в белом — в платьице с кружевами, похожем на школьное выпускное. Как видно, в образе работает. Знаю: проститутки тут почти все на веществах сидят, есть и те, кто нехорошими болезнями болеет."}, {"kind": "paragraph", "text": "— Ах ты, шалава! — кричит хозяин девушки. — Гонорар взяла — всё по столице Австрии (вене) пустила. В хламину перед уважаемыми клиентами явилась! А работать? Кто за тебя гостей города обслуживать будет?!"}, {"kind": "paragraph", "text": "И снова — хрясь её по лицу. Не сильно, ладошкой — чтобы товарный вид не испортить, но больно и стыдно. Вижу: плохо совсем девочке. Тошнит её — то ли от передозировки, то ли от болезни. Никакая совсем."}, {"kind": "paragraph", "text": "Я, может быть, в другую минуту не стал вмешиваться и нырять в чужой мутный поток. Но сегодня на моих глазах произошло преображение Машки. И сам я, признаться, истосковался по обычной сваре — чтобы скопившуюся мерзость запустения душевного из себя изгнать. Надо заступиться. Иначе молнии внутренние меня самого испепелят."}, {"kind": "paragraph", "text": "— Земляк, оставь девушку. Не видишь, ей плохо? Какая она жрица любви — ей самой лекарь нужен. Оставь её, зёма. Она тебе здоровая бухгалтерию сделает. А сегодня — оставь."}, {"kind": "paragraph", "text": "Наискосок от меня стоят на тротуаре два парня в камуфляже. Худые, крепкие, прокопчённые. С мёртвыми лицами — своих внутри потока узнаю с первого взгляда. Шевроны чёрные с белыми черепами — вот она, буква «Ч». От них на расстоянии ощущается предупреждение: не встревай — убьём. Это клиенты. Им нужна ночная фея в образе школьницы. У них много денег и совсем нет страха. Наверное, гонорар они дали наперёд, а «школьница» их кинула, уехала с деньгами, промотала. Они вызвонили хозяина — и теперь тот вразумляет под липами «проколовшуюся» девицу."}, {"kind": "paragraph", "text": "— Ты кто? — поворачивается ко мне сутенёр. Лицо тоже мёртвое — в потоке. Вроде не старый, а ведёт себя нагло. Косится на клиентов, подмигивает им. Он не боится меня. В трёх метрах стоят защитники — два камуфляжных бойца. Курят папиросы, от которых идёт кочегарный чад с примесью травки. Глаза сверкают. Кажется, они готовы разрядить свои молнии прямо сейчас под липами."}, {"kind": "paragraph", "text": "Я не унимаюсь. Я уже нырнул в чужой поток. Теперь остаётся либо утонуть, либо выплыть. Третьего не дано. А силы в моём теле по-прежнему кипят — хотят благородного выхлопа."}, {"kind": "paragraph", "text": "«Дайте мне точку опоры, и я переверну землю». Мне точка опоры не нужна. Я уже начал переворачивать землю."}, {"kind": "paragraph", "text": "— Я смерть твоя, вот кто я. Всадник Апокалипсиса. Оставь девицу. А ты, детка, встань и иди. Я разговаривать с твоим псом буду."}, {"kind": "paragraph", "text": "Белое платье девушки неожиданно растворилось в ночи. Ночная фея упорхнула, предчувствуя неладное."}, {"kind": "paragraph", "text": "Рефлекторно я затянул молнию на карманах джинсов, где лежала наличность, и шагнул в сторону наглеца. Схватил его за шиворот белой рубахи. Силы не рассчитал — воротник треснул, сутенёр побледнел, стал звать на помощь. Но я не дал ему разогнаться в потоке — притянул за штаны и отвесил крепкую оплеуху. И согрешил — оставил камуфляжных без внимания."}, {"kind": "paragraph", "text": "Они подошли ко мне сзади бесшумно, как кошки. Наверное, решили снять вражеского часового с поста. И ударили. Сзади. По голове. По затылку. Как Череп хотел — в голову, а не в пяту."}, {"kind": "paragraph", "text": "О, эти «гравёры» крепко держали в руках кувалду. Били по скарпелю прицельно и дерзко. Вышибали в мозгах моих: «Не любим. Не помним. Скорбеть не будем». У них свой юморок — с червоточинкой. Били так, что в какой-то момент я отчётливо услышал церковный колокол. И увидел сквозь муть потока стайку тёмных старух и Лешего, надувающего лягушек. Кричать я не мог. Лежал под липами и глотал воздух, словно рыба, выброшенная на берег."}, {"kind": "paragraph", "text": "«Лёва, я тебя умоляю, не нужно пошлых розочек и сериальной скорби. Напиши бодрящее: \\"Он шёл по жизни, чуть шатаясь\\". Не надо скорбеть и помнить»."}, {"kind": "paragraph", "text": "Кажется, я надул через задницу огромную жабу и запустил её прямо в небеса. Авось откликнутся."}, {"kind": "paragraph", "text": "Вика, Лёва, Игнат, Машка, Леший, Череп, Корней, старушки с косами и новыми зубами."}, {"kind": "paragraph", "text": "Господи, как хорошо…"}, {"kind": "paragraph", "text": "Очнулся под липами под утро — от странного шелеста сверху. Будто ангелы крыльями зашуршали в кронах деревьев. И по лицу — нежно и ласково — заплясали…"}, {"kind": "paragraph", "text": "Боже, это же дождь!"}, {"kind": "paragraph", "text": "Случилось чудо."}, {"kind": "paragraph", "text": "Скарпели камуфляжных пробили небеса и влезли в потусторонние нейронные связи."}, {"kind": "paragraph", "text": "И хлынул дождь."}, {"kind": "paragraph", "text": "Долгожданный, чудесный, преображающий."}, {"kind": "paragraph", "text": "Нет, я не плакал. Не имею такой привычки."}, {"kind": "paragraph", "text": "Это был дождь."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
9	mrd6-betmen	Бэтмен	47	mrd6/mrd6-betmen.png	data:image/jpeg;base64,	Насилие — это результат мечтаний.	[{"kind": "image", "path": "mrd6/mrd6-betmen.png", "caption": "Иллюстрация Маргариты Царевой при помощи Midjourney"}, {"kind": "paragraph", "text": "Насилие — это результат мечтаний."}, {"kind": "paragraph", "text": "Я — что-то типа Бэтмена города Кызыла. Только у меня нет ни маски, ни специального костюма, ни машины, ни миллиарда долларов, ни тех, ради кого мне нужно скрывать своё лицо. Я работаю на заказ, но никогда не убиваю людей. Беру деньги, и цена зависит от клиента: если заказчик богатый или чиновник — беру не менее ста тысяч рублей, но я никогда не гнушаюсь брать деньги и с обычных людей."}, {"kind": "paragraph", "text": "Отличие богатых от бедных состоит в том, что богатые хотят устранить конкурентов, а бедные просто хотят отомстить кому-нибудь за какую-нибудь злобу. А объединяет их то, что я отношусь к ним абсолютно одинаково, не берусь за дело сразу, потому что, прежде чем исполнить заказ, мне нужно изучить объект заказа, что занимает от трёх до семи дней, за которые я стараюсь лучше понять жертву, изучить её привычки и найти момент для удара. Если же считаю, что объект не так уж плох, то отказываюсь от заказа или повышаю цену, не объясняя причин. А порой я узнаю, что объект — та ещё сволочь."}, {"kind": "paragraph", "text": "Однажды, изучая объект, я увидел, как он, чиновник в сельском районе, избивает и насилует свою жену. Я не стал медлить: днём отключил жену хлороформом, связал её и запер, чтобы она ничего не увидела и не услышала, а вечером, когда муж вернулся, избил его и сломал ему пальцы и кисти рук молотком, чтобы он даже подтереться не мог, не говоря уже о насилии. Я не взял плату, даже не сообщил, что заказ выполнен, а просто сделал, что было по совести, и продолжил жить дальше."}, {"kind": "paragraph", "text": "Вообще, я люблю использовать молоток — в этом есть что-то философское и отсылка к «Олдбою» Пак Чхан Ука. Молоток — великий инструмент строителей, воздвигший бессчётное количество домов, зданий, а я использую его, чтобы избивать объекты. Используя молоток, я тоже строю будущее, в котором общество сможет жить лучше, не боясь насилия и убийств, но пока у меня не получается, потому что в новостях и соцсетях обо мне чаще пишут как о некоем разбойнике, а может, даже преступной группе. Ну и ладно — я давно привык к этому. Бывают случаи, что на встречах с заказчиками они начинают поучать меня — я вот так бессовестно избиваю незнакомых людей, — хотя сами обращаются ко мне с заказом и потом ещё и платят деньги. Я бы не брал эти заказы, честное слово, но на жизнь чем-то надо зарабатывать: надо есть, пить, постоянно покупать новую симку, телефон, чтобы не выследили, менять гардероб и сжигать старую одежду, если заметили на улицах. Понимаете, деньги всё равно мне нужны, но я никогда не принимаюсь за заказ, если считаю, что объект — достойное существо."}, {"kind": "paragraph", "text": "У меня есть хобби: бродить по ночам по Кызылу и ловить всяких мелких бандюков или хулиганов, хорошенько учить их уму-разуму через то, что они привыкли воспринимать — насилие. Как правило, в такое время я включаю наушники и слушаю Малера — Восьмую симфонию. Малера я впервые услышал, когда только начал увлекаться своим делом. Тогда я жил в Екатеринбурге и учился у одного из местных бандитов рукопашному бою, стрельбе, стратегии пыток; он отправил меня разобраться с какой-то «крысой», которая сдала их ментам, дал адрес с квартирой, и вот когда я ворвался к нему, когда разбил ему лицо (Бэмс! Шмак! Бах!), сломал ногу, то наконец — в тишине и под звуки стонов своего первого объекта — услышал кульминацию."}, {"kind": "paragraph", "text": "— Что это за музыка? — спросил я у лежащего, но он не ответил. Тогда я наступил ему на сломанную ногу. — ЧТО ЭТО ЗА МУЗЫКА?!"}, {"kind": "paragraph", "text": "— Это Малер, недоучка! Восьмая симфония! А-а-а, отпусти, псих!"}, {"kind": "paragraph", "text": "Я забрал этот диск и слушал Восьмую симфонию целую ночь. Слушал и слушал, и долгие годы она мне не надоедала. Я задавался вопросом, почему она мне нравится, и понял, что без неё меня начинают мучить вопросы о том, кто я и зачем я всё это делаю, но с этой музыкой, с этой симфонией я успокаиваю себя."}, {"kind": "paragraph", "text": "Насчёт того, что я не убиваю людей… На самом деле, я убил одного человека — но по чистой случайности, да и объект сам был виноват: мог бы отделаться только травмами, а в итоге теперь лежит в земле. Под словами «я не убиваю» я имею в виду, что не беру заказы на убийства, но убийство становится следствием случайности или вспыльчивости объекта."}, {"kind": "paragraph", "text": "Сам я живу в небольшой квартирке возле Башни. Мне нравится этот район — особенно после того, как я зачистил его от всех алкашей и пацанов, которые включали громкую музыку ночью, когда все пытаются уснуть. Я люблю сидеть по ночам на скамейке и просто наслаждаться тишиной, которая напоминает мне, что хоть я и побил множество людей, так или иначе сделал чью-то жизнь лучше, чей-то сон — спокойнее, а чью-то прогулку — приятнее."}, {"kind": "paragraph", "text": "Скоро Новый год, а это значит, что мне вот-вот придёт письмо от матери с приглашением встретить праздник вместе. Ненавижу Новый год, и тем более — праздновать его, и тем более — праздновать с семьёй, но почему-то в этом году я чувствую себя иначе. Наверное, это из-за одного объекта, которого я избил под Новый год сколько-то лет назад. Его заказала любовница, которая забеременела от него, не получала алиментов, когда он был женат, о чём узнала бывшая жена и развелась с ним. Я изучал его несколько дней, и мне показалось, что он был обычным сорокалетним мужиком, но мне не было его жаль: он изменил жене, обрюхатил другую, не платил алименты — так что я с лёгкостью на душе сломал ему челюсть и также отбил яйца, чтобы больше ни одна женщина от него не забеременела."}, {"kind": "paragraph", "text": "Когда он лёг на землю, я заметил рядом коробку с игрушкой — подарок сыну на Новый год. Сыну не от любовницы. Это был дорогой подарок: миниатюрная железная дорога с локомотивом, которая умеет издавать звук и выпускать дым, при этом вся модель была украшена горами, лесами и ещё тысячей мелких деталей. Я видел однажды такую, когда гулял по торговому центру Екатеринбурга, и не мог наглядеться на этот маленький поезд, который так отрадно, стойко и целеустремлённо движется по своему пути. Я не мог купить именно эту модель, которая по размерам была равна четырём квадратным метрам, но запомнил её, и это детское желание, которое мне казалось утраченным далеко в детстве, запомнил и хранил крепко."}, {"kind": "paragraph", "text": "И вот я стою над этим отцом, который хотел подарить своему сыну поезд, и ощущаю какое-то щемящее чувство внутри, чувство отрады за мальца, который получит этот поезд. А на отца — плевать…"}, {"kind": "paragraph", "text": "Когда я подошёл к дому своих родителей (не буду говорить, в каком районе и селе они жили — в целях их безопасности), то мать меня не узнала. Причём встретила меня одна: отец стал глуховат к своим годам, не услышал, что его зовут. Он сидел в кресле и смотрел телевизор, именно смотрел, а не слушал, и когда я подошёл к нему, он тоже меня не узнал, но, узнав, встал из кресла и пожал мне руку."}, {"kind": "paragraph", "text": "— Как мы рады тебя видеть, сынок! Как ты вырос, какой большой и сильный! Качаешься? — спросила мать."}, {"kind": "paragraph", "text": "Я ответил, что хожу в зал."}, {"kind": "paragraph", "text": "Не буду ходить вокруг да около — неприятно вспоминать это место. Просто скажу: дни мы провели спокойно, по крайней мере сами не вспоминали прошлое, а прошлое всё мелькало перед глазами — в виде нефункционирующей руки отца, которую я раздробил ещё в детстве молотком, чтобы он перестал избивать мать (Бэмс! Шмак! Бах!)."}, {"kind": "paragraph", "text": "— Ну что, девушка у тебя есть? — спросила мать."}, {"kind": "paragraph", "text": "Я чуть не подавился. Сама идея девушек в романтическом плане меня никогда не интересовала. Никогда не приходила в голову."}, {"kind": "paragraph", "text": "— А чем на жизнь зарабатываешь? — спросил отец."}, {"kind": "paragraph", "text": "Я застыл. Ответил, что работаю охранником."}, {"kind": "paragraph", "text": "— Ух ты, много получаешь?"}, {"kind": "paragraph", "text": "— Достаточно."}, {"kind": "paragraph", "text": "— А по одежде не видно. Прикупи что-нибудь получше, а то ходишь, как гопник. Или в Кызыле все так ходят? И ты решил, что если все так ходят, то и тебе стоит? Весь в старой одежде, похож на бомжа. Хотя, наверное, даже бомжи в Кызыле лучше одеваются, да? Ну я бы не удивился. Ты никогда не отличался умом — вот и стал охранником. Вот у тебя жены и нет, потому что любая женщина постыдится ходить с таким, как ты."}, {"kind": "paragraph", "text": "— Заткнись, пожалуйста! — закричала мать. — Сын к нам приехал, а ты продолжаешь вести себя, как осёл!"}, {"kind": "paragraph", "text": "Находиться в этом доме, где мать вечно занимается чем-то непонятным на кухне, а отец часами смотрит на движущиеся картинки, было невыносимо, поэтому в тот же день я вышел на улицу — осмотреться, вдруг что-нибудь новенькое или всякие хулиганы местные ходят."}, {"kind": "paragraph", "text": "И вот, идя по улице, я встретил своего старого — единственного — школьного друга и одноклассника, который теперь стал председателем администрации. Он пригласил меня в свой кабинет."}, {"kind": "paragraph", "text": "— Какой ты большой стал! Качаешься?"}, {"kind": "paragraph", "text": "— Можно и так сказать."}, {"kind": "paragraph", "text": "— Чудо, что я тебя узнал. От прежнего мальчишки ничего не осталось. Мы с тобой сколько не виделись? Сколько прошло с того инцидента?"}, {"kind": "paragraph", "text": "— Какой инцидент?"}, {"kind": "paragraph", "text": "— Тот самый. Ты забыл? Ну и ладно, ничего интересного не произошло. Чем вообще занимаешься в Кызыле? Наверное, охранником сделался — с такими руками? Не хочешь ко мне? Буду платить прилично, а то тут с каждым разом становится всё опаснее. Да и не все меня любят: обвиняют, что я своровал деньги, которые должны были уйти на постройку бассейна. Но они неправы. Не я один забрал эти деньги… Шучу! Вот такие у политиков шутки. Кстати, ты не слышал о некоем человеке? Он стал уже мифом. Некоторые называют его Бэтменом, только не таким благородным. Слышал о нём?"}, {"kind": "paragraph", "text": "— Нет, ничего подобного."}, {"kind": "paragraph", "text": "— Говорят, он принимает заказы на людей. Не убивает, только избивает. Делает чисто, тихо. Но самое подлое — что на него не выйти. Жаль. Я бы ему заплатил так, как никто не платил бы."}, {"kind": "paragraph", "text": "— И сколько бы ты ему заплатил?"}, {"kind": "paragraph", "text": "— Сколько? Думаешь, я бы предложил ему деньги? О нет, в мире есть то, чего за деньги не купить. Нельзя купить прощение, искупление, совесть… Понимаешь? Я думаю, этот человек калечит потому, что ему нужно прощение. Возможно, сам он этого не осознаёт, но именно этого он и добивается… У меня есть для тебя заказ."}, {"kind": "paragraph", "text": "— Ты думаешь, это я — тот человек?"}, {"kind": "paragraph", "text": "— Не отвертишься. Я точно знаю. У меня есть заказ. И я заплачу тебе тем, чего ты так желаешь."}, {"kind": "paragraph", "text": "— Деньги у меня есть."}, {"kind": "paragraph", "text": "— Я ведь то, что тебе нужно: искупление. Неужели ты и правда не помнишь тот инцидент? Не помнишь, как побил меня?"}, {"kind": "paragraph", "text": "— Нет."}, {"kind": "paragraph", "text": "— История простая: тебе нравилась девочка в нашем классе, как и многим другим мальчикам. А от ревности ты побил только меня — единственного друга. И знаешь почему? Потому что я был слабее тех мальчиков, которым она тоже нравилась. Мне плевать, а вот тебе… Я знаю, ты ищешь искупления. Не просто так сюда пришёл, не просто так вернулся спустя столько лет. И вот в итоге из всех парней та девочка выбрала именно меня. И стала моей женой. Женой и вместе с тем трагедией. Она мне изменяет, а я её люблю. Мой заказ таков: я хочу, чтобы ты нашёл и избил её любовника. А взамен ты искупишь свою вину. Ты наконец перестанешь жить социопатом. Начнёшь жизнь заново, освободишься от этого страха перед счастьем. Ты наконец-то станешь человеком."}, {"kind": "paragraph", "text": "Я вернулся домой поздним вечером, когда улицы были уже почти пусты, в редких окнах ещё горел свет, и, идя медленно сквозь сугробы, будто нарочно откладывая возвращение, я думал о встрече с тем человеком, которого когда-то знал — и не узнал бы, если бы не голос, не движения, не неуловимый, но ясный внутренний стержень, как узнают по странной, только одному человеку присущей походке."}, {"kind": "paragraph", "text": "И, размышляя о нём, я, сам того не замечая, стал думать о девочке, которая тогда, в том далёком прошлом, мне нравилась, о том, какая она теперь, где живёт, как говорит, как смеётся, и не исказило ли время её лицо — так же, как искажается душа, если человек живёт неправдой."}, {"kind": "paragraph", "text": "Когда я подошёл к дому, который тишина окутала особенным тревожно-уютным покровом и в котором угадывались знакомые звуки: телевизор, работающий вполголоса, стул, скрипящий под тяжестью отцовского тела, и сдержанное мамино дыхание из её комнаты — всё это звучало как прежде, как будто и не было тех лет, что меня не было здесь, как будто всё замерло в ожидании моего возвращения, но не из любви — нет, а скорее по привычке, как замирает знакомый пейзаж в окне не потому, что он тебя ждёт, а потому, что он есть."}, {"kind": "paragraph", "text": "Я вошёл в свою старую комнату — всё на месте: тетради на полке, книги, фотографии. А самое главное — комиксы."}, {"kind": "paragraph", "text": "Я не особо любил Человека-паука или Супермена, мне больше нравился именно Бэтмен, хоть он и был миллиардером, в отличие от меня, и на свои миллиарды купил огромное количество технологий, но, несмотря на богатство и возможности, даже без своего костюма и машины он мог побить плохих парней своими руками, потому что был здоров как бык, мог с лёгкостью поднять сто килограмм, и если бы он захотел сделать карьеру в спорте, ему не было бы равных. Я взял один выпуск комикса и, сев на кровать — ничуть не запылённую за долгие годы, — начал читать, смотреть на картинки, на графические эффекты от ударов, особенно звуковые: «Бэмс!», «Шмак!», «Бах!». Забавно: в детстве мне хотелось стать похожим на него, и во многом мне это удалось."}, {"kind": "paragraph", "text": "Когда я вновь вспомнил его — друга, которого когда-то уважал, которому завидовал, которого, быть может, любил, — я понял, что в этой истории, в этом нелепом, почти гротескном замысле, где якобы нужно было наказать кого-то за предательство, я сам и был тем, кто предал. Кто осквернил дружбу, а не тот, кого обвиняли. И потому даже когда он уверенно, почти с каким-то внешним спокойствием — как бывает у людей, давно приговоривших кого-то в своём сердце, — сказал, что всё в прошлом, что ему это безразлично, я увидел: в нём глубоко, под толщей молчания, живёт та самая обида, прогнившая, забытая не им, но временем, как забывается боль, оставшаяся в теле после болезни, ты уже не думаешь о ней, но она там, она дышит, и, когда ты прикоснёшься, запах её вырвется наружу, и ты поймёшь, что ничего не прошло, что человек не время и не Бог, он не лечит, он лишь прячет."}, {"kind": "paragraph", "text": "Чего я не могу вспомнить — неважно, как ни стараюсь, как ни обхожу стороной, как ни ловлю себя на обрывках, — так это того, как я избил своего друга с глухой яростью, разрушил нашу дружбу, ту самую, которой я дорожил по-настоящему, всеми остатками своего школьного, детского, да и вообще человеческого существования. Потому что, когда я встретил его спустя годы, мне вдруг стало светлее, как будто в этой серости, в этих холодных, вязких, неумолимо скукоживающихся днях появилось что-то, похожее на утешение; не надежда, нет, но хотя бы воспоминание, показалось, что, может быть, я смогу, даже через нашу общую немногословность, всё-таки с ним заговорить, услышать, вспомнить… Да, именно — вспомнить! Но не я — он, именно он вспомнил бы всё и рассказал, а я — только слушал, только вытаскивал из глубин памяти то, что когда-то тоже было моим, хотя уже и не казалось таким."}, {"kind": "paragraph", "text": "И всё же вместо этого, вместо этой смутной надежды на что-то, пусть и не настоящее примирение, но хотя бы жест доброй воли, случилось обратное: встреча омрачилась его болью, обидой, его невысказанным или слишком резко высказанным желанием отомстить мне, вцепиться в меня, соскрести с меня старую вину его ревностью к жене, его яростью на любовника, его ощущением, что ему что-то недодали, недоотдали, что я забрал, и я в этот момент снова оказался тем, кем всегда был — кто бьёт первым, кто не жалеет удара, кто выбивает зубы, кто ломает кости, тем, кем я никогда по-настоящему не переставал быть."}, {"kind": "paragraph", "text": "Не скажу, что нехотя или без желания я взялся за эту работу, тем более за которую заплатят не деньгами, а искуплением (будто я персонаж Достоевского) и которую мне предложил не какой-нибудь тупой обыватель этой планеты, а сам председатель села — впрочем, как и всегда, это была лишь работа, а не личная жизнь, — но я согласился в очередной раз побыть Бэтменом, восстанавливая чью-то сугубо субъективную справедливость — хоть и не города Кызыла, хоть и не ради денег, хотя меня продолжала одолевать внезапно возникшая на фоне встречи с родителями усталость от себя и, наверное, от существования моих родителей, перед которыми я, от стыда или страха, должен скрывать детали своей работы, и я надеялся, что где-то внутри очерствевшей души я скажу себе, что это всё, что это последнее задание, что после этого чёртового заказа я уеду далеко, может, в лес, может, за границу, и больше никогда не стану бить людей."}, {"kind": "paragraph", "text": "Но я ничего другого и не умею, ничему другому не учился, даже школу до конца не окончил, и мне кажется, что мне нравится бить людей, как людям нравится пить алкоголь от радостного или грустного события или курить сигареты по утрам и после еды, а может быть, это, как и алкоголизм, просто зависимость — иметь власть воздействовать на жизнь и сознание людей через насилие их тела, через боль, через страх, через угрозу смерти… Ладно, плевать, надо покончить с этим дерьмом."}, {"kind": "paragraph", "text": "На улице этого села включённые фонари — скорее исключение, чем правило из-за пьяных мальчишек, кидающих камни в лампы; жизнь омрачается не только отсутствием солнца и работающих фонарей, но и разгуливающей шпаной, алкоголиками, драками, разбитыми лицами, сломанными руками и нередко ножевыми ударами в живот. Это по мне… Я бы остался тут, в этом тихом по звукам и громком по молчаниям селе, навёл бы тут порядок, набил рожи всем парнишкам — чтобы больше не пили, чтобы не дразнили одноклассников, чтобы занимались спортом."}, {"kind": "paragraph", "text": "А оказывается — и так было всегда — что от наших мечтаний о будущем или о самих себе мало что зависит и что мечтания, какими бы они благородными ни казались, редко приводят к тому, что называют хорошим. Но я бы не только исправлял тут жизнь через насилие — я бы и просто помогал людям: старикам бы колол дрова, детей учил драться, защищал жён, которых избивают мужья… Твою мать, в итоге всё сводится к насилию! Да, к насилию, потому что насилие — это результат мечтаний!"}, {"kind": "paragraph", "text": "Когда я нашёл изменщицу своего друга… простите… Когда я нашёл изменщицу своего бывшего друга — пока она гуляла со своим любовником, лицо которого я не мог разглядеть, будто он чувствовал на себе мой взгляд и пытался от него улизнуть, — время уже подходило к утру, ноги замёрзли, в общем-то, как и всё тело, стало тихо, настолько, что меня начала пугать громкость моего дыхания, которое могли услышать на другом конце села, но я мог продолжать, мог нанести удар, мог искупить свою вину. Мне только нужно было увидеть лицо объекта. Я не знаю почему, но, казалось, это было важно."}, {"kind": "paragraph", "text": "В гробовой тишине зимнего утра, пока деревья наблюдали за мной из-под заснеженных век, затаив дыхание, я стал часто оглядываться по сторонам, пытался разглядеть за каждым углом кого-то, кто за мной следит, будто мой бывший друг ещё кого-то нанял разобраться со мной, и, пока я отводил взгляд от объекта, он вдруг исчез. Она стояла одна, спиной ко мне, смотрела вдаль. Почему-то меня охватила тревога от этого вида: одинокая женщина стоит посреди заснеженной улицы и смотрит в её конец — тёмный, пустой, как тоннель в метро, будто она убила всех в округе. Я стал медленно идти в её сторону, а затем понемногу бежать — мне захотелось ударить её в затылок. Не знаю почему. Вот просто захотелось!"}, {"kind": "paragraph", "text": "ПРОСТО ХОЧУ ЕЁ УДАРИТЬ! ХОЧУ РАЗМОЗЖИТЬ ЕЙ ЛИЦО! СЛОМАТЬ ЕЙ РЁБРА! ВЫЛОМАТЬ РУКИ! Я БЕГУ НА НЕЁ! ГОТОВ НАПРЫ-"}, {"kind": "paragraph", "text": "— Это же ты? — спросила она, повернувшись. У неё не было глаз, а только их подобие, через которое смотрела густая тьма."}, {"kind": "paragraph", "text": "— Что?"}, {"kind": "paragraph", "text": "— Это ты… Ты! Боже мой, это ты! Как же я по тебе скучала! — Она подбежала ко мне и обняла. — Господи, как ты изменился! Качаешься? Но где ты был? Почему ты ни разу не приезжал ко мне?"}, {"kind": "paragraph", "text": "— Что ты несёшь?"}, {"kind": "paragraph", "text": "— Ты ведь должен был приехать за мной, должен был забрать меня, чтобы мы жили далеко отсюда, вместе. Неужели ты забыл?"}, {"kind": "paragraph", "text": "— Погоди, что ты имеешь в виду? Я ничего не должен был тебе. Мы с тобой почти никогда и не общались."}, {"kind": "paragraph", "text": "— Зачем ты так говоришь? Я же люблю тебя, и ты любишь меня, разве нет? Разве ты не помнишь? Ты убил своего друга, своего единственного друга — убил ради меня. Ты не помнишь?"}, {"kind": "paragraph", "text": "— Друга? Какого друга?"}, {"kind": "paragraph", "text": "— У тебя больше не было других друзей. Он был только один."}, {"kind": "paragraph", "text": "— Постой... Ты о председателе?"}, {"kind": "paragraph", "text": "— При чём тут председатель?"}, {"kind": "paragraph", "text": "— Да постой ты, чёрт возьми! Не лезь на меня! Что тут происходит?! Ты — жена председателя этого села. Ты изменяешь ему с этим мужиком, который стоял возле тебя."}, {"kind": "paragraph", "text": "— Возле меня? Но я тут всегда была одна. О чём ты?"}, {"kind": "paragraph", "text": "— Только что, перед тем как я подошёл, ты всю ночь ходила с каким-то мужиком, не знаю, кто это."}, {"kind": "paragraph", "text": "— Это не так, любимый! Я всегда была одна! Я хранила верность тебе! Ты мне не веришь?"}, {"kind": "paragraph", "text": "— Какой, к чёрту, любимый?! И что ты имеешь в виду, говоря, что я убил своего друга?"}, {"kind": "paragraph", "text": "— Ты убил его. Ударил молотком по голове на новогоднем утреннике, потому что его поставили танцевать со мной. Когда его тёплая кровь попала на моё лицо и когда я увидела тебя — я сразу же влюбилась! Ты тот, кто сможет защитить меня в этом ужасном месте, в этом ужасном мире!"}, {"kind": "paragraph", "text": "— Это невозможно… Это какой-то бред. Я только вчера с ним разговаривал, я только вчера его видел. Он жив, чёрт тебя подери!"}, {"kind": "paragraph", "text": "— Если он жив, то как его зовут, а? Вспомни его имя."}, {"kind": "paragraph", "text": "— Да чёрт, что за бред! Я знаю его имя!"}, {"kind": "paragraph", "text": "— Ну так назови его!"}, {"kind": "paragraph", "text": "— Это не имеет смысла. Назову я его — и что дальше?"}, {"kind": "paragraph", "text": "— Да, это не имеет смысла, потому что мы вместе. Мы наконец-то вместе, мой любимый! Спустя столько лет! Ну же, милый, обними меня, поцелуй меня! ЛЮБИ МЕНЯ! Слышишь меня?! ОБНИМИ! ПОЦЕЛуЙ мЕНЯ ЧОртаВА ТЫ МРАЗЬ! ПАцилУЙ! ЦЭлУЙ!"}, {"kind": "paragraph", "text": "— Успокойся!"}, {"kind": "paragraph", "text": "Что происходит? Что со мной? Где я? Что случилось? Я не чувствую тела — только сознание, которое будто сидит в падающем вертолёте, но падает вертолёт не вниз, а вверх... если верх вообще существует, потому что, когда я падал наверх, у меня было ощущение, что верх понемногу превращается в низ, падает в отзеркаленный мир, абсолютно идентичный нашему нынешнему, но отчего-то, казалось, более тёмный, мрачный и тревожный, словно в том мире я не тот, кто я есть сейчас."}, {"kind": "paragraph", "text": "— Успокойся, ублюдок! — кричит на меня мужчина."}, {"kind": "paragraph", "text": "Я чувствую, как чьи-то руки очень крепко и даже больно сжимают меня, и это кажется крайне непонятным, потому что мало у кого хватало длины и силы рук, чтобы обхватить меня полностью — и тем более доставить мне дискомфорт, если только вдруг моё тело не уменьшилось."}, {"kind": "paragraph", "text": "Когда перед глазами всё более-менее начинает приходить в норму, а голова перестаёт кружиться, я замечаю перед собой толпу детей, и через некоторое время — взрослых, которые этих детей держат, а то, что их объединяет, — это то, что все они смотрят на меня и смотрят при этом с ужасом, будто я убил человека."}, {"kind": "paragraph", "text": "Вдруг я получил кулаком по голове."}, {"kind": "paragraph", "text": "— Успокоился?! — кричит мне в ухо мужчина, тот же самый, который не отпускает меня. Я пытаюсь выбраться, но, на удивление, у меня не хватает сил даже пошевелить рукой."}, {"kind": "paragraph", "text": "— Отпусти меня! — кричу я — и удивляюсь самому себе. Это я сказал? Зачем? Что со мной?"}, {"kind": "paragraph", "text": "Я замечаю, как в помещение, которое я мог распознать как зрительный зал — то ли в Доме культуры, то ли в школе — вбегают сотрудники скорой помощи и направляются к мальчику с кровью, текущей с макушки — судя по мокрым волосам, а на руках его держит женщина и неистово плачет, пытаясь своей кофтой остановить кровотечение. И какой бы чёткой ни стала картина перед моими глазами, я всё равно не могу понять: что тут, чёрт возьми, происходит?"}, {"kind": "paragraph", "text": "— Ты хоть понимаешь, что только что натворил, ублюдок? — говорит тот мужчина, который меня держал и который оказался моим отцом, но на удивление молодым. Что ещё более удивительно — его рука, которую я когда-то раздробил молотком за то, что он бил мать, была совершенно здорова и, мало того, ещё и умудрялась теперь бить меня."}, {"kind": "paragraph", "text": "Когда отец ударил меня в первый раз, я не успел увернуться, но решил замахнуться в ответ, а сил и скорости моих рук не хватило, чтобы он не успел увернуться. И вот тогда я понял, что эта слабость моего тела от того, что какого-то чёрта моё тело превратилось обратно в тело двенадцатилетнего ребёнка!"}, {"kind": "paragraph", "text": "— Эй, ублюдок! Ты меня слышишь?"}, {"kind": "paragraph", "text": "— Не смей меня так называть!"}, {"kind": "paragraph", "text": "Бэмс! Шмак! Бах! Я падаю на пол, у меня течёт кровь из носа, болят побитые рёбра, бёдра, спина. Пытаюсь встать — и вдруг меня берут за волосы и швыряют в стену. Сознание отключается."}, {"kind": "paragraph", "text": "...Я просыпаюсь в тёмной комнате, сижу, мои руки привязаны к чему-то, что не могу разглядеть через густую темноту комнаты, в которой нет окон, как в доме моих родителей, хотя я мог догадаться, что раз уж мой отец меня вырубил, то и отнёс меня домой, и запер тут, как он это часто делал со мной в детстве — если я не застелил кровать с утра и если он был в хорошем настроении от алкоголя."}, {"kind": "paragraph", "text": "Если это и правда та маленькая комната, где он меня запирал, то недалеко и дверь... Я смогу её выломать… точнее, нет, не смогу."}, {"kind": "paragraph", "text": "Но я начинаю стучать и кричать:"}, {"kind": "paragraph", "text": "— Грёбаный ублюдок, чёртов алкаш! Открой дверь! А то я тебе челюсть сломаю!"}, {"kind": "paragraph", "text": "Это подействовало — с оговорками. Бэмс! Шмак! Бах! Я снова валяюсь на полу с разбитой губой, вижу, как отец идёт на кухню, садится за стол, выпивает рюмку водки и смотрит телевизор, подвешенный на потолок. А буквально за стеной, в спальной комнате, стоит мать и смотрит на меня тем знакомым взглядом, от которого я её избавил, лишив отца возможности как минимум дрочить этой рукой."}, {"kind": "paragraph", "text": "— Да что, чёрт возьми, происходит? Это сон? Если это сон, то я хочу проснуться. Эй, алкаш! Да, ты! Ударь меня ещё раз, чтобы я проснулся. Ну же!"}, {"kind": "paragraph", "text": "Через месяц после того инцидента врачи психиатрической больницы диагностировали у меня шизофрению на почве чего-то там, но уж точно не жестокого обращения со стороны отца, который, помимо лёгкой для насилия над женщинами руки, имел и подвешенный язык в этом маленьком селе, где какая-нибудь падшая женщина могла отдаться за бутылку водки, на которую скинулись три мужика, собирая целую неделю стеклянные бутылки и банки."}, {"kind": "paragraph", "text": "Я пролежал в больнице два месяца и был отправлен домой для домашнего обучения с трёхразовым приёмом таблеток — для восстановления мироощущения и ежесекундного осознания того, что вся моя карьера Бэтмена оказалась лишь плодом воображения, заполненного комиксами из моей комнаты. Чёрт подери…"}, {"kind": "paragraph", "text": "Тёмный узкий коридор. Стены покрыты трещинами, тени пляшут под мерцающим светом. Бэтмен окружён буйными пациентами Аркхэма — они наступают со всех сторон, их глаза безумны, зубы оскалены. Он не хочет калечить их, но они бросаются на него с ножами, трубами, голыми руками."}, {"kind": "paragraph", "text": "Бэтмен движется как тень: резкий удар в живот одного, ломающий хватку другого, перекат под летящую бритву. Он использует стены, отталкивается, чтобы увеличить силу удара, но каждый раз сдерживается: это жертвы, а не враги. Бэмс! Шмак! Бах!"}, {"kind": "paragraph", "text": "Вдруг свет гаснет. На секунду — тишина. Потом — крики, звуки падающих тел. Когда свет возвращается, Бэтмен стоит один среди груды бесчувственных тел. Его плащ развевается, дыхание ровное. Он не празднует победу — он уже движется дальше, вглубь безумия Аркхэма."}, {"kind": "paragraph", "text": "Дома, вместе с мамой и бутылкой водки отца, я отучился почти два года, пока врачи и сотрудники полиции не сочли, что ребёнок годен для прохождения школьной службы, и это означало только одно: пока я в школе, я буду видеть, как отец избивает мать, в два раза меньше, чем когда учился дома. Не знаю, хорошо это или плохо. Может, ни то ни другое?"}, {"kind": "paragraph", "text": "Странно так бывает в мире: есть вещи, которые ни хороши, ни плохи, они просто есть. Так, может, и насилие — это тоже ни плохо, ни хорошо? Насилие просто есть. Как и мечты. Мечты — это не плохо и не хорошо. Они просто есть. Разве нет?"}, {"kind": "paragraph", "text": "После долгожданного (в другом измерении) возвращения в школу — на класс ниже того, в котором учился, — я ожидал, что все будут смотреть на меня, как на прокажённого. И знаете что? Так и было! Никто со мной не разговаривал. Но я подумал: а какая разница? Дома мать не была мне особо хорошим собеседником — впрочем, как и учителем. Кем ей хорошо удавалось быть — так это грушей. Наверное, это передалось мне по наследству."}, {"kind": "paragraph", "text": "Я был худощавым парнем, и это было что-то вроде болезни, так мне сказали в больнице, а отец говорил, что я просто слабак, и обвинял мать, что это она виновата в моей худощавости и тем более — в том инциденте."}, {"kind": "paragraph", "text": "Однажды ночью, когда отец лежал после выпитой бутылки водки, я взял молоток и хотел сделать то, что сделал другой «я». Я подошёл к кровати, на которой он лежал на спине, свесив руку на краю и положив её на деревянный стул, на котором просто обожал сидеть во дворе и пить с соседом, поднял молоток, но вдруг увидел взгляд отца. Он смотрел на меня спокойно, руку не убирал, лежал, ожидая моих действий, а я смотрел на него в ответ всё с тем же поднятым молотком."}, {"kind": "paragraph", "text": "— Ну же, сделай это, — сказал отец."}, {"kind": "paragraph", "text": "Но я не мог. Мне было страшно."}, {"kind": "paragraph", "text": "— Я так и думал. Ты просто слабак. Худой, слабый сопляк, — сказал он и повернулся на другой бок."}, {"kind": "paragraph", "text": "По возвращении в школу я, конечно, ожидал увидеть своего друга, который, как оказалось, уезжал куда-то с семьёй на отдых, мне сказали, что он лежал в коме от моего удара почти два месяца, а затем ещё полгода реабилитировался, совмещая это с домашним обучением — как и я. Но, в отличие от меня, в школу он вернулся на год раньше, и при этом его не отправили на класс ниже, а ввиду горя семьи вернули к одноклассникам."}, {"kind": "paragraph", "text": "Когда я узнал, что он вернулся, очень хотел с ним встретиться. Хотя понимаю теперь, что это было глупо. После уроков я нагнал его и одноклассников."}, {"kind": "paragraph", "text": "— Привет, — сказал я."}, {"kind": "paragraph", "text": "Он промолчал."}, {"kind": "paragraph", "text": "— Слушай, моя мама дома пирог сделала. Не хочешь ко мне пойти? — Это была ложь. Мать никогда не делала пироги, потому что отец запрещал, считая, что пироги только для слабаков и что мужчины должны есть только мясо."}, {"kind": "paragraph", "text": "— Нет. Я ухожу."}, {"kind": "paragraph", "text": "— А можно с вами?"}, {"kind": "paragraph", "text": "— Нет."}, {"kind": "paragraph", "text": "— Может, тогда завтра?"}, {"kind": "paragraph", "text": "— Нет."}, {"kind": "paragraph", "text": "— А послезавтра?"}, {"kind": "paragraph", "text": "— Хватит! Я не хочу с тобой гулять. Я не хочу быть твоим другом."}, {"kind": "paragraph", "text": "— Никогда?"}, {"kind": "paragraph", "text": "— Да! НИКОГДА! НИКОГДА!"}, {"kind": "paragraph", "text": "Он толкнул меня, и дети вокруг замерли. Я заметил, как учитель с сигаретой подглядывал за нами из-за угла и ждал дальнейших событий. Одноклассники смотрели на меня, будто знали, что произойдёт дальше, а дальше — ритуал избиения, унижения, и никто не будет против, потому что все давно мечтали, чтобы мальчик, который избил самого доброго и умного мальчика, самого благородного, который находил хорошее даже в таком дерьме, как я, наконец сам оказался избит."}, {"kind": "paragraph", "text": "Я посмотрел на группу детей позади него и увидел ту самую девочку, из-за которой всё началось, и она тоже смотрела на меня с отвращением, она была готова вырвать мне яйца — хотя даже никогда их не видела, и им ещё не объясняли это на уроках биологии."}, {"kind": "paragraph", "text": "Но ничего не произошло. Он и его друзья просто повернулись и ушли."}, {"kind": "paragraph", "text": "Не буду врать: когда я вернулся домой, я просто заплакал, сидя на кровати. Плакал так сильно, что даже руки не могли сдержать слёз. Плакал по многим причинам: что меня бил отец, что отец бил мать, что я избил друга и что так нелепо получилось, что насилие родилось из обычных мечтаний. И что же тогда делать? Не мечтать?"}, {"kind": "paragraph", "text": "Но это ведь невозможно. А раз уж это невозможно — то нужно избавиться от того, что вызывает насилие."}, {"kind": "paragraph", "text": "Заброшенная аллея в гетто Готэма. Лужи дождевой воды, разбитые фонари, граффити с символами банд. Бэтмен — уже не молодой, но всё ещё невероятно опасный — стоит перед Лидером Мутантов, огромным, мускулистым монстром с клыками и безумными глазами. Его банда окружила их скандируя, с жаждой крови."}, {"kind": "paragraph", "text": "Лидер Мутантов смеётся, называет Бэтмена «стариком». Бэтмен молчит."}, {"kind": "paragraph", "text": "Первый удар — за Лидером: он бросается, как зверь, кулак летит в голову. Бэтмен уклоняется, но не полностью — удар скользит по плечу, отбрасывая его назад. Он чувствует возраст, но боль — это топливо."}, {"kind": "paragraph", "text": "Он контратакует: резкий удар в колено, локтем в солнечное сплетение. Лидер Мутантов даже не кряхтит — просто бьёт снова. Бэмс! Шмак! Бах! Бэтмен падает в грязь, кровь на губах."}, {"kind": "paragraph", "text": "Банда ревёт."}, {"kind": "paragraph", "text": "Но Бэтмен не сдаётся. Он использует окружение — отталкивается от стены, бьёт ногой в челюсть. Лидер Мутантов шатается. Бэтмен хватает обломок трубы — и ломает её о голову врага."}, {"kind": "paragraph", "text": "Тот падает."}, {"kind": "paragraph", "text": "Тишина."}, {"kind": "paragraph", "text": "Банда в ужасе отступает."}, {"kind": "paragraph", "text": "Бэтмен, тяжело дыша, поднимается. Он не убил его. Но он победил."}, {"kind": "paragraph", "text": "Я хочу быть как Бэтмен! Я хочу тоже быть непобеждённым! Я хочу бороться со злом! Да, несмотря ни на что, я буду бороться! Я истреблю всё зло в своей жизни!"}, {"kind": "paragraph", "text": "...Маленький мальчик бросил комикс на пол и побежал в маленькую комнату. Найдя там молоток, он вернулся, снова прочитал последнюю страницу комикса, чтобы набраться уверенности, — будто выпить стакан водки — подошёл к своему столу, поставил на него свою проклятую руку, поднял другую руку с молотком, которой не коснулось насилие, и снова посмотрел на проклятую."}, {"kind": "paragraph", "text": "Да, это правильно! Он знает, что делает! Ведь он — Бэтмен!"}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
11	mrd6-sotnya-besnuyuschihsya-urodov	Сотня беснующихся уродов	49	mrd6/mrd6-sotnya-besnuyuschihsya-urodov.png	data:image/jpeg;base64,	Дверь Лелюков открывать не спешил, потому что Лелюкову было страшно. За дверью бесновалась сотня уродов, и это точно была не та компания, в которой ему хотелось провести остаток вечера.	[{"kind": "image", "path": "mrd6/mrd6-sotnya-besnuyuschihsya-urodov.png", "caption": "Иллюстрация Маргариты Царевой при помощи Midjourney"}, {"kind": "paragraph", "text": "Дверь Лелюков открывать не спешил, потому что Лелюкову было страшно. За дверью бесновалась сотня уродов, и это точно была не та компания, в которой ему хотелось провести остаток вечера."}, {"kind": "paragraph", "text": "Несмотря на сорок лет жизни, Лелюков совершенно не знал, как себя следует вести с уродами. Не знал, о чём с ними можно говорить и нужно ли говорить вообще."}, {"kind": "paragraph", "text": "И вот, однако же, эти самые уроды были прямо здесь — за его дверью. Более того, пригласил их сюда сам Лелюков. А значит, как ни крути, дверь уродам он должен был открыть. И Лелюков это прекрасно понимал."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "В детстве, лет до семи, родители не разрешали Лелюкову смотреть на уродов."}, {"kind": "paragraph", "text": "«Славик, закрой глаза! — говорили они каждый раз, когда уроды оказывались где-нибудь поблизости. — Здесь уроды! Не нужно на них смотреть!»"}, {"kind": "paragraph", "text": "И маленький Лелюков послушно закрывал глаза. На самом деле ему не было страшно, но даже в таком юном возрасте он понимал, что смотреть на уродов действительно как бы незачем. Достаточно было знать, что они существуют, что их вокруг не так уж и мало, что все они страшные, но в большинстве своём совершенно безобидные."}, {"kind": "paragraph", "text": "Чуть позже, когда Лелюков пошёл в школу, отец начал потихоньку разрешать ему посматривать на уродов. Издалека, краем глаза и недолго."}, {"kind": "paragraph", "text": "«Это жизнь, — отвечал он на возражения матери, которая считала, что так рано на уродов смотреть не следует. — Пусть потихоньку привыкает!»"}, {"kind": "paragraph", "text": "Ну а где-то годам к десяти смотреть на уродов Лелюкову разрешила и мать."}, {"kind": "paragraph", "text": "«Только не увлекайся!» — предупредила она Лелюкова, ласково погладив его рыжую шевелюру и нежно поцеловав в лоб."}, {"kind": "paragraph", "text": "Несмотря на обретённую свободу взглядов, Лелюков не испытывал особого желания смотреть на уродов. И даже значительно позже, уже будучи подростком и постигая в одном из ПТУ основы гидравлики сельскохозяйственной техники, он изучал курс уродоведения настолько поверхностно, насколько это допускалось минимальным пропускным баллом, а самих уродов по-прежнему предпочитал обходить стороной."}, {"kind": "paragraph", "text": "Ну а потом… Потом была самая обычная жизнь, со всеми её заботами, радостями, первой любовью, женитьбой, разочарованиями, взаимными упрёками, громким разводом, возвратом в родительскую двушку, ну и всё с теми же уродами, которые попадались на глаза всё чаще и чаще, вынуждая Лелюкова всё чаще эти самые глаза закрывать."}, {"kind": "paragraph", "text": "Что Лелюков и делал вплоть до самого недавнего времени."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Самое недавнее время началось сразу же после того, как однажды за ужином мать с нескрываемым упрёком спросила отца:"}, {"kind": "paragraph", "text": "— Ну что, наразрешался Славику смотреть на уродов с семи лет?!"}, {"kind": "paragraph", "text": "— А что такого? — насторожился отец."}, {"kind": "paragraph", "text": "— Испугал ребёнка. Неужели не видишь — он до сих пор на уродов не смотрит!"}, {"kind": "paragraph", "text": "— Как это не смотрит?! Смотрит! Слава, ты на уродов смотришь?"}, {"kind": "paragraph", "text": "— Смотрю, — спокойно ответил Лелюков."}, {"kind": "paragraph", "text": "— Как же, смотришь, — вздохнула мать. — Всю жизнь их стороной обходишь."}, {"kind": "paragraph", "text": "— Не самая плохая идея, между прочим, — попытался отшутиться отец, но его шутка не произвела ожидаемого впечатления."}, {"kind": "paragraph", "text": "— Ты что это говоришь, пень старый?! — взорвалась мать. — Это тебе от уродов на расстоянии держаться можно — возраст, как-никак, пенсия. А Славику как дальше жить?!"}, {"kind": "paragraph", "text": "— Да всё в порядке, мам, — снова попытался вмешаться Лелюков, но мать уже было не остановить."}, {"kind": "paragraph", "text": "— А ты не встревай! Кругом уроды эти! И закрывать глаза на них нельзя! А ты…"}, {"kind": "paragraph", "text": "Мать заплакала, отец с мрачным видом снова погрузился в газетные отчёты о ходе уборочной, хотя, кажется, расстраивал его вовсе не низкий темп намолота зернобобовых."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Всю ночь Лелюков провёл без сна, а под утро решил обсудить своё отношение к уродам с напарником (и в какой-то степени другом) Сашкой Будылиным — человеком, который всю жизнь проработал на заводе и в силу этого неплохо разбирался в уродах."}, {"kind": "paragraph", "text": "— Сань, а ты вообще как к уродам относишься? — спросил он Сашку в разгар смены (чтобы вопрос не выглядел слишком откровенным и не сильно выделялся на фоне цехового грохота)."}, {"kind": "paragraph", "text": "— Да обычно отношусь, как все, — ответил напарник, уверенно загоняя кувалдой гильзу гидроцилиндра в корпус формовочной машины. — А ты это чего вдруг об уродах заговорил?"}, {"kind": "paragraph", "text": "— Да так, — пожал плечами Лелюков. — Намекнули мне давеча, будто не всё у меня гладко в отношениях с уродами."}, {"kind": "paragraph", "text": "— Ха, ну ты даёшь! — захохотал в голос напарник, выронив из рук кувалду и схватившись руками за живот. — Ты серьёзно?! Намекнули тебе? Да каждая собака знает, что ты уродов терпеть не можешь! И они сами, кстати говоря, от этого не в восторге!"}, {"kind": "paragraph", "text": "— Да нормально я к ним отношусь, — смутился Лелюков."}, {"kind": "paragraph", "text": "— Ага, но когда увидишь кого-нибудь из уродов, обязательно на другую сторону улицы переходишь или взгляд отводишь. Да ладно, ты не красней! Не мне тебя упрекать, не мне тебя воспитывать. Живи как хочешь. Хотя…"}, {"kind": "paragraph", "text": "Напарник снова разразился приступом искреннего смеха."}, {"kind": "paragraph", "text": "И если насмешливое наплевательство Будылина в отношении своей персоны Лелюков мог легко объяснить тем, что подобным образом Сашка относился вообще ко всем на свете (он сам был трижды женат, трижды разведён, но при этом не собирался придавать своим неудачам характер судьбоносных катастроф), то слова о каждой собаке вызвали у Лелюкова неприятное и даже тревожное чувство, как это бывает, когда что-то тайное становится явным или когда вдруг выясняется, что это тайное на самом деле таковым никогда не являлось."}, {"kind": "paragraph", "text": "Стоило Лелюкову чуть внимательнее осмотреться вокруг, и он вынужден был признать, что большинство людей вовсе не избегает уродов."}, {"kind": "paragraph", "text": "Так, сразу после обеда Лелюков собственными глазами наблюдал, как несколько шлифовщиц соседнего цеха по пути из столовой весело общались сразу с четырьмя уродами. При этом женщины совершенно не стеснялись отпускать в адрес уродов весьма смелые шутки, но самих уродов это обстоятельство совершенно не расстраивало и даже, наоборот, доставляло очевидное удовольствие. Широко раскрыв рты, уроды увлечённо семенили за женщинами и сопровождали каждую шутку тяжёлым гортанным смехом."}, {"kind": "paragraph", "text": "Начальник сборки Мазуркевич демонстративно прикармливал уродов батоном у транспортных ворот (чтобы те не толпились у пандуса СГД и не мешали отгрузке продукции), напоминал им о важности соблюдения правил приемлемой гигиены, рассказывал о своих дачных достижениях, обещал «как-нибудь в другой раз» принести уродам яблок и вообще общался с ними, будто со своими подчинёнными: назидательно, уверенно и при этом ни к чему себя не обязывая."}, {"kind": "paragraph", "text": "Кладовщицы Клава и Зина сердобольно отдавали уродам списанные комплекты спецодежды, которые те натягивали на себя, не обращая внимания на размеры и количество рукавов (у многих уродов было три руки, и, к своему стыду, Лелюков заметил это только сегодня), благодарили кладовщиц громкими ломаными, частично понятными фразами."}, {"kind": "paragraph", "text": "В общем, ближе к концу рабочего дня Лелюков вынужден был признать: большинство людей прекрасно уживается с уродами и уж тем более не закрывает при встрече с ними глаза."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Уже вечером измученное непривычно долгим наблюдением за уродами сознание Лелюкова смогло успокоиться и собрать все полученные за день данные в один очень важный и сложный вопрос."}, {"kind": "paragraph", "text": "Важность его заключалась в том, что он касался самых дальних душевных закоулков Лелюкова, а сложность — в том, что сам Лелюков, как человек, чьи жизненные взгляды во многом основывались на закрытых глазах, ответить на этот вопрос совершенно точно не мог. Здесь нужен был посторонний человек, готовый оценивать внутренние переживания Лелюкова исключительно со внешних и при этом далеко не самых снисходительных позиций."}, {"kind": "paragraph", "text": "К счастью, такой человек на примете у Лелюкова был."}, {"kind": "paragraph", "text": "— Лена, — осторожно сказал он, когда в телефонной трубке послышался сонный голос бывшей супруги. — Лен, ты послушай, я вот тут думал…"}, {"kind": "paragraph", "text": "— Господи, о чём ты там думал, в час ночи-то?"}, {"kind": "paragraph", "text": "— Да так... О себе, о тебе, о нас, об уродах. Слушай, Лен, а может, у нас в итоге ничего не получилось только потому, что я не особенно люблю смотреть на уродов?"}, {"kind": "paragraph", "text": "— Нашёл время… — вздохнула бывшая."}, {"kind": "paragraph", "text": "— Нет, Лен, не сердись. Ответь честно."}, {"kind": "paragraph", "text": "— Ну да, — неожиданно спокойно ответила бывшая."}, {"kind": "paragraph", "text": "— Ты мне об этом никогда не говорила."}, {"kind": "paragraph", "text": "— Ну, не говорила и не говорила. В чём проблема?"}, {"kind": "paragraph", "text": "— Всё-таки не один год прожили вместе. Могла бы и сказать."}, {"kind": "paragraph", "text": "— Могла, не могла… Какая теперь разница? Ты ведь уродов всегда как чёрт ладана боялся."}, {"kind": "paragraph", "text": "— Да не боюсь я их... Просто не люблю смотреть на уродов, только и всего, — попытался оправдаться Лелюков. — А так, в целом, ничего против них не имею."}, {"kind": "paragraph", "text": "— Так не бывает, когда не можешь на что-то смотреть и при этом ничего против не имеешь. Вот скажи, когда ты в последний раз общался с кем-нибудь из уродов?"}, {"kind": "paragraph", "text": "— Общался? — переспросил Лелюков."}, {"kind": "paragraph", "text": "— Ну да. Разговаривал, спрашивал, как дела, шутки шутил?"}, {"kind": "paragraph", "text": "— Не помню."}, {"kind": "paragraph", "text": "— Вот видишь. А уроды всегда рядом, хочешь ты этого или нет. Такова реальная жизнь. И ты к ней совершенно не приспособлен. Вот об этом, между прочим, я тебе говорила, и даже не раз."}, {"kind": "paragraph", "text": "Телефон отключился. Разговор был окончен, а вместе с ним, как понял Лелюков, была окончена и та часть его жизни, в которой уроды оставались где-то далеко на периферии внимания. Теперь их роль должна была измениться. Измениться коренным образом."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "На следующий день, отработав смену, по пути из гардероба к проходной Лелюков заметил возле ворот покрасочного цеха одного из заводских уродов. Урод был не особенно страшен, местами одет, выглядел достаточно понятливым. Но главное — он был один, а значит, прекрасно подходил для того, чтобы начать «внутреннюю жизнь со внешних позиций», как это ловко сформулировал для себя сам Лелюков."}, {"kind": "paragraph", "text": "— Привет! С тобой можно поговорить? — спросил он, осторожно приблизившись к уроду."}, {"kind": "paragraph", "text": "— Ну даваи-и-и-и! — ответил урод, недоверчиво покосившись на Лелюкова."}, {"kind": "paragraph", "text": "— Как дела?"}, {"kind": "paragraph", "text": "— Нар-р-р-р-мально, — ответил урод."}, {"kind": "paragraph", "text": "— Ясно... А как жизнь вообще?"}, {"kind": "paragraph", "text": "На этот раз урод промолчал, неопределённо пожав плечами и устремив свой взгляд куда-то за спину Лелюкову."}, {"kind": "paragraph", "text": "Скорее всего, разговор просто наскучил уроду. Лелюков слышал, что уроды не умеют долго концентрировать своё внимание на том, что их не интересует. При этом вспомнить, что вызывает их устойчивый интерес, Лелюков вот так сразу не мог. Кажется, уроды любили кучковаться, но в данный момент от подобного знания толку было мало — кучковаться с уродом Лелюкову совершенно не хотелось. Да и заниматься этим уроды, кажется, предпочитали исключительно в компании своих собратьев. Если не изменяла память, они ещё любили сухие салаты, но таковых при себе Лелюков не имел."}, {"kind": "paragraph", "text": "В тот момент, когда урод полностью потерял к нему интерес и снова принялся бесцельно трястись, Лелюкова вдруг осенило: он вспомнил, что уроды больше всего на свете любят вечеринки. Вечеринки, дискотеки, различного рода тусовки и утренники. Это был шанс вернуть интерес урода, и Лелюков решил этим шансом воспользоваться, тем более что его старики надёжно съехали на дачу и у Лелюкова появилась возможность устраивать вечеринки, сколько Лелюкову хотелось (пусть даже ему и не хотелось этого вовсе)."}, {"kind": "paragraph", "text": "— А я вот подумываю сегодня вечером у себя вечеринку закатить, — осторожно сказал Лелюков."}, {"kind": "paragraph", "text": "На этот раз он попал в самую точку. Услышав заветное слово, урод тут же принялся трястись, щёлкать языком и жадно ловить ноздрями воздух."}, {"kind": "paragraph", "text": "— Вечиринку-у-у? — переспросил он, глядя Лелюкову прямо в глаза и всем своим взъерошенным видом выражая полнейшую заинтересованность."}, {"kind": "paragraph", "text": "— Да, вечеринку. Вот думаю, кого бы пригласить. Ты бы ко мне пришёл?"}, {"kind": "paragraph", "text": "— А дру-у-у-зей пр-и-и-и-гласи-и-и-и-ть м-м-можно? — с надеждой поинтересовался урод."}, {"kind": "paragraph", "text": "«Ну, пути назад у меня нет!» — отважно подумал Лелюков."}, {"kind": "paragraph", "text": "— Друзья точно не помешают! Какая же вечеринка без друзей? Буду только рад! — уверенно сказал он."}, {"kind": "paragraph", "text": "Урод подпрыгнул на месте, несколько раз широко взмахнул руками, после чего бодро поковылял в направлении заводской столовой."}, {"kind": "paragraph", "text": "— Ты это куда? — спросил Лелюков, не ожидавший от урода такой прыти."}, {"kind": "paragraph", "text": "— Друз-з-з-зьям рас-с-сказать! — на ходу выкрикнул урод, жестами призывая Лелюкова следовать за ним."}, {"kind": "paragraph", "text": "Следовать пришлось довольно быстро. Несмотря на хромоту, урод передвигался стремительно — Лелюкову временами приходилось переходить даже на лёгкий бег, и он старался не отставать. Точка невозврата была пройдена, а само общение с уродом оказалось не таким уж и сложным."}, {"kind": "paragraph", "text": "Зато теперь любой работник предприятия мог воочию убедиться, что Лелюков вовсе не чурается общества уродов и даже вот так, вполне открыто, держит путь куда-то вместе с одним из них."}, {"kind": "paragraph", "text": "Расчёт Лелюкова оправдал себя сразу и вполне. Проходивший мимо расточник Слава, заметив Лелюкова в компании с уродом, застыл на месте и даже от удивления приоткрыл рот, из которого на землю вывалилась папироса."}, {"kind": "paragraph", "text": "— Лель, ты это куда? — спросил он. — Да ещё с уродом?!"}, {"kind": "paragraph", "text": "— Да так, дела, — бодро ответил Лелюков, прибавляя шагу. Урод успел оторваться метров на двадцать и уже подходил к группе других уродов, толпившихся у входа в столовую. Уродов было шестеро, и Лелюкова это немного расстроило — всё-таки он рассчитывал ограничиться вечеринкой с двумя-тремя уродами, но теперь об этом уже не могло быть и речи."}, {"kind": "paragraph", "text": "Стремительно проникнув в самую гущу своих собратьев, урод принялся им что-то нашёптывать. Он радостно трогал их за плечи, вздрагивал, многозначительно кивал в сторону Лелюкова."}, {"kind": "paragraph", "text": "— А поесть чё там у тебя будет? — выковыляв из толпы, спросил Лелюкова ещё один урод, усиленно тряся кадыком и приглаживая языком космы взъерошенных волос."}, {"kind": "paragraph", "text": "— А что вы любите?"}, {"kind": "paragraph", "text": "— Салаты!!! Сухие салаты!!! — выкрикнули уроды хором."}, {"kind": "paragraph", "text": "— Будут, будут вам салаты."}, {"kind": "paragraph", "text": "— А музыка?"}, {"kind": "paragraph", "text": "— Магнитофон у меня. Panasonic. Не слишком большой, но…"}, {"kind": "paragraph", "text": "— Годится! — выкрикнул кто-то из уродов, после чего вся компания поддержала своего товарища одобрительными возгласами."}, {"kind": "paragraph", "text": "Назвав уродам свой адрес и попросив явиться часам к семи, не раньше, Лелюков направился к остановке, опасаясь, как бы радостные выкрики его новоиспечённых знакомых не привлекли внимания других уродов."}, {"kind": "paragraph", "text": "«Семи уродов для вечеринки вполне достаточно, — рассуждал он по пути. — И даже более чем!»"}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "На остановке Лелюкова нагнал Сашка Будылин. К удивлению Лелюкова, он уже был в курсе запланированной вечеринки, при этом выглядел непривычно серьёзным и даже взволнованным."}, {"kind": "paragraph", "text": "— Так ты и вправду решил уродам вечеринку закатить? — поинтересовался он у Лелюкова. — Я думал, мужики в гардеробе просто так болтают…"}, {"kind": "paragraph", "text": "— А почему бы и нет? Ты же и сам мне говорил, что у меня не всё с уродами, как у других людей. Вот я и решился."}, {"kind": "paragraph", "text": "— А зачем ты их всех пригласил?"}, {"kind": "paragraph", "text": "— Почему всех? Семерых."}, {"kind": "paragraph", "text": "— Ну так это считай, что всех. Они сейчас друг другу расскажут, по заводу разнесут. А по пути ещё всех встречных подхватят. Уроды по-другому не могут."}, {"kind": "paragraph", "text": "— Серьёзно, что ли? — с тревогой спросил Лелюков."}, {"kind": "paragraph", "text": "— Конечно! Когда речь заходит о вечеринке, уроды первым делом теряют концепцию личностной самоидентификации. Об этом даже на уроках в школе рассказывают. Если собираешься устроить вечеринку с участием уродов, приглашать их нужно совсем не так."}, {"kind": "paragraph", "text": "— А как?"}, {"kind": "paragraph", "text": "— Ну, берёшь парочку — тех, что поближе к дому, — и тащишь сразу к себе, чтобы они другим сообщить не успели."}, {"kind": "paragraph", "text": "— Твою мать! — выругался Лелюков."}, {"kind": "paragraph", "text": "— Ну, теперь пути назад нет, — сочувственно произнёс Будылин. — Сотня, а то и больше, точно припрётся."}, {"kind": "paragraph", "text": "— Они ж все у меня в квартире не поместятся."}, {"kind": "paragraph", "text": "— Плохо ты уродов знаешь. А если и вправду не влезут, так на лестничной площадке побеснуются. Да ладно, ты уж не раскисай! Смотри на это с другой стороны: после вечеринки больше никто не скажет, что ты уродов избегаешь, правда? Да и сами уроды будут считать тебя своим."}, {"kind": "paragraph", "text": "— В смысле — побеснуются? Я не хочу, чтобы они бесновались, — побледнев, прошептал Лелюков."}, {"kind": "paragraph", "text": "О том, что иногда уроды начинают бесноваться, он когда-то мимоходом слышал. И пусть Лелюков не знал в точности, что именно означает эта фраза, предельная откровенность формулировки не оставляла сомнений в характере грозящей квартире опасности."}, {"kind": "paragraph", "text": "— Если будет сотня или около того — беснования не избежать. Крепись! — постарался поддержать Лелюкова Будылин и, похлопав его по плечу, направился к подъехавшему к остановке троллейбусу."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "После разговора с Будылиным Лелюков некоторое время стоял неподвижно, придавленный внезапным осознанием того, что всего через каких-нибудь полтора часа он окажется в самой гуще беснующихся уродов, о которых по-прежнему ничего не знает."}, {"kind": "paragraph", "text": "К счастью, в ближайшем газетном киоске нашлась карманная энциклопедия об уродах, обложка которой бравурно утверждала, что любой человек при помощи данного справочника всего за каких-то полчаса узнает об уродах решительно всё, что только нужно, даже если до этого он не видел их вовсе."}, {"kind": "paragraph", "text": "Книга и вправду оказалась весьма познавательной."}, {"kind": "paragraph", "text": "За расстояние между Кировоградской и Кацедальной, которое троллейбус преодолел минут за двадцать, Лелюков и вправду узнал об уродах много нового. В частности, что в отношении уродов принципиально важно не нарушать данного им слова, особенно если дело касается вечеринок и еды."}, {"kind": "paragraph", "text": "«Если вы что-то обещаете уроду, ни в коем случае не нарушайте своего обещания, — легко и даже как-то издевательски доступно объяснял справочник. — Все уроды легко ранимы и мнительны. В случае глубоких разочарований у уродов стремительно происходит процесс озлобления на окружающих, нередко принимающий агрессивные формы проявления. Поэтому данное уродам слово нужно выполнять всегда и без исключений. Согласитесь: меньше всего нашему обществу нужны озлобленные и агрессивные уроды»."}, {"kind": "paragraph", "text": "Процессу беснования в справочнике также отводилась пара строк, в которых утверждалось, что беснование мало чем отличается от обычного поведения уродов, если не принимать в расчёт повышенную крикливость и растущий в геометрической прогрессии уровень антисанитарии, который чаще всего выражается в виде активной линьки. Ввиду этого авторы пособия настоятельно рекомендовали не пренебрегать простейшими мерами, направленными на снижение последствий беснования уродов. В частности, они советовали не скупиться на организацию праздничного антуража (флажков, конфетти и угощения), к которому уроды были особенно восприимчивы. И хотя интенсивность линьки уродов от этого, по признанию самих авторов, особенно не зависела, по их словам, «будет гораздо лучше, если мероприятие беснующимся уродам понравится, нежели наоборот»."}, {"kind": "paragraph", "text": "Заскочив по пути в гастроном и закупившись на все деньги флажками, конфетти и сухими салатами, Лелюков прибежал домой и принялся лихорадочно украшать комнату, почитывая на ходу справочник и бросая тревожные взгляды на настенные часы."}, {"kind": "paragraph", "text": "До прибытия уродов оставалось менее часа, а значит, следовало поторопиться. Тот же справочник уверенно утверждал, что уроды, не способные при иных обстоятельствах воспринимать саму концепцию времени, на вечеринки являются всегда точно в срок, демонстрируя завидную ориентировку на местности и чудеса картографической памяти."}, {"kind": "paragraph", "text": "Наконец, завершив свои судорожные приготовления, Лелюков вышел на балкон и, нервно закурив папиросу, принялся с опаской поглядывать во двор. Робкая надежда, что в случае с его вечеринкой уродам всё же не удастся проявить своих лучших качеств и они попросту не найдут его квартиру, улетучилась неприглядно быстро: ровно без пяти минут семь из-за соседнего дома показалась весёлая ватага уродов, которая направлялась к подъезду Лелюкова."}, {"kind": "paragraph", "text": "Как и предупреждал Будылин, уродов действительно было где-то около сотни. Все они радостно махали руками, подпрыгивали и, кажется, уже прямо сейчас начинали бесноваться — их нестройная колонна местами сливалась в единую клокочущую массу, явно готовую к линьке и безудержному веселью."}, {"kind": "paragraph", "text": "И всего через пару минут эта масса должна была оказаться прямо здесь, в украшенной флажками квартире Лелюкова. Человека, всю жизнь избегавшего уродов."}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "Когда в двери начали стучать и звонить, Лелюков впал в ступор. Приникнув к дверному глазку, он молча наблюдал сменяющиеся физиономии уродов. Те отталкивали друг друга от двери и норовили заглянуть в глазок со своей стороны."}, {"kind": "paragraph", "text": "— Открывай! — выкрикивали уроды."}, {"kind": "paragraph", "text": "— Давай, открывай!"}, {"kind": "paragraph", "text": "— Открывай! Открывай!"}, {"kind": "paragraph", "text": "— Да открывай же уже!"}, {"kind": "paragraph", "text": "— Открывай! Время начинать вечеринку!"}, {"kind": "paragraph", "text": "Оторвавшись от дверного глазка, Лелюков обречённо обвёл взглядом родительскую квартиру, впервые в жизни перекрестился и медленно протянул руку к дверному замку. Он понимал, что настал тот самый момент, когда он должен открыть дверь и впустить уродов на свою вечеринку, совершив тем самым первый шаг навстречу новой и теперь уже совершенно нормальной жизни."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
12	mrd6-derevo	Дерево	50	mrd6/mrd6-derevo.png	data:image/jpeg;base64,	* * *	[{"kind": "image", "path": "mrd6/mrd6-derevo.png", "caption": "Иллюстрация Маргариты Царевой при помощи Midjourney"}, {"kind": "paragraph", "text": "* * *"}, {"kind": "paragraph", "text": "На голове и руках шуршит сухая листва, тело в онемении застыло, вросло глубоко в землю. Я — дерево. Вокруг скачут маленькие дети. Все веселятся, хороводят, готовятся к большому празднику. У каждого по игрушке, в основном плюшевой: мишки, зайчики, волчата… Звонкий детский смех скрипит стержнем сухого фломастера."}, {"kind": "paragraph", "text": "Из корпуса детского сада выходит воспитательница, и настроение детей резко меняется: лица их становятся серьёзнее, все выстраиваются в колонну по одному возле меня и внимательно слушают. Она раздаёт каждому ребёнку по паре рукавиц, солнцезащитные очки и фартук. Прошла в начало колонны, достала из передника разделочный нож. Ай! Нож прошёл через сухую кору и остался в стволе."}, {"kind": "paragraph", "text": "— Ребята, — выдёргивает и ещё раз с силой вгоняет между ребристых волокон, — каждый из вас по очереди должен сделать так же. Не забудьте оставить мягкого друга, бедняге не будет так одиноко. А теперь достаём колючки и-и-и-и-и-и, — протяжным стоном, с усилием дёргая за рукоять, — начали!"}, {"kind": "paragraph", "text": "По мне расползаются мелкие порезы, царапины, вмятины, ничего не могу поделать: корни глубоко в земле. Ширк-ширк-ширк! Из-под коры струится смола. Мальчик, только что ткнувший в меня шилом, хватается за низкую ветку и с силой дёргает её на себя. Скр-р-р-п. Листья падают на землю. Из места, где переломилась ветка, начинает течь кровь. Шурх."}, {"kind": "paragraph", "text": "— Ты что такое делаешь? Кто разрешал висеть на ветвях? Это тебе не качели. А ну, быстро слезь! — воспитательница дёрнулась с места и стащила мальчика на землю. — Дети, не трогайте ветки и листья! Они ядовиты, они пусты, в них нет жизни!"}, {"kind": "paragraph", "text": "Когда в меня робко вонзилась последняя иголочка, у корней выстроилась уже целая армия старых игрушек. Детские крики куда-то пропали. У-у-у-у. Налетел сильный ветер, игрушки зашевелились. Они стали плотно цепляться друг за друга, образуя плюшевый ураган, мягкий хороводоворот."}, {"kind": "paragraph", "text": "Мишки, зайчики, волчата, лисички, слоники, щенята и прочие, прочие звери, пыльные и грязные, вырваны глаза и обгрызены уши, забесновались в каком-то диком прерывистом танце, всё время сужая круг и подступая всё ближе к стволу, пока окончательно не прижались, образовав тесную цепь."}, {"kind": "paragraph", "text": "Ветер вскоре стих, вокруг снова засуетилась малышня. В этот раз вместе с воспитательницей вышел ещё один человек — дворник. В руках у него не было ни метлы, ни совка, ни даже ножниц. Он тащил большую канистру."}, {"kind": "paragraph", "text": "— Дети, отойдите подальше и наденьте очки, — скомандовала воспитательница."}, {"kind": "paragraph", "text": "Дворник принялся выливать содержимое канистры на ствол и ветки. Горючее вещество соприкасалось со смолой, образуя ужасный едкий запах. Залил землю и игрушки. Тёмно-жёлтые, как я. Бензин питает корни, крону кружит, кренит."}, {"kind": "paragraph", "text": "Чиркнула спичка. Высокая огненная стена выстроилась. Сменяющие друг друга одинаково поющие детские лица спрятались под очками. Раны коптятся. Закручиваются в сплошной треск-хруст. Ш-ш-ш."}, {"kind": "paragraph", "text": "Рассказ победителя пятого сезона конкурса рок-прозы «Гроза»."}]	2026-01-20 12:00:00+00	2026-06-09 14:52:07.972255+00	1381	797	10
